const PRODUCTS_STORAGE_KEY = "hogarflex_products";

// Variables del módulo de productos
let currentProductPhotoBase64 = "";
let productPendingDeleteId = null;

function getStoredProducts() {
  try {
    const data = localStorage.getItem(PRODUCTS_STORAGE_KEY);
    return data ? JSON.parse(data) : [];
  } catch (err) {
    console.error("Error al cargar productos de localStorage:", err);
    return [];
  }
}

function saveProductsToStorage(products) {
  try {
    localStorage.setItem(PRODUCTS_STORAGE_KEY, JSON.stringify(products));
    triggerAutoCloudBackup("productos");
  } catch (err) {
    console.error("Error al guardar productos en localStorage:", err);
    alert("No se pudo guardar el producto. Espacio de almacenamiento lleno.");
  }
}

function initProductsModule() {
  const btnOpenAddProduct = document.getElementById("btn-open-add-product");
  const productModal = document.getElementById("product-modal");
  const btnCloseModal = document.getElementById("btn-close-modal");
  const btnCancelProduct = document.getElementById("btn-cancel-product");
  const productForm = document.getElementById("product-form");
  const productPhotoInput = document.getElementById("product-photo-input");

  // Elementos del modal de confirmación de eliminación
  const deleteModal = document.getElementById("delete-modal");
  const btnCloseDeleteModal = document.getElementById("btn-close-delete-modal");
  const btnCancelDelete = document.getElementById("btn-cancel-delete");
  const btnConfirmDelete = document.getElementById("btn-confirm-delete");
  const productsTbody = document.getElementById("products-tbody");

  if (!btnOpenAddProduct || !productModal || !productForm) return;

  // Abrir modal para agregar
  btnOpenAddProduct.addEventListener("click", () => {
    openAddProductModal();
  });

  // Cerrar modal con botón cruz o botón Cancelar
  btnCloseModal.addEventListener("click", closeProductModal);
  btnCancelProduct.addEventListener("click", closeProductModal);

  // Cerrar modal al hacer clic en el fondo oscuro
  productModal.addEventListener("click", (e) => {
    if (e.target === productModal) {
      closeProductModal();
    }
  });

  // Escuchadores del modal de confirmación de eliminación
  if (btnCloseDeleteModal) btnCloseDeleteModal.addEventListener("click", closeDeleteProductModal);
  if (btnCancelDelete) btnCancelDelete.addEventListener("click", closeDeleteProductModal);
  if (btnConfirmDelete) btnConfirmDelete.addEventListener("click", executeDeleteProduct);
  if (deleteModal) {
    deleteModal.addEventListener("click", (e) => {
      if (e.target === deleteModal) {
        closeDeleteProductModal();
      }
    });
  }

  // Delegación de eventos en la tabla para Editar y Eliminar (robusto para móviles y re-renderizados)
  if (productsTbody) {
    productsTbody.addEventListener("click", (e) => {
      const editBtn = e.target.closest(".btn-action-edit");
      if (editBtn) {
        e.preventDefault();
        const id = editBtn.getAttribute("data-id");
        openEditProductModal(id);
        return;
      }

      const deleteBtn = e.target.closest(".btn-action-delete");
      if (deleteBtn) {
        e.preventDefault();
        const id = deleteBtn.getAttribute("data-id");
        openDeleteProductModal(id);
        return;
      }
    });
  }

  // Cambio de foto
  productPhotoInput.addEventListener("change", handlePhotoUpload);

  // Envío del formulario (Guardar)
  productForm.addEventListener("submit", handleProductFormSubmit);

  // Render inicial
  renderProducts();
}

// Manejar compresión y lectura de foto desde dispositivo
function handlePhotoUpload(e) {
  const file = e.target.files[0];
  const previewImg = document.getElementById("photo-preview-img");
  const placeholder = document.getElementById("photo-preview-placeholder");

  if (!file) return;

  const reader = new FileReader();
  reader.onload = function(event) {
    const img = new Image();
    img.onload = function() {
      // Redimensionar para optimizar peso en localStorage (máx 450px)
      const maxDim = 450;
      let width = img.width;
      let height = img.height;

      if (width > height && width > maxDim) {
        height = Math.round((height * maxDim) / width);
        width = maxDim;
      } else if (height > maxDim) {
        width = Math.round((width * maxDim) / height);
        height = maxDim;
      }

      const canvas = document.createElement("canvas");
      canvas.width = width;
      canvas.height = height;
      const ctx = canvas.getContext("2d");
      ctx.drawImage(img, 0, 0, width, height);

      currentProductPhotoBase64 = canvas.toDataURL("image/jpeg", 0.78);

      previewImg.src = currentProductPhotoBase64;
      previewImg.classList.remove("hidden");
      placeholder.classList.add("hidden");
    };
    img.src = event.target.result;
  };
  reader.readAsDataURL(file);
}

// Abrir modal en modo Agregar
function openAddProductModal() {
  const modal = document.getElementById("product-modal");
  const modalTitle = document.getElementById("modal-product-title");
  const form = document.getElementById("product-form");
  const previewImg = document.getElementById("photo-preview-img");
  const placeholder = document.getElementById("photo-preview-placeholder");
  const idInput = document.getElementById("product-id");

  modalTitle.textContent = "Agregar Producto";
  form.reset();
  idInput.value = "";
  currentProductPhotoBase64 = "";

  previewImg.src = "";
  previewImg.classList.add("hidden");
  placeholder.classList.remove("hidden");

  modal.classList.remove("hidden");
  document.getElementById("product-name-input").focus();
}

// Abrir modal en modo Editar
function openEditProductModal(productId) {
  const products = getStoredProducts();
  const product = products.find((p) => String(p.id) === String(productId));
  if (!product) return;

  const modal = document.getElementById("product-modal");
  const modalTitle = document.getElementById("modal-product-title");
  const form = document.getElementById("product-form");
  const idInput = document.getElementById("product-id");
  const nameInput = document.getElementById("product-name-input");
  const priceInput = document.getElementById("product-price-input");
  const qtyInput = document.getElementById("product-qty-input");
  const previewImg = document.getElementById("photo-preview-img");
  const placeholder = document.getElementById("photo-preview-placeholder");

  form.reset();
  modalTitle.textContent = "Editar Producto";
  idInput.value = product.id;
  nameInput.value = product.name;
  priceInput.value = product.price;
  qtyInput.value = (product.quantity !== null && product.quantity !== undefined && product.quantity !== "") ? product.quantity : "";

  currentProductPhotoBase64 = product.photo || "";

  if (currentProductPhotoBase64) {
    previewImg.src = currentProductPhotoBase64;
    previewImg.classList.remove("hidden");
    placeholder.classList.add("hidden");
  } else {
    previewImg.src = "";
    previewImg.classList.add("hidden");
    placeholder.classList.remove("hidden");
  }

  modal.classList.remove("hidden");
  nameInput.focus();
}

// Cerrar modal
function closeProductModal() {
  const modal = document.getElementById("product-modal");
  const form = document.getElementById("product-form");
  modal.classList.add("hidden");
  form.reset();
  currentProductPhotoBase64 = "";
}

// Guardar producto (Nuevo o Editado) - Cantidad es OPCIONAL e INFORMATIVA
function handleProductFormSubmit(e) {
  e.preventDefault();

  const idInput = document.getElementById("product-id");
  const nameInput = document.getElementById("product-name-input");
  const priceInput = document.getElementById("product-price-input");
  const qtyInput = document.getElementById("product-qty-input");

  const nameVal = nameInput.value.trim();
  const priceVal = parseFloat(priceInput.value);
  const qtyStr = qtyInput.value.trim();
  const qtyVal = qtyStr === "" ? null : parseInt(qtyStr, 10);

  if (!nameVal) {
    alert("Por favor ingresa el nombre del producto.");
    return;
  }
  if (isNaN(priceVal) || priceVal < 0) {
    alert("Por favor ingresa un precio válido en USD.");
    return;
  }

  const products = getStoredProducts();
  const isEditing = idInput.value !== "";

  if (isEditing) {
    // Actualizar producto existente
    const index = products.findIndex((p) => String(p.id) === String(idInput.value));
    if (index !== -1) {
      products[index].name = nameVal;
      products[index].price = priceVal.toFixed(2);
      products[index].quantity = qtyVal;
      // Conservar la foto existente si no se subió una nueva
      if (currentProductPhotoBase64) {
        products[index].photo = currentProductPhotoBase64;
      }
      products[index].updatedAt = Date.now();
    }
  } else {
    // Crear nuevo producto
    const newProduct = {
      id: "prod_" + Date.now(),
      name: nameVal,
      price: priceVal.toFixed(2),
      quantity: qtyVal,
      photo: currentProductPhotoBase64 || "",
      createdAt: Date.now()
    };
    products.push(newProduct);
  }

  saveProductsToStorage(products);
  closeProductModal();
  renderProducts();
}

// Abrir modal de confirmación de eliminación
function openDeleteProductModal(productId) {
  productPendingDeleteId = productId;
  const products = getStoredProducts();
  const product = products.find((p) => String(p.id) === String(productId));
  const deleteModal = document.getElementById("delete-modal");
  const deleteModalMsg = document.getElementById("delete-modal-msg");

  if (product && deleteModalMsg) {
    deleteModalMsg.textContent = `¿Estás seguro de que deseas eliminar "${product.name}"?`;
  } else if (deleteModalMsg) {
    deleteModalMsg.textContent = "¿Estás seguro de que deseas eliminar este producto?";
  }

  if (deleteModal) {
    deleteModal.classList.remove("hidden");
  }
}

// Cerrar modal de confirmación de eliminación
function closeDeleteProductModal() {
  const deleteModal = document.getElementById("delete-modal");
  if (deleteModal) {
    deleteModal.classList.add("hidden");
  }
  productPendingDeleteId = null;
}

// Ejecutar eliminación confirmada
function executeDeleteProduct() {
  if (!productPendingDeleteId) return;

  const products = getStoredProducts();
  const updatedProducts = products.filter((p) => String(p.id) !== String(productPendingDeleteId));
  saveProductsToStorage(updatedProducts);
  closeDeleteProductModal();
  renderProducts();
}

// Función compatible directa
function deleteProduct(productId) {
  openDeleteProductModal(productId);
}

// Renderizar la lista de productos
function renderProducts() {
  const tbody = document.getElementById("products-tbody");
  const noProductsMsg = document.getElementById("no-products-msg");
  const table = document.getElementById("products-table");

  if (!tbody || !noProductsMsg || !table) return;

  const products = getStoredProducts();

  if (products.length === 0) {
    table.classList.add("hidden");
    noProductsMsg.classList.remove("hidden");
    tbody.innerHTML = "";
    return;
  }

  table.classList.remove("hidden");
  noProductsMsg.classList.add("hidden");

  tbody.innerHTML = products
    .map((product) => {
      const photoHtml = product.photo
        ? `<img src="${product.photo}" alt="${escapeHtml(product.name)}" class="product-table-img">`
        : `<div class="product-table-no-img" title="Sin imagen">📦</div>`;

      // Campo opcional e informativo: si no tiene cantidad definida, no muestra ese campo
      const hasQty = product.quantity !== null && product.quantity !== undefined && product.quantity !== "";
      let qtyHtml = '<span style="color: var(--color-text-muted); font-weight: 500;">—</span>';
      if (hasQty) {
        const qtyNum = parseInt(product.quantity, 10);
        const qtyBadgeClass = qtyNum <= 0 ? "product-qty-badge out-of-stock" : "product-qty-badge";
        const qtyText = qtyNum <= 0 ? `Disponible: ${qtyNum}` : `${qtyNum} unid.`;
        qtyHtml = `<span class="${qtyBadgeClass}">${qtyText}</span>`;
      }

      return `
        <tr>
          <td class="th-photo">${photoHtml}</td>
          <td class="product-name-cell">${escapeHtml(product.name)}</td>
          <td class="product-price-cell">$${parseFloat(product.price).toFixed(2)}</td>
          <td>
            ${qtyHtml}
          </td>
          <td class="actions-cell">
            <button type="button" class="btn-action-edit" data-id="${product.id}">Editar</button>
            <button type="button" class="btn-action-delete" data-id="${product.id}">Eliminar</button>
          </td>
        </tr>
      `;
    })
    .join("");

  // Asignación directa onclick como respaldo garantizado
  tbody.querySelectorAll(".btn-action-edit").forEach((btn) => {
    btn.onclick = (e) => {
      e.preventDefault();
      const id = btn.getAttribute("data-id");
      openEditProductModal(id);
    };
  });

  tbody.querySelectorAll(".btn-action-delete").forEach((btn) => {
    btn.onclick = (e) => {
      e.preventDefault();
      const id = btn.getAttribute("data-id");
      openDeleteProductModal(id);
    };
  });
}

// Utilidad para prevenir inyección XSS
function escapeHtml(str) {
  if (!str) return "";
  return String(str)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#039;");
}

