function closeClientModal() {
  const modal = document.getElementById("client-modal");
  const form = document.getElementById("client-form");
  const errorMsg = document.getElementById("client-form-error");
  if (modal) modal.classList.add("hidden");
  if (form) form.reset();
  if (errorMsg) {
    errorMsg.style.display = "none";
    errorMsg.textContent = "";
  }
}

// ============================================================
// MODAL DE ADVERTENCIA: CÉDULA/RIF DUPLICADA AL CREAR CLIENTE
// ============================================================
let pendingDuplicateClientCallback = null;

function showDuplicateClientModal(existingClientName, onConfirm) {
  setupDuplicateClientModalEvents();
  const modal = document.getElementById("modal-duplicate-client-confirm");
  const msgEl = document.getElementById("duplicate-client-message");
  const inputEl = document.getElementById("input-duplicate-client-word");
  const btnConfirm = document.getElementById("btn-confirm-duplicate-client");

  if (!modal) {
    if (confirm(`⚠️ Esta cédula/RIF ya existe. Pertenece al cliente: ${existingClientName}. ¿Deseas continuar de todas formas?`)) {
      if (typeof onConfirm === "function") onConfirm();
    }
    return;
  }

  pendingDuplicateClientCallback = onConfirm;

  if (msgEl) {
    msgEl.textContent = `⚠️ Esta cédula/RIF ya existe. Pertenece al cliente: ${existingClientName}. ¿Deseas continuar de todas formas?`;
  }

  if (inputEl) {
    inputEl.value = "";
  }

  if (btnConfirm) {
    btnConfirm.disabled = true;
  }

  modal.classList.remove("hidden");
  if (inputEl) {
    inputEl.focus();
  }
}

function closeDuplicateClientModal() {
  const modal = document.getElementById("modal-duplicate-client-confirm");
  const inputEl = document.getElementById("input-duplicate-client-word");
  const btnConfirm = document.getElementById("btn-confirm-duplicate-client");

  if (modal) modal.classList.add("hidden");
  if (inputEl) inputEl.value = "";
  if (btnConfirm) btnConfirm.disabled = true;
  pendingDuplicateClientCallback = null;
}

function setupDuplicateClientModalEvents() {
  const inputEl = document.getElementById("input-duplicate-client-word");
  const btnConfirm = document.getElementById("btn-confirm-duplicate-client");
  const btnCancel = document.getElementById("btn-cancel-duplicate-client");
  const btnCloseX = document.getElementById("btn-close-duplicate-client-x");
  const modal = document.getElementById("modal-duplicate-client-confirm");

  if (inputEl && !inputEl.dataset.bound) {
    inputEl.dataset.bound = "true";
    inputEl.addEventListener("input", () => {
      const isAccepted = inputEl.value.trim().toLowerCase() === "acepto";
      if (btnConfirm) btnConfirm.disabled = !isAccepted;
    });
    inputEl.addEventListener("keydown", (e) => {
      if (e.key === "Enter") {
        e.preventDefault();
        if (btnConfirm && !btnConfirm.disabled) {
          btnConfirm.click();
        }
      }
    });
  }

  if (btnConfirm && !btnConfirm.dataset.bound) {
    btnConfirm.dataset.bound = "true";
    btnConfirm.addEventListener("click", () => {
      if (inputEl && inputEl.value.trim().toLowerCase() !== "acepto") return;
      const callback = pendingDuplicateClientCallback;
      closeDuplicateClientModal();
      if (typeof callback === "function") {
        callback();
      }
    });
  }

  if (btnCancel && !btnCancel.dataset.bound) {
    btnCancel.dataset.bound = "true";
    btnCancel.addEventListener("click", closeDuplicateClientModal);
  }

  if (btnCloseX && !btnCloseX.dataset.bound) {
    btnCloseX.dataset.bound = "true";
    btnCloseX.addEventListener("click", closeDuplicateClientModal);
  }

  if (modal && !modal.dataset.bound) {
    modal.dataset.bound = "true";
    modal.addEventListener("click", (e) => {
      if (e.target === modal) closeDuplicateClientModal();
    });
  }
}

function handleClientFormSubmit(e) {
  e.preventDefault();

  const idInput = document.getElementById("client-id");
  const dniInput = document.getElementById("client-dni-input");
  const nameInput = document.getElementById("client-name-input");
  const phoneInput = document.getElementById("client-phone-input");
  const addressInput = document.getElementById("client-address-input");
  const errorMsg = document.getElementById("client-form-error");

  const dniVal = dniInput.value.trim();
  const nameVal = nameInput.value.trim();
  const phoneVal = phoneInput.value.trim();
  const addressVal = addressInput.value.trim();

  if (!dniVal || !nameVal || !phoneVal || !addressVal) {
    if (errorMsg) {
      errorMsg.textContent = "Por favor completa todos los campos requeridos.";
      errorMsg.style.display = "block";
    }
    if (typeof addSystemLog === "function") {
      addSystemLog({
        level: "WARNING",
        action: "VALIDATION_ERROR",
        details: { form: "client", reason: "Campos requeridos incompletos", dni: dniVal, name: nameVal },
        status: "failed",
        errorMessage: "Validación fallida: completa todos los campos del cliente"
      });
    }
    return;
  }

  const clients = getStoredClients();
  const isEditing = idInput.value !== "";

  // PARTE 1: Validar si ya existe un cliente con la misma cédula o RIF
  const existingClient = clients.find((c) => {
    if (isEditing && String(c.id) === String(idInput.value)) {
      return false;
    }
    const cDni = String(c.dni || c.cedula || c.rif || "").trim().toLowerCase();
    return cDni === dniVal.toLowerCase();
  });

  const saveClientAction = () => {
    const currentClients = getStoredClients();
    if (isEditing) {
      const index = currentClients.findIndex((c) => String(c.id) === String(idInput.value));
      if (index !== -1) {
        const oldClient = currentClients[index];
        const changedFields = [];
        if (oldClient.dni !== dniVal) changedFields.push({ field: "dni", old: oldClient.dni, new: dniVal });
        if (oldClient.name !== nameVal) changedFields.push({ field: "name", old: oldClient.name, new: nameVal });
        if (oldClient.phone !== phoneVal) changedFields.push({ field: "phone", old: oldClient.phone, new: phoneVal });
        if (oldClient.address !== addressVal) changedFields.push({ field: "address", old: oldClient.address, new: addressVal });

        currentClients[index].dni = dniVal;
        currentClients[index].name = nameVal;
        currentClients[index].phone = phoneVal;
        currentClients[index].address = addressVal;
        currentClients[index].updatedAt = Date.now();

        if (typeof addSystemLog === "function") {
          addSystemLog({
            level: "INFO",
            action: "UPDATE_CLIENT",
            details: { id: oldClient.id, name: nameVal, changedFields },
            status: "success"
          });
        }
      }
    } else {
      const newClient = {
        id: "client_" + Date.now(),
        dni: dniVal,
        name: nameVal,
        phone: phoneVal,
        address: addressVal,
        createdAt: Date.now()
      };
      currentClients.push(newClient);
      if (typeof addSystemLog === "function") {
        addSystemLog({
          level: "INFO",
          action: "CREATE_CLIENT",
          details: { id: newClient.id, name: newClient.name, dni: newClient.dni, date: new Date().toISOString() },
          status: "success"
        });
      }
    }

    saveClientsToStorage(currentClients);
    closeClientModal();
    renderClients();
  };

  if (existingClient && !isEditing) {
    if (typeof addSystemLog === "function") {
      addSystemLog({
        level: "WARNING",
        action: "VALIDATION_ERROR",
        details: { form: "client", reason: "Duplicado de cédula/RIF detectado", dni: dniVal, existingClient: existingClient.name },
        status: "failed",
        errorMessage: `Cédula o RIF ${dniVal} ya pertenece a ${existingClient.name}`
      });
    }
    showDuplicateClientModal(existingClient.name || "Cliente existente", saveClientAction);
    return;
  }

  saveClientAction();
}

function openClientProfileModal(clientId) {
  const clients = getStoredClients();
  const client = clients.find((c) => String(c.id) === String(clientId));
  if (!client) return;

  const modal = document.getElementById("client-profile-modal");
  const nameDisplay = document.getElementById("profile-client-name");
  const dniDisplay = document.getElementById("profile-client-dni");
  const phoneDisplay = document.getElementById("profile-client-phone");
  const addressDisplay = document.getElementById("profile-client-address");

  if (nameDisplay) nameDisplay.textContent = client.name;
  if (dniDisplay) dniDisplay.textContent = `Cédula: ${client.dni}`;
  if (phoneDisplay) phoneDisplay.textContent = client.phone;
  if (addressDisplay) addressDisplay.textContent = client.address;

  // Vincular y renderizar historial de créditos por cédula del cliente
  const historyContainer = document.getElementById("profile-credit-history");
  if (historyContainer) {
    const credits = getStoredCredits();
    const targetDni = client.dni ? String(client.dni).trim().toLowerCase() : "";
    const clientCredits = credits.filter((credit) => {
      const creditDni = credit.client && credit.client.dni ? String(credit.client.dni).trim().toLowerCase() : "";
      const matchByDni = targetDni && creditDni === targetDni;
      const matchById = String(credit.clientId) === String(client.id) || (credit.client && String(credit.client.id) === String(client.id));
      return matchByDni || matchById;
    });

    if (clientCredits.length === 0) {
      historyContainer.innerHTML = `
        <div class="empty-history">
          <p>Sin créditos registrados.</p>
        </div>
      `;
    } else {
      historyContainer.innerHTML = clientCredits.map((cred) => {
        const productsSummary = cred.items && cred.items.length > 0
          ? cred.items.map((it) => `${escapeHtml(it.name)} (x${it.quantity})`).join(", ")
          : "Sin productos detallados";
        const paidCount = cred.installments ? cred.installments.filter((i) => i.status === "Pagada").length : 0;
        const totalCount = cred.installments ? cred.installments.length : 0;
        const statusInfo = getCreditStatus(cred);
        const dateStr = formatDateDisplay(new Date(cred.createdAt || (cred.id ? cred.id.replace("cred_", "") * 1 : Date.now())));

        return `
          <div class="client-credit-card">
            <div style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 6px;">
              <div>
                <span style="font-size: 0.8rem; color: var(--color-text-muted);">${dateStr}</span>
                <strong style="color: var(--color-primary); font-size: 0.95rem; margin-left: 6px;">Crédito #${cred.id.slice(-6)}</strong>
              </div>
              <span class="status-pill ${statusInfo.statusClass}" style="font-size: 0.75rem;">${statusInfo.statusText}</span>
            </div>
            <div style="font-size: 0.88rem; color: var(--color-text); margin-bottom: 8px;">
              <strong>Producto(s):</strong> ${productsSummary}
            </div>
            <div style="display: grid; grid-template-columns: repeat(auto-fit, minmax(110px, 1fr)); gap: 8px; font-size: 0.82rem; background: #f8fafc; padding: 8px 10px; border-radius: 6px;">
              <div><span style="color: var(--color-text-muted);">Total venta:</span><br><strong>$${cred.totalSaleUSD.toFixed(2)} USD</strong></div>
              <div><span style="color: var(--color-text-muted);">Saldo restante:</span><br><strong style="color: #b91c1c;">$${cred.remainingBalance.toFixed(2)} USD</strong></div>
              <div><span style="color: var(--color-text-muted);">Cuotas:</span><br><strong>${paidCount}/${totalCount} pagadas</strong></div>
              <div><span style="color: var(--color-text-muted);">Próx. vencimiento:</span><br><strong>${statusInfo.nextDueDate}</strong></div>
            </div>
            <div style="display: flex; justify-content: flex-end; margin-top: 10px;">
              <button type="button" class="btn-action-view btn-view-credit-from-client" data-id="${cred.id}" style="padding: 4px 10px; font-size: 0.8rem;">
                Ver detalle del crédito
              </button>
            </div>
          </div>
        `;
      }).join("");

      historyContainer.querySelectorAll(".btn-view-credit-from-client").forEach((btn) => {
        btn.onclick = (e) => {
          e.preventDefault();
          const credId = btn.getAttribute("data-id");
          closeClientProfileModal();
          openCreditDetailModal(credId);
        };
      });
    }
  }

  if (modal) modal.classList.remove("hidden");
}

function closeClientProfileModal() {
  const modal = document.getElementById("client-profile-modal");
  if (modal) modal.classList.add("hidden");
}

let clientDeletionTarget = null;

function updateSelectedClientsButton() {
  const tbody = document.getElementById("clients-tbody");
  const btnDeleteSelected = document.getElementById("btn-delete-selected-clients");
  const checkAll = document.getElementById("check-all-clients");
  if (!tbody || !btnDeleteSelected) return;

  const checkedBoxes = tbody.querySelectorAll(".client-row-checkbox:checked");
  const allBoxes = tbody.querySelectorAll(".client-row-checkbox");
  const count = checkedBoxes.length;

  if (count > 0) {
    btnDeleteSelected.classList.remove("hidden");
    btnDeleteSelected.style.display = "inline-flex";
    btnDeleteSelected.innerHTML = `<span>🗑️ Eliminar seleccionados (${count})</span>`;
  } else {
    btnDeleteSelected.classList.add("hidden");
    btnDeleteSelected.style.display = "none";
  }

  if (checkAll) {
    checkAll.checked = (allBoxes.length > 0 && count === allBoxes.length);
    checkAll.indeterminate = (count > 0 && count < allBoxes.length);
  }
}

function openDeleteClientModal(target) {
  if (typeof target === "string") {
    target = { mode: "single", clientId: target };
  }
  clientDeletionTarget = target;
  const modal = document.getElementById("modal-confirm-delete-client");
  const step1 = document.getElementById("delete-client-step-1");
  const step2 = document.getElementById("delete-client-step-2");
  const step1Msg = document.getElementById("delete-client-step-1-message");
  const input1 = document.getElementById("input-confirm-delete-client-word");
  const btnContinue = document.getElementById("btn-continue-delete-client-step-1");
  const input2 = document.getElementById("input-confirm-delete-client-cascade-word");
  const btnCascade = document.getElementById("btn-confirm-delete-client-cascade");

  if (!modal || !step1 || !step2) return;

  step1.classList.remove("hidden");
  step2.classList.add("hidden");
  if (input1) input1.value = "";
  if (btnContinue) btnContinue.disabled = true;
  if (input2) input2.value = "";
  if (btnCascade) btnCascade.disabled = true;

  if (target.mode === "single") {
    const clients = getStoredClients();
    const client = clients.find((c) => String(c.id) === String(target.clientId));
    const clientName = client ? client.name : "este cliente";
    const clientDni = client ? client.dni : "";
    if (step1Msg) {
      step1Msg.innerHTML = `¿Seguro que deseas eliminar al cliente <strong>${escapeHtml(clientName)}</strong>${clientDni ? ` (${escapeHtml(clientDni)})` : ""}? Esta acción no se puede deshacer.`;
    }
  } else if (target.mode === "selected") {
    const count = (target.clientIds && target.clientIds.length) || 0;
    if (step1Msg) {
      step1Msg.innerHTML = `¿Seguro que deseas eliminar los <strong>${count}</strong> clientes seleccionados? Esta acción no se puede deshacer.`;
    }
  }

  modal.classList.remove("hidden");
  if (input1) input1.focus();
}

function closeDeleteClientModal() {
  const modal = document.getElementById("modal-confirm-delete-client");
  if (modal) modal.classList.add("hidden");
  const input1 = document.getElementById("input-confirm-delete-client-word");
  const input2 = document.getElementById("input-confirm-delete-client-cascade-word");
  if (input1) input1.value = "";
  if (input2) input2.value = "";
  clientDeletionTarget = null;
}

function proceedDeleteClientStep1() {
  const input1 = document.getElementById("input-confirm-delete-client-word");
  if (!input1 || input1.value.trim().toLowerCase() !== "borrar") return;
  if (!clientDeletionTarget) return;

  const targetIds = clientDeletionTarget.mode === "single" ? [String(clientDeletionTarget.clientId)] : clientDeletionTarget.clientIds.map(String);
  const allCredits = getStoredCredits();
  const hasCredits = allCredits.some((c) =>
    targetIds.includes(String(c.clientId)) ||
    (c.client && targetIds.includes(String(c.client.id)))
  );

  if (hasCredits) {
    const step1 = document.getElementById("delete-client-step-1");
    const step2 = document.getElementById("delete-client-step-2");
    const input2 = document.getElementById("input-confirm-delete-client-cascade-word");
    const btnCascade = document.getElementById("btn-confirm-delete-client-cascade");
    if (step1) step1.classList.add("hidden");
    if (step2) step2.classList.remove("hidden");
    if (input2) {
      input2.value = "";
      input2.focus();
    }
    if (btnCascade) btnCascade.disabled = true;
  } else {
    executeClientOnlyDeletion();
  }
}

function executeClientOnlyDeletion() {
  if (!clientDeletionTarget) return;
  const targetIds = clientDeletionTarget.mode === "single" ? [String(clientDeletionTarget.clientId)] : clientDeletionTarget.clientIds.map(String);
  const clients = getStoredClients();
  const updatedClients = clients.filter((c) => !targetIds.includes(String(c.id)));
  saveClientsToStorage(updatedClients);

  if (typeof addSystemLog === "function") {
    addSystemLog({
      level: "INFO",
      action: "DELETE_CLIENT",
      details: { targetIds, count: targetIds.length, cascade: false },
      status: "success"
    });
  }

  closeDeleteClientModal();
  renderClients();
}

function executeClientCascadeDeletion() {
  const input2 = document.getElementById("input-confirm-delete-client-cascade-word");
  if (!input2 || input2.value.trim().toLowerCase() !== "borrar") return;
  if (!clientDeletionTarget) return;

  const targetIds = clientDeletionTarget.mode === "single" ? [String(clientDeletionTarget.clientId)] : clientDeletionTarget.clientIds.map(String);
  const clients = getStoredClients();
  const updatedClients = clients.filter((c) => !targetIds.includes(String(c.id)));
  saveClientsToStorage(updatedClients);

  // Eliminar todos los créditos y pagos asociados a estos clientes
  const credits = getStoredCredits();
  const remainingCredits = credits.filter((c) =>
    !targetIds.includes(String(c.clientId)) &&
    !(c.client && targetIds.includes(String(c.client.id)))
  );
  saveCreditsToStorage(remainingCredits);

  // Limpiar facturas y comprobantes asociados
  const invoices = getStoredInvoices();
  const remainingInvoices = invoices.filter((inv) => {
    const credId = String(inv.creditId || (inv.data && inv.data.creditId) || "");
    const belongsToDeletedClient = targetIds.includes(String(inv.clientId || (inv.client && inv.client.id) || ""));
    const creditWasDeleted = credId && !remainingCredits.some((c) => String(c.id) === credId);
    return !belongsToDeletedClient && !creditWasDeleted;
  });
  saveInvoicesToStorage(remainingInvoices);

  if (typeof addSystemLog === "function") {
    addSystemLog({
      level: "INFO",
      action: "DELETE_CLIENT",
      details: {
        targetIds,
        count: targetIds.length,
        cascade: true,
        deletedCreditsCount: credits.length - remainingCredits.length
      },
      status: "success"
    });
  }

  closeDeleteClientModal();
  renderClients();
  renderCredits();
  renderPagosSection();
}

function renderClients() {
  const tbody = document.getElementById("clients-tbody");
  const noClientsMsg = document.getElementById("no-clients-msg");
  const table = document.getElementById("clients-table");

  if (!tbody || !noClientsMsg || !table) return;

  const allClients = getStoredClients();

  // Filtrar según búsqueda si aplica
  let filteredClients = allClients;
  if (clientSearchQuery) {
    filteredClients = allClients.filter((c) => {
      const nameMatch = c.name.toLowerCase().includes(clientSearchQuery);
      const dniMatch = c.dni.toLowerCase().includes(clientSearchQuery);
      return nameMatch || dniMatch;
    });
  }

  if (allClients.length === 0) {
    table.classList.add("hidden");
    noClientsMsg.classList.remove("hidden");
    noClientsMsg.querySelector("p").textContent = "No hay clientes registrados.";
    tbody.innerHTML = "";
    updateSelectedClientsButton();
    return;
  }

  if (filteredClients.length === 0) {
    table.classList.add("hidden");
    noClientsMsg.classList.remove("hidden");
    noClientsMsg.querySelector("p").textContent = "No se encontraron clientes coincidentes.";
    tbody.innerHTML = "";
    updateSelectedClientsButton();
    return;
  }

  table.classList.remove("hidden");
  noClientsMsg.classList.add("hidden");

  tbody.innerHTML = filteredClients
    .map((client) => {
      return `
        <tr>
          <td style="width: 44px; text-align: center;">
            <input type="checkbox" class="client-row-checkbox" data-id="${client.id}" style="width: 17px; height: 17px; cursor: pointer;">
          </td>
          <td>
            <span class="client-dni-badge">${escapeHtml(client.dni)}</span>
          </td>
          <td class="client-name-cell">${escapeHtml(client.name)}</td>
          <td class="client-phone-cell">${escapeHtml(client.phone)}</td>
          <td class="client-address-cell" title="${escapeHtml(client.address)}">${escapeHtml(client.address)}</td>
          <td class="actions-cell">
            <button type="button" class="btn-action-view" data-id="${client.id}">Ver</button>
            <button type="button" class="btn-action-edit" data-id="${client.id}">Editar</button>
            <button type="button" class="btn-action-delete" data-id="${client.id}" title="Eliminar cliente">🗑️ Eliminar</button>
          </td>
        </tr>
      `;
    })
    .join("");

  // Respaldos directos de eventos onclick
  tbody.querySelectorAll(".btn-action-view").forEach((btn) => {
    btn.onclick = (e) => {
      e.preventDefault();
      const id = btn.getAttribute("data-id");
      openClientProfileModal(id);
    };
  });

  tbody.querySelectorAll(".btn-action-edit").forEach((btn) => {
    btn.onclick = (e) => {
      e.preventDefault();
      const id = btn.getAttribute("data-id");
      openEditClientModal(id);
    };
  });

  tbody.querySelectorAll(".btn-action-delete").forEach((btn) => {
    btn.onclick = (e) => {
      e.preventDefault();
      const id = btn.getAttribute("data-id");
      openDeleteClientModal(id);
    };
  });

  updateSelectedClientsButton();
}

// ============================================================
// FASE 4: MÓDULO DE CRÉDITOS Y CUOTAS (LÓGICA)
// ============================================================
const CREDITS_STORAGE_KEY = "hogarflex_credits";

// Estado temporal para la creación de un crédito
let currentCreditItems = [];

function getStoredCredits() {
  try {
    const data = localStorage.getItem(CREDITS_STORAGE_KEY);
    return data ? JSON.parse(data) : [];
  } catch (err) {
    console.error("Error al cargar créditos de localStorage:", err);
    return [];
  }
}

function saveCreditsToStorage(credits) {
  try {
    localStorage.setItem(CREDITS_STORAGE_KEY, JSON.stringify(credits));
    triggerAutoCloudBackup("créditos/pagos");
  } catch (err) {
    console.error("Error al guardar créditos en localStorage:", err);
    alert("No se pudo guardar el crédito. Almacenamiento lleno.");
  }
}

let currentDetailCreditId = null;
let currentPaymentCreditId = null;
let creditDeletionTarget = null;

function updateSelectedCreditsButton() {
  const tbody = document.getElementById("credits-tbody");
  const btnDeleteSelected = document.getElementById("btn-delete-selected-credits");
  const checkAll = document.getElementById("check-all-credits");
  if (!btnDeleteSelected) return;

  const checkedBoxes = tbody ? tbody.querySelectorAll(".credit-row-checkbox:checked") : document.querySelectorAll(".credit-row-checkbox:checked");
  const allBoxes = tbody ? tbody.querySelectorAll(".credit-row-checkbox") : document.querySelectorAll(".credit-row-checkbox");
  const count = checkedBoxes.length;

  if (count > 0) {
    btnDeleteSelected.classList.remove("hidden");
    btnDeleteSelected.style.display = "inline-flex";
    btnDeleteSelected.innerHTML = `<span>🗑️ Eliminar seleccionados (${count})</span>`;
  } else {
    btnDeleteSelected.classList.add("hidden");
    btnDeleteSelected.style.display = "none";
  }

  if (checkAll) {
    checkAll.checked = (allBoxes.length > 0 && count === allBoxes.length);
    checkAll.indeterminate = (count > 0 && count < allBoxes.length);
  }
}

function openDeleteCreditModal(target) {
  if (typeof target === "string") {
    target = { mode: "single", creditId: target };
  }

  // Comprobar si algún crédito a eliminar está en estado "Cortado" (Operación no permitida)
  const allCreds = getStoredCredits();
  const checkIds = target.mode === "single" ? [String(target.creditId)] : (target.creditIds || []).map(String);
  const targetCreds = allCreds.filter((c) => checkIds.includes(String(c.id)));
  const cortadoItem = targetCreds.find((c) => String(c.status || "").toLowerCase() === "cortado");

  if (cortadoItem) {
    if (typeof addSystemLog === "function") {
      addSystemLog({
        level: "WARNING",
        action: "OPERATION_FORBIDDEN",
        details: {
          operation: "DELETE_CREDIT",
          creditId: cortadoItem.id,
          status: cortadoItem.status,
          reason: "Intento de eliminar crédito en estado Cortado"
        },
        status: "failed",
        errorMessage: `Intento de operación no permitida: crédito ${cortadoItem.id} en estado Cortado`
      });
    }
    alert("⚠️ Operación no permitida: No se puede eliminar un crédito que se encuentra en estado Cortado por políticas de auditoría.");
    return;
  }

  creditDeletionTarget = target;

  const modal = document.getElementById("modal-confirm-delete-credit");
  const step1 = document.getElementById("delete-credit-step-1");
  const step2 = document.getElementById("delete-credit-step-2");
  const step1Msg = document.getElementById("delete-credit-step-1-message");
  const input1 = document.getElementById("input-confirm-delete-credit-word");
  const btnContinue = document.getElementById("btn-continue-delete-credit-step-1");
  const input2 = document.getElementById("input-confirm-delete-credit-cascade-word");
  const btnCascade = document.getElementById("btn-confirm-delete-credit-cascade");

  if (!modal || !step1 || !step2) return;

  step1.classList.remove("hidden");
  step2.classList.add("hidden");
  if (input1) input1.value = "";
  if (btnContinue) btnContinue.disabled = true;
  if (input2) input2.value = "";
  if (btnCascade) btnCascade.disabled = true;

  if (target.mode === "single") {
    const credits = getStoredCredits();
    const credit = credits.find((c) => String(c.id) === String(target.creditId));
    const clientName = credit && credit.client && credit.client.name ? credit.client.name : "este crédito";
    const totalSale = credit ? `$${(parseFloat(credit.totalSaleUSD) || 0).toFixed(2)} USD` : "";
    if (step1Msg) {
      step1Msg.innerHTML = `¿Seguro que deseas eliminar el crédito de <strong>${escapeHtml(clientName)}</strong>${totalSale ? ` por <strong>${totalSale}</strong>` : ""}? Esta acción no se puede deshacer.`;
    }
  } else if (target.mode === "selected") {
    const count = (target.creditIds && target.creditIds.length) || 0;
    if (step1Msg) {
      step1Msg.innerHTML = `¿Seguro que deseas eliminar los <strong>${count}</strong> créditos seleccionados? Esta acción no se puede deshacer.`;
    }
  }

  modal.classList.remove("hidden");
  if (input1) input1.focus();
}

function closeDeleteCreditModal() {
  const modal = document.getElementById("modal-confirm-delete-credit");
  if (modal) modal.classList.add("hidden");
  const input1 = document.getElementById("input-confirm-delete-credit-word");
  const input2 = document.getElementById("input-confirm-delete-credit-cascade-word");
  if (input1) input1.value = "";
  if (input2) input2.value = "";
  creditDeletionTarget = null;
}

function proceedDeleteCreditStep1() {
  const input1 = document.getElementById("input-confirm-delete-credit-word");
  if (!input1 || input1.value.trim().toLowerCase() !== "borrar") return;
  if (!creditDeletionTarget) return;

  const targetIds = creditDeletionTarget.mode === "single"
    ? [String(creditDeletionTarget.creditId)]
    : creditDeletionTarget.creditIds.map(String);

  const credits = getStoredCredits();
  const targetCredits = credits.filter((c) => targetIds.includes(String(c.id)));
  const hasPayments = targetCredits.some((c) => Array.isArray(c.payments) && c.payments.length > 0);

  if (hasPayments) {
    const step1 = document.getElementById("delete-credit-step-1");
    const step2 = document.getElementById("delete-credit-step-2");
    const input2 = document.getElementById("input-confirm-delete-credit-cascade-word");
    const btnCascade = document.getElementById("btn-confirm-delete-credit-cascade");

    if (step1) step1.classList.add("hidden");
    if (step2) step2.classList.remove("hidden");
    if (input2) {
      input2.value = "";
      input2.focus();
    }
    if (btnCascade) btnCascade.disabled = true;
  } else {
    executeCreditOnlyDeletion();
  }
}

function executeCreditOnlyDeletion() {
  if (!creditDeletionTarget) return;
  const targetIds = creditDeletionTarget.mode === "single"
    ? [String(creditDeletionTarget.creditId)]
    : creditDeletionTarget.creditIds.map(String);

  const credits = getStoredCredits();
  const remainingCredits = credits.filter((c) => !targetIds.includes(String(c.id)));
  saveCreditsToStorage(remainingCredits);

  if (typeof addSystemLog === "function") {
    addSystemLog({
      level: "INFO",
      action: "DELETE_CREDIT",
      details: { targetIds, count: targetIds.length, cascade: false },
      status: "success"
    });
  }

  closeDeleteCreditModal();
  renderCredits();
  renderPagosSection();
}

function executeCreditCascadeDeletion() {
  const input2 = document.getElementById("input-confirm-delete-credit-cascade-word");
  if (!input2 || input2.value.trim().toLowerCase() !== "borrar") return;
  if (!creditDeletionTarget) return;

  const targetIds = creditDeletionTarget.mode === "single"
    ? [String(creditDeletionTarget.creditId)]
    : creditDeletionTarget.creditIds.map(String);

  const credits = getStoredCredits();
  const remainingCredits = credits.filter((c) => !targetIds.includes(String(c.id)));
  saveCreditsToStorage(remainingCredits);

  // Limpiar facturas asociadas
  const invoices = getStoredInvoices();
  const remainingInvoices = invoices.filter((inv) => {
    const credId = String(inv.creditId || (inv.data && inv.data.creditId) || "");
    return !targetIds.includes(credId);
  });
  saveInvoicesToStorage(remainingInvoices);

  if (typeof addSystemLog === "function") {
    addSystemLog({
      level: "INFO",
      action: "DELETE_CREDIT",
      details: { targetIds, count: targetIds.length, cascade: true },
      status: "success"
    });
  }

  closeDeleteCreditModal();
  renderCredits();
  renderPagosSection();
}

function initCreditsModule() {
  const btnOpenCreateCredit = document.getElementById("btn-open-create-credit");
  const creditModal = document.getElementById("credit-modal");
  const btnCloseCreditModal = document.getElementById("btn-close-credit-modal");
  const btnCancelCredit = document.getElementById("btn-cancel-credit");
  const creditForm = document.getElementById("credit-form");

  const btnAddProductToCredit = document.getElementById("btn-add-product-to-credit");
  const creditItemsTbody = document.getElementById("credit-items-tbody");

  const hasShippingCheckbox = document.getElementById("credit-has-shipping");
  const shippingInputBox = document.getElementById("credit-shipping-input-box");
  const shippingAmountInput = document.getElementById("credit-shipping-amount");
  
  // Elementos de cuota inicial monto libre y porcentaje opcional
  const downpaymentCurrencySelect = document.getElementById("credit-downpayment-currency");
  const downpaymentPercentInput = document.getElementById("credit-downpayment-percent");
  const downpaymentBoxUsd = document.getElementById("downpayment-box-usd");
  const downpaymentBoxBs = document.getElementById("downpayment-box-bs");
  const downpaymentAmountUsdInput = document.getElementById("credit-downpayment-amount-usd");
  const downpaymentAmountBsInput = document.getElementById("credit-downpayment-amount-bs");
  const downpaymentRateBcvInput = document.getElementById("credit-downpayment-rate-bcv");

  const installmentsInput = document.getElementById("credit-installments-count");
  const paymentFrequencySelect = document.getElementById("credit-payment-frequency");

  // Elementos modal detalle
  const detailModal = document.getElementById("credit-detail-modal");
  const btnCloseDetailModal = document.getElementById("btn-close-credit-detail-modal");
  const btnCloseDetail = document.getElementById("btn-close-credit-detail");
  const btnPayInstFromDetail = document.getElementById("btn-pay-installment-from-detail");
  const btnOpenPaymentFromDetail = document.getElementById("btn-open-payment-from-detail");

  // Elementos modal pagar cuota fija específica (Corrección 3)
  const payInstModal = document.getElementById("credit-pay-installment-modal");
  const btnClosePayInstModal = document.getElementById("btn-close-pay-installment-modal");
  const btnCancelPayInst = document.getElementById("btn-cancel-pay-installment");
  const payInstForm = document.getElementById("credit-pay-installment-form");
  const payInstCurrencySelect = document.getElementById("pay-inst-currency-select");
  const payInstRateBcvTodayInput = document.getElementById("pay-inst-rate-bcv-today");

  // Elementos modal registrar abono libre (Corrección 3)
  const paymentModal = document.getElementById("credit-payment-modal");
  const btnClosePaymentModal = document.getElementById("btn-close-payment-modal");
  const btnCancelPayment = document.getElementById("btn-cancel-payment");
  const paymentForm = document.getElementById("credit-payment-form");
  const paymentAmountInput = document.getElementById("payment-amount-input");
  const paymentCurrencySelect = document.getElementById("payment-currency-select");
  const paymentRateBcvBox = document.getElementById("payment-rate-bcv-box");
  const paymentRateBcvTodayInput = document.getElementById("payment-rate-bcv-today");

  const creditsTbody = document.getElementById("credits-tbody");

  if (!btnOpenCreateCredit || !creditModal || !creditForm) return;

  // Abrir modal de creación
  btnOpenCreateCredit.addEventListener("click", openCreateCreditModal);

  // Cerrar modal de creación
  btnCloseCreditModal.addEventListener("click", closeCreditModal);
  btnCancelCredit.addEventListener("click", closeCreditModal);
  creditModal.addEventListener("click", (e) => {
    if (e.target === creditModal) closeCreditModal();
  });

  // Toggle de campo de flete
  hasShippingCheckbox.addEventListener("change", () => {
    if (hasShippingCheckbox.checked) {
      shippingInputBox.classList.remove("hidden");
    } else {
      shippingInputBox.classList.add("hidden");
      shippingAmountInput.value = "0.00";
    }
    updateCreditCalculations();
  });

  // Toggle de campos de cuota inicial según moneda seleccionada (Divisas, Bolívares o Mixto)
  function handleDownpaymentCurrencyChange() {
    const curr = downpaymentCurrencySelect.value;
    if (curr === "USD") {
      if (downpaymentBoxUsd) downpaymentBoxUsd.classList.remove("hidden");
      if (downpaymentBoxBs) downpaymentBoxBs.classList.add("hidden");
    } else if (curr === "BS") {
      if (downpaymentBoxUsd) downpaymentBoxUsd.classList.add("hidden");
      if (downpaymentBoxBs) downpaymentBoxBs.classList.remove("hidden");
    } else if (curr === "MIXED") {
      if (downpaymentBoxUsd) downpaymentBoxUsd.classList.remove("hidden");
      if (downpaymentBoxBs) downpaymentBoxBs.classList.remove("hidden");
    }

    const pInput = document.getElementById("credit-downpayment-percent");
    if (pInput && parseFloat(pInput.value) > 0) {
      handleDownpaymentPercentInput();
    } else {
      updateCreditCalculations();
    }
  }

  if (downpaymentCurrencySelect) {
    downpaymentCurrencySelect.addEventListener("change", handleDownpaymentCurrencyChange);
  }
  if (downpaymentPercentInput) {
    downpaymentPercentInput.addEventListener("input", handleDownpaymentPercentInput);
  }
  if (downpaymentAmountUsdInput) downpaymentAmountUsdInput.addEventListener("input", updateCreditCalculations);
  if (downpaymentAmountBsInput) downpaymentAmountBsInput.addEventListener("input", updateCreditCalculations);
  if (downpaymentRateBcvInput) {
    downpaymentRateBcvInput.addEventListener("input", () => {
      const pInput = document.getElementById("credit-downpayment-percent");
      if (pInput && parseFloat(pInput.value) > 0 && downpaymentCurrencySelect && downpaymentCurrencySelect.value === "BS") {
        handleDownpaymentPercentInput();
      } else {
        updateCreditCalculations();
      }
    });
  }

  shippingAmountInput.addEventListener("input", updateCreditCalculations);
  installmentsInput.addEventListener("input", updateCreditCalculations);
  if (paymentFrequencySelect) {
    paymentFrequencySelect.addEventListener("change", updateCreditCalculations);
  }

  // Añadir producto al crédito
  btnAddProductToCredit.addEventListener("click", handleAddProductToCredit);

  // Escuchar selector de producto para abrir drawer si selecciona ＋ Nuevo producto
  const creditProductSelect = document.getElementById("credit-product-select");
  if (creditProductSelect) {
    creditProductSelect.addEventListener("change", (e) => {
      if (e.target.value === "__NEW_PRODUCT__") {
        e.target.value = "";
        if (typeof openProductCatalogDrawer === "function") {
          openProductCatalogDrawer({ originSelectId: "credit-product-select" });
        }
      }
    });
  }

  // Delegación para eliminar producto de la lista en el formulario
  creditItemsTbody.addEventListener("click", (e) => {
    const removeBtn = e.target.closest(".btn-remove-item");
    if (removeBtn) {
      const idx = parseInt(removeBtn.getAttribute("data-index"), 10);
      if (!isNaN(idx)) {
        currentCreditItems.splice(idx, 1);
        renderCreditItemsTable();
        updateCreditCalculations();
      }
    }
  });

  // Guardar crédito
  creditForm.addEventListener("submit", handleCreditFormSubmit);

  // Cerrar modal de detalle
  if (btnCloseDetailModal) btnCloseDetailModal.addEventListener("click", closeCreditDetailModal);
  if (btnCloseDetail) btnCloseDetail.addEventListener("click", closeCreditDetailModal);
  if (detailModal) {
    detailModal.addEventListener("click", (e) => {
      if (e.target === detailModal) closeCreditDetailModal();
    });
  }

  // Botones desde el modal de detalle
  if (btnPayInstFromDetail) {
    btnPayInstFromDetail.addEventListener("click", () => {
      if (currentDetailCreditId) {
        openPayInstallmentModal(currentDetailCreditId);
      }
    });
  }
  if (btnOpenPaymentFromDetail) {
    btnOpenPaymentFromDetail.addEventListener("click", () => {
      if (currentDetailCreditId) {
        openCreditPaymentModal(currentDetailCreditId);
      }
    });
  }

  // Eventos modal Pagar Cuota fija (Corrección 3)
  if (btnClosePayInstModal) btnClosePayInstModal.addEventListener("click", closePayInstallmentModal);
  if (btnCancelPayInst) btnCancelPayInst.addEventListener("click", closePayInstallmentModal);
  if (payInstModal) {
    payInstModal.addEventListener("click", (e) => {
      if (e.target === payInstModal) closePayInstallmentModal();
    });
  }
  if (payInstCurrencySelect) {
    payInstCurrencySelect.addEventListener("change", updatePayInstallmentCalculations);
  }
  if (payInstRateBcvTodayInput) {
    payInstRateBcvTodayInput.addEventListener("input", updatePayInstallmentCalculations);
  }
  if (payInstForm) {
    payInstForm.addEventListener("submit", handlePayInstallmentSubmit);
  }

  // Modal de pago libre
  if (btnClosePaymentModal) btnClosePaymentModal.addEventListener("click", closeCreditPaymentModal);
  if (btnCancelPayment) btnCancelPayment.addEventListener("click", closeCreditPaymentModal);
  if (paymentModal) {
    paymentModal.addEventListener("click", (e) => {
      if (e.target === paymentModal) closeCreditPaymentModal();
    });
  }
  const paymentAmountBsInput = document.getElementById("payment-amount-bs-input");
  const paymentAmountBsBox = document.getElementById("payment-amount-bs-box");

  if (paymentAmountInput) {
    paymentAmountInput.addEventListener("input", () => {
      if (paymentCurrencySelect && paymentCurrencySelect.value === "BS") {
        const rateVal = parseFloat(paymentRateBcvTodayInput ? paymentRateBcvTodayInput.value : 0) || 0;
        const usdVal = parseFloat(paymentAmountInput.value) || 0;
        if (rateVal > 0 && paymentAmountBsInput && document.activeElement !== paymentAmountBsInput) {
          paymentAmountBsInput.value = (usdVal * rateVal).toFixed(2);
        }
      }
      updatePaymentCalculations();
    });
  }
  if (paymentAmountBsInput) {
    paymentAmountBsInput.addEventListener("input", () => {
      const rateVal = parseFloat(paymentRateBcvTodayInput ? paymentRateBcvTodayInput.value : 0) || 0;
      const bsVal = parseFloat(paymentAmountBsInput.value) || 0;
      if (rateVal > 0 && paymentAmountInput) {
        paymentAmountInput.value = (bsVal / rateVal).toFixed(2);
      }
      updatePaymentCalculations();
    });
  }
  if (paymentCurrencySelect) {
    paymentCurrencySelect.addEventListener("change", () => {
      if (paymentCurrencySelect.value === "BS") {
        if (paymentRateBcvBox) paymentRateBcvBox.classList.remove("hidden");
        if (paymentAmountBsBox) paymentAmountBsBox.classList.remove("hidden");
      } else {
        if (paymentRateBcvBox) paymentRateBcvBox.classList.add("hidden");
        if (paymentAmountBsBox) paymentAmountBsBox.classList.add("hidden");
      }
      updatePaymentCalculations();
    });
  }
  if (paymentRateBcvTodayInput) {
    paymentRateBcvTodayInput.addEventListener("input", () => {
      const rateVal = parseFloat(paymentRateBcvTodayInput.value) || 0;
      if (rateVal > 0) {
        if (document.activeElement === paymentAmountBsInput || (paymentAmountBsInput && paymentAmountBsInput.value && !paymentAmountInput.value)) {
          const bsVal = parseFloat(paymentAmountBsInput.value) || 0;
          if (paymentAmountInput) paymentAmountInput.value = (bsVal / rateVal).toFixed(2);
        } else if (paymentAmountInput && paymentAmountInput.value) {
          const usdVal = parseFloat(paymentAmountInput.value) || 0;
          if (paymentAmountBsInput) paymentAmountBsInput.value = (usdVal * rateVal).toFixed(2);
        }
      }
      updatePaymentCalculations();
    });
  }
  if (paymentForm) {
    paymentForm.addEventListener("submit", handlePaymentFormSubmit);
  }

  // Delegación en tabla de créditos para Ver Detalle y Abonar
  if (creditsTbody) {
    creditsTbody.addEventListener("click", (e) => {
      const payInstBtn = e.target.closest(".btn-action-pay-installment");
      if (payInstBtn) {
        e.preventDefault();
        const id = payInstBtn.getAttribute("data-id");
        if (id) openPayInstallmentModal(id);
        return;
      }
      const payBtn = e.target.closest(".btn-action-abonar") || e.target.closest(".btn-action-pay");
      if (payBtn) {
        e.preventDefault();
        const id = payBtn.getAttribute("data-id");
        openCreditPaymentModal(id);
        return;
      }
      const viewBtn = e.target.closest(".btn-action-view");
      if (viewBtn) {
        e.preventDefault();
        const id = viewBtn.getAttribute("data-id");
        openCreditDetailModal(id);
        return;
      }
      const deleteBtn = e.target.closest(".btn-action-delete-credit");
      if (deleteBtn) {
        e.preventDefault();
        const id = deleteBtn.getAttribute("data-id");
        if (id) openDeleteCreditModal(id);
        return;
      }
    });
  }

  // Control de checkboxes para selección múltiple de créditos
  const checkAllCredits = document.getElementById("check-all-credits");
  if (checkAllCredits) {
    checkAllCredits.addEventListener("change", () => {
      const tbody = document.getElementById("credits-tbody");
      if (!tbody) return;
      const checkboxes = tbody.querySelectorAll(".credit-row-checkbox");
      checkboxes.forEach((cb) => {
        cb.checked = checkAllCredits.checked;
      });
      updateSelectedCreditsButton();
    });
  }

  if (creditsTbody) {
    creditsTbody.addEventListener("change", (e) => {
      if (e.target.classList.contains("credit-row-checkbox")) {
        updateSelectedCreditsButton();
      }
    });
  }

  const btnDeleteSelectedCredits = document.getElementById("btn-delete-selected-credits");
  if (btnDeleteSelectedCredits) {
    btnDeleteSelectedCredits.addEventListener("click", () => {
      const tbody = document.getElementById("credits-tbody");
      if (!tbody) return;
      const checkedBoxes = tbody.querySelectorAll(".credit-row-checkbox:checked");
      const selectedIds = Array.from(checkedBoxes).map((cb) => cb.getAttribute("data-id"));
      if (selectedIds.length === 0) return;
      openDeleteCreditModal({ mode: "selected", creditIds: selectedIds });
    });
  }

  // Eventos del modal de confirmación en dos pasos (Créditos)
  const btnCloseDelCreditModal = document.getElementById("btn-close-delete-credit-modal");
  const btnCancelCreditStep1 = document.getElementById("btn-cancel-delete-credit-step-1");
  const btnContinueCreditStep1 = document.getElementById("btn-continue-delete-credit-step-1");
  const btnCancelCreditStep2 = document.getElementById("btn-cancel-delete-credit-step-2");
  const btnConfirmCreditCascade = document.getElementById("btn-confirm-delete-credit-cascade");
  const inputDeleteCreditWord = document.getElementById("input-confirm-delete-credit-word");
  const inputDeleteCreditCascadeWord = document.getElementById("input-confirm-delete-credit-cascade-word");
  const modalDelCredit = document.getElementById("modal-confirm-delete-credit");

  if (btnCloseDelCreditModal) btnCloseDelCreditModal.addEventListener("click", closeDeleteCreditModal);
  if (btnCancelCreditStep1) btnCancelCreditStep1.addEventListener("click", closeDeleteCreditModal);
  if (btnContinueCreditStep1) btnContinueCreditStep1.addEventListener("click", proceedDeleteCreditStep1);
  if (btnCancelCreditStep2) btnCancelCreditStep2.addEventListener("click", executeCreditOnlyDeletion);
  if (btnConfirmCreditCascade) btnConfirmCreditCascade.addEventListener("click", executeCreditCascadeDeletion);

  if (inputDeleteCreditWord) {
    inputDeleteCreditWord.addEventListener("input", (e) => {
      const isBorrar = e.target.value.trim().toLowerCase() === "borrar";
      if (btnContinueCreditStep1) btnContinueCreditStep1.disabled = !isBorrar;
    });
    inputDeleteCreditWord.addEventListener("keydown", (e) => {
      if (e.key === "Enter" && btnContinueCreditStep1 && !btnContinueCreditStep1.disabled) {
        e.preventDefault();
        proceedDeleteCreditStep1();
      }
    });
  }

  if (inputDeleteCreditCascadeWord) {
    inputDeleteCreditCascadeWord.addEventListener("input", (e) => {
      const isBorrar = e.target.value.trim().toLowerCase() === "borrar";
      if (btnConfirmCreditCascade) btnConfirmCreditCascade.disabled = !isBorrar;
    });
    inputDeleteCreditCascadeWord.addEventListener("keydown", (e) => {
      if (e.key === "Enter" && btnConfirmCreditCascade && !btnConfirmCreditCascade.disabled) {
        e.preventDefault();
        executeCreditCascadeDeletion();
      }
    });
  }

  if (modalDelCredit) {
    modalDelCredit.addEventListener("click", (e) => {
      if (e.target === modalDelCredit) closeDeleteCreditModal();
    });
  }

  setupOverdueActionModalEvents();
  setupActiveCreditsModalEvents();
  renderCredits();
}

// Abrir modal de creación de crédito
function openCreateCreditModal() {
  const modal = document.getElementById("credit-modal");
  const form = document.getElementById("credit-form");
  const errorMsg = document.getElementById("credit-form-error");
  const clientSelect = document.getElementById("credit-client-select");
  const productSelect = document.getElementById("credit-product-select");
  const shippingInputBox = document.getElementById("credit-shipping-input-box");
  const hasShippingCheckbox = document.getElementById("credit-has-shipping");

  form.reset();
  currentCreditItems = [];
  if (errorMsg) {
    errorMsg.style.display = "none";
    errorMsg.textContent = "";
  }

  // Poblar select de clientes
  const clients = getStoredClients();
  clientSelect.innerHTML = '<option value="">-- Seleccionar cliente registrado --</option>' +
    clients.map((c) => `<option value="${c.id}">${escapeHtml(c.name)} (${escapeHtml(c.dni)})</option>`).join("");

  // Poblar select de productos con soporte para catálogo y opción fija ＋ Nuevo producto
  if (typeof populateProductSelectWithCatalog === "function") {
    populateProductSelectWithCatalog(productSelect);
  } else {
    const products = getStoredProducts();
    productSelect.innerHTML = '<option value="">-- Seleccionar producto --</option>' +
      products.map((p) => {
        const hasQty = p.quantity !== null && p.quantity !== undefined && p.quantity !== "";
        const stockInfo = hasQty ? ` (Disponibles: ${p.quantity})` : "";
        return `<option value="${p.id}" data-price="${p.price}" data-name="${escapeHtml(p.name)}">${escapeHtml(p.name)} - $${parseFloat(p.price).toFixed(2)}${stockInfo}</option>`;
      }).join("");
  }

  // Valores predeterminados de inicial
  const downpaymentCurrencySelect = document.getElementById("credit-downpayment-currency");
  if (downpaymentCurrencySelect) downpaymentCurrencySelect.value = "USD";
  const downpaymentBoxUsd = document.getElementById("downpayment-box-usd");
  const downpaymentBoxBs = document.getElementById("downpayment-box-bs");
  if (downpaymentBoxUsd) downpaymentBoxUsd.classList.remove("hidden");
  if (downpaymentBoxBs) downpaymentBoxBs.classList.add("hidden");

  const downpaymentPercentInput = document.getElementById("credit-downpayment-percent");
  if (downpaymentPercentInput) downpaymentPercentInput.value = "0";
  const downpaymentAmountUsdInput = document.getElementById("credit-downpayment-amount-usd");
  if (downpaymentAmountUsdInput) downpaymentAmountUsdInput.value = "0.00";
  const downpaymentAmountBsInput = document.getElementById("credit-downpayment-amount-bs");
  if (downpaymentAmountBsInput) downpaymentAmountBsInput.value = "0.00";
  const downpaymentRateBcvInput = document.getElementById("credit-downpayment-rate-bcv");
  if (downpaymentRateBcvInput) downpaymentRateBcvInput.value = "";

  document.getElementById("credit-installments-count").value = "3";
  const frequencySelect = document.getElementById("credit-payment-frequency");
  if (frequencySelect) frequencySelect.value = "30";
  hasShippingCheckbox.checked = false;
  shippingInputBox.classList.add("hidden");
  document.getElementById("credit-shipping-amount").value = "0.00";

  renderCreditItemsTable();
  updateCreditCalculations();

  modal.classList.remove("hidden");
}

function closeCreditModal() {
  const modal = document.getElementById("credit-modal");
  const form = document.getElementById("credit-form");
  if (modal) modal.classList.add("hidden");
  if (form) form.reset();
  currentCreditItems = [];
}

// Añadir producto a la lista temporal del crédito
// Cantidad es informativa: NUNCA bloquea venta ni muestra error, incluso con stock 0 o negativo
function handleAddProductToCredit() {
  const productSelect = document.getElementById("credit-product-select");
  const qtyInput = document.getElementById("credit-product-qty");
  const errorMsg = document.getElementById("credit-form-error");

  const productId = productSelect.value;
  const qty = parseInt(qtyInput.value, 10);

  if (!productId) {
    if (errorMsg) {
      errorMsg.textContent = "Por favor selecciona un producto para añadir.";
      errorMsg.style.display = "block";
    }
    return;
  }
  if (isNaN(qty) || qty <= 0) {
    if (errorMsg) {
      errorMsg.textContent = "Por favor indica una cantidad válida mayor a cero.";
      errorMsg.style.display = "block";
    }
    return;
  }

  const selectedOption = productSelect.options[productSelect.selectedIndex];
  const productName = selectedOption.getAttribute("data-name");
  const productPrice = parseFloat(selectedOption.getAttribute("data-price"));

  if (errorMsg) errorMsg.style.display = "none";

  // Comprobar si ya estaba en la lista para acumular cantidad sin bloquear venta
  const existingIdx = currentCreditItems.findIndex((item) => String(item.productId) === String(productId));
  if (existingIdx !== -1) {
    currentCreditItems[existingIdx].quantity += qty;
    currentCreditItems[existingIdx].qty = currentCreditItems[existingIdx].quantity;
    currentCreditItems[existingIdx].cantidad = currentCreditItems[existingIdx].quantity;
    currentCreditItems[existingIdx].subtotal = parseFloat((currentCreditItems[existingIdx].quantity * currentCreditItems[existingIdx].price).toFixed(2));
    currentCreditItems[existingIdx].totalLinea = currentCreditItems[existingIdx].subtotal;
  } else {
    const lineTotal = parseFloat((qty * productPrice).toFixed(2));
    currentCreditItems.push({
      id: "item_" + Date.now() + "_" + Math.random().toString(36).substr(2, 4),
      productId,
      name: productName,
      nombre: productName,
      price: productPrice,
      priceUSD: productPrice,
      precioUnitario: productPrice,
      unitPrice: productPrice,
      quantity: qty,
      qty: qty,
      cantidad: qty,
      subtotal: lineTotal,
      totalLinea: lineTotal
    });
  }

  // Restablecer selector
  productSelect.value = "";
  qtyInput.value = "1";

  renderCreditItemsTable();
  updateCreditCalculations();
}

// Renderizar tabla de productos seleccionados en el modal de creación
function renderCreditItemsTable() {
  const tbody = document.getElementById("credit-items-tbody");
  const emptyMsg = document.getElementById("empty-credit-items-msg");
  const table = document.getElementById("credit-items-table");

  if (!tbody || !emptyMsg || !table) return;

  if (currentCreditItems.length === 0) {
    table.classList.add("hidden");
    emptyMsg.classList.remove("hidden");
    tbody.innerHTML = "";
    return;
  }

  table.classList.remove("hidden");
  emptyMsg.classList.add("hidden");

  tbody.innerHTML = currentCreditItems
    .map((item, idx) => `
      <tr>
        <td><strong>${escapeHtml(item.name)}</strong></td>
        <td>${item.quantity}</td>
        <td>$${item.price.toFixed(2)}</td>
        <td><strong>$${item.subtotal.toFixed(2)}</strong></td>
        <td style="text-align: right;">
          <button type="button" class="btn-remove-item" data-index="${idx}" title="Quitar">✕</button>
        </td>
      </tr>
    `)
    .join("");
}

// Manejar entrada de porcentaje libre de cuota inicial (bidireccional con el monto)
function handleDownpaymentPercentInput() {
  const percentInput = document.getElementById("credit-downpayment-percent");
  if (!percentInput) return;

  const percentVal = Math.min(100, Math.max(0, parseFloat(percentInput.value) || 0));

  const hasShipping = document.getElementById("credit-has-shipping").checked;
  const shippingAmount = hasShipping ? (parseFloat(document.getElementById("credit-shipping-amount").value) || 0) : 0;
  const productsTotal = currentCreditItems.reduce((acc, item) => acc + item.subtotal, 0);
  const totalSaleUSD = productsTotal + shippingAmount;

  const targetUSD = totalSaleUSD * (percentVal / 100);

  const currencySelect = document.getElementById("credit-downpayment-currency");
  const currency = currencySelect ? currencySelect.value : "USD";
  const usdInput = document.getElementById("credit-downpayment-amount-usd");
  const bsInput = document.getElementById("credit-downpayment-amount-bs");
  const rateBcvInput = document.getElementById("credit-downpayment-rate-bcv");
  const rateBCV = parseFloat(rateBcvInput ? rateBcvInput.value : 0) || 0;

  if (currency === "USD") {
    if (usdInput) usdInput.value = targetUSD > 0 ? targetUSD.toFixed(2) : "0.00";
  } else if (currency === "BS") {
    if (rateBCV > 0) {
      const targetBs = targetUSD * rateBCV;
      if (bsInput) bsInput.value = targetBs > 0 ? targetBs.toFixed(2) : "0.00";
    }
  } else if (currency === "MIXED") {
    if (usdInput) usdInput.value = targetUSD > 0 ? targetUSD.toFixed(2) : "0.00";
    if (bsInput) bsInput.value = "0.00";
  }

  updateCreditCalculations({ skipPercentSync: true });
}

// Actualizar cálculos en tiempo real
// La dueña ingresa el monto libre que le dieron (ej. $50 o Bs. 200.000) o el porcentaje (ej. 20%)
// La app calcula automáticamente qué porcentaje representa del total y el saldo restante
function updateCreditCalculations(options = {}) {
  const hasShipping = document.getElementById("credit-has-shipping").checked;
  const shippingAmount = hasShipping ? (parseFloat(document.getElementById("credit-shipping-amount").value) || 0) : 0;
  const installmentsCount = Math.min(24, Math.max(1, parseInt(document.getElementById("credit-installments-count").value, 10) || 1));
  
  // 1. Total productos y Total venta (en USD)
  const productsTotal = currentCreditItems.reduce((acc, item) => acc + item.subtotal, 0);
  const totalSaleUSD = productsTotal + shippingAmount;

  // 2. Moneda y Monto libre de cuota inicial
  const downpaymentCurrencySelect = document.getElementById("credit-downpayment-currency");
  const currency = downpaymentCurrencySelect ? downpaymentCurrencySelect.value : "USD";

  const downpaymentAmountUsdInput = document.getElementById("credit-downpayment-amount-usd");
  const downpaymentAmountBsInput = document.getElementById("credit-downpayment-amount-bs");
  const downpaymentRateBcvInput = document.getElementById("credit-downpayment-rate-bcv");

  let downpaymentAmountUSD = 0;
  let downpaymentPaidUSD = 0;
  let downpaymentPaidBs = 0;
  let referenceText = "";

  if (currency === "USD") {
    const usdVal = parseFloat(downpaymentAmountUsdInput ? downpaymentAmountUsdInput.value : 0) || 0;
    downpaymentPaidUSD = usdVal;
    downpaymentAmountUSD = Math.min(totalSaleUSD, Math.max(0, usdVal));
    downpaymentPaidBs = 0;
    referenceText = downpaymentPaidUSD > 0 
      ? `$${downpaymentPaidUSD.toFixed(2)} USD pagados en divisas directamente` 
      : "Sin cuota inicial";
  } else if (currency === "BS") {
    const bsVal = parseFloat(downpaymentAmountBsInput ? downpaymentAmountBsInput.value : 0) || 0;
    const rateBCV = parseFloat(downpaymentRateBcvInput ? downpaymentRateBcvInput.value : 0) || 0;
    downpaymentPaidUSD = 0;
    downpaymentPaidBs = bsVal;

    if (rateBCV > 0 && bsVal > 0) {
      const usdEq = bsVal / rateBCV;
      downpaymentAmountUSD = Math.min(totalSaleUSD, Math.max(0, usdEq));
      referenceText = `Bs. ${formatBs(bsVal)} al cambio de ${rateBCV.toFixed(2)} Bs/$ = $${usdEq.toFixed(2)} USD`;
    } else if (bsVal > 0) {
      downpaymentAmountUSD = 0;
      referenceText = "Ingresa la Tasa BCV de hoy para calcular la equivalencia en USD";
    } else {
      downpaymentAmountUSD = 0;
      referenceText = "Sin cuota inicial";
    }
  } else if (currency === "MIXED") {
    const usdVal = parseFloat(downpaymentAmountUsdInput ? downpaymentAmountUsdInput.value : 0) || 0;
    const bsVal = parseFloat(downpaymentAmountBsInput ? downpaymentAmountBsInput.value : 0) || 0;
    const rateBCV = parseFloat(downpaymentRateBcvInput ? downpaymentRateBcvInput.value : 0) || 0;
    downpaymentPaidUSD = usdVal;
    downpaymentPaidBs = bsVal;

    let bsUsdEq = 0;
    if (rateBCV > 0 && bsVal > 0) {
      bsUsdEq = bsVal / rateBCV;
      referenceText = `$${usdVal.toFixed(2)} USD + Bs. ${formatBs(bsVal)} (Ref: $${bsUsdEq.toFixed(2)} USD a ${rateBCV.toFixed(2)} Bs/$)`;
    } else if (bsVal > 0) {
      referenceText = `$${usdVal.toFixed(2)} USD en divisas (Indica Tasa BCV de hoy para sumar la parte en Bs)`;
    } else {
      referenceText = usdVal > 0 ? `$${usdVal.toFixed(2)} USD en divisas` : "Sin cuota inicial";
    }
    downpaymentAmountUSD = Math.min(totalSaleUSD, Math.max(0, usdVal + bsUsdEq));
  }

  // 3. Porcentaje que representa del total y Saldo restante
  const downpaymentPercent = totalSaleUSD > 0 ? (downpaymentAmountUSD / totalSaleUSD) * 100 : 0;
  const percentDisplay = downpaymentPercent % 1 === 0 ? downpaymentPercent.toFixed(0) : downpaymentPercent.toFixed(1);

  // Sincronizar el campo de porcentaje si el usuario no lo está editando activamente
  const percentInput = document.getElementById("credit-downpayment-percent");
  if (percentInput && document.activeElement !== percentInput && (!options || !options.skipPercentSync)) {
    percentInput.value = downpaymentAmountUSD > 0 ? percentDisplay : "0";
  }

  const remainingBalance = Math.max(0, totalSaleUSD - downpaymentAmountUSD);

  // 4. Monto de cada cuota (en USD)
  const installmentAmount = (remainingBalance > 0 && installmentsCount > 0) ? (remainingBalance / installmentsCount) : 0;

  if (isNaN(installmentAmount) || isNaN(remainingBalance)) {
    if (typeof addSystemLog === "function") {
      addSystemLog({
        level: "ERROR",
        action: "CALCULATION_ERROR",
        details: { totalSaleUSD, downpaymentAmountUSD, remainingBalance, installmentsCount, installmentAmount },
        status: "failed",
        errorMessage: "Error en cálculo de cuotas: valor no numérico (NaN)"
      });
    }
  }

  // Pintar en DOM
  document.getElementById("calc-products-total").textContent = `$${productsTotal.toFixed(2)}`;
  document.getElementById("calc-shipping-total").textContent = shippingAmount > 0 ? `+$${shippingAmount.toFixed(2)}` : "$0.00";
  document.getElementById("calc-sale-total").textContent = `$${totalSaleUSD.toFixed(2)}`;
  document.getElementById("calc-downpayment-amount").textContent = `$${downpaymentAmountUSD.toFixed(2)} (${percentDisplay}% del total)`;
  document.getElementById("calc-remaining-balance").textContent = `$${remainingBalance.toFixed(2)}`;
  document.getElementById("calc-installment-amount").textContent = `$${installmentAmount.toFixed(2)} USD`;

  const calcPaidUsdEl = document.getElementById("calc-downpayment-paid-usd");
  const calcPaidBsEl = document.getElementById("calc-downpayment-paid-bs");
  const calcRefEl = document.getElementById("calc-downpayment-ref");
  if (calcPaidUsdEl) calcPaidUsdEl.textContent = `$${downpaymentPaidUSD.toFixed(2)}`;
  if (calcPaidBsEl) calcPaidBsEl.textContent = `Bs. ${formatBs(downpaymentPaidBs)}`;
  if (calcRefEl) calcRefEl.textContent = referenceText;

  // Totales separados
  const finalTotalDivisasEl = document.getElementById("calc-final-total-divisas");
  const finalTotalBsEl = document.getElementById("calc-final-total-bs");
  if (finalTotalDivisasEl) finalTotalDivisasEl.textContent = `$${downpaymentPaidUSD.toFixed(2)}`;
  if (finalTotalBsEl) finalTotalBsEl.textContent = `Bs. ${formatBs(downpaymentPaidBs)}`;

  // Cronograma estimado de cuotas según la frecuencia seleccionada (en USD)
  const frequencySelect = document.getElementById("credit-payment-frequency");
  const frequencyDays = frequencySelect ? (parseInt(frequencySelect.value, 10) || 30) : 30;

  const scheduleChipsContainer = document.getElementById("calc-schedule-list");
  if (scheduleChipsContainer) {
    if (remainingBalance <= 0 || installmentsCount <= 0) {
      scheduleChipsContainer.innerHTML = '<span class="schedule-chip">Pago al contado / Sin saldo financiado</span>';
    } else {
      let chipsHtml = "";
      const now = new Date();
      for (let i = 1; i <= installmentsCount; i++) {
        const dueDate = new Date(now.getTime() + i * frequencyDays * 24 * 60 * 60 * 1000);
        chipsHtml += `<span class="schedule-chip">Cuota ${i}: ${formatDateDisplay(dueDate)} ($${installmentAmount.toFixed(2)} USD)</span>`;
      }
      scheduleChipsContainer.innerHTML = chipsHtml;
    }
  }
}

// Procesar guardado de nuevo crédito (La tasa BCV no se fija aquí, cada cuota usa la tasa del día que se pague)
function handleCreditFormSubmit(e) {
  e.preventDefault();

  const clientSelect = document.getElementById("credit-client-select");
  const clientId = clientSelect.value;
  const errorMsg = document.getElementById("credit-form-error");

  if (!clientId) {
    if (errorMsg) {
      errorMsg.textContent = "Por favor selecciona un cliente para el crédito.";
      errorMsg.style.display = "block";
    }
    if (typeof addSystemLog === "function") {
      addSystemLog({
        level: "WARNING",
        action: "VALIDATION_ERROR",
        details: { form: "credit", reason: "Cliente no seleccionado" },
        status: "failed",
        errorMessage: "Por favor selecciona un cliente para el crédito."
      });
    }
    clientSelect.focus();
    return;
  }

  if (currentCreditItems.length === 0) {
    if (errorMsg) {
      errorMsg.textContent = "Debes añadir al menos un producto a la venta.";
      errorMsg.style.display = "block";
    }
    if (typeof addSystemLog === "function") {
      addSystemLog({
        level: "WARNING",
        action: "VALIDATION_ERROR",
        details: { form: "credit", reason: "Sin productos seleccionados" },
        status: "failed",
        errorMessage: "Debes añadir al menos un producto a la venta."
      });
    }
    return;
  }

  const clients = getStoredClients();
  const clientObj = clients.find((c) => String(c.id) === String(clientId));
  if (!clientObj) {
    if (errorMsg) {
      errorMsg.textContent = "Cliente no encontrado.";
      errorMsg.style.display = "block";
    }
    return;
  }

  const hasShipping = document.getElementById("credit-has-shipping").checked;
  const shippingAmount = hasShipping ? (parseFloat(document.getElementById("credit-shipping-amount").value) || 0) : 0;
  const installmentsCount = Math.min(24, Math.max(1, parseInt(document.getElementById("credit-installments-count").value, 10) || 1));

  const productsTotal = currentCreditItems.reduce((acc, item) => acc + item.subtotal, 0);
  const totalSaleUSD = productsTotal + shippingAmount;

  // Manejo de la inicial de monto libre
  const downpaymentCurrencySelect = document.getElementById("credit-downpayment-currency");
  const currency = downpaymentCurrencySelect ? downpaymentCurrencySelect.value : "USD";

  const downpaymentAmountUsdInput = document.getElementById("credit-downpayment-amount-usd");
  const downpaymentAmountBsInput = document.getElementById("credit-downpayment-amount-bs");
  const downpaymentRateBcvInput = document.getElementById("credit-downpayment-rate-bcv");

  let downpaymentAmountUSD = 0;
  let downpaymentPaidUSD = 0;
  let downpaymentPaidBs = 0;
  let downpaymentRefText = "";
  let initialRateBCV = null;

  if (currency === "USD") {
    const usdVal = parseFloat(downpaymentAmountUsdInput ? downpaymentAmountUsdInput.value : 0) || 0;
    downpaymentPaidUSD = usdVal;
    downpaymentAmountUSD = Math.min(totalSaleUSD, Math.max(0, usdVal));
    downpaymentPaidBs = 0;
    downpaymentRefText = usdVal > 0 ? `$${usdVal.toFixed(2)} USD en divisas` : "Sin cuota inicial";
  } else if (currency === "BS") {
    const bsVal = parseFloat(downpaymentAmountBsInput ? downpaymentAmountBsInput.value : 0) || 0;
    const rateBCV = parseFloat(downpaymentRateBcvInput ? downpaymentRateBcvInput.value : 0) || 0;
    if (bsVal > 0 && rateBCV <= 0) {
      if (errorMsg) {
        errorMsg.textContent = "Por favor ingresa la Tasa BCV de hoy para calcular la inicial en Bolívares.";
        errorMsg.style.display = "block";
      }
      if (typeof addSystemLog === "function") {
        addSystemLog({
          level: "WARNING",
          action: "VALIDATION_ERROR",
          details: { form: "credit", reason: "Tasa BCV de hoy requerida para inicial en Bolívares" },
          status: "failed",
          errorMessage: "Tasa BCV de hoy requerida para inicial en Bolívares"
        });
      }
      if (downpaymentRateBcvInput) downpaymentRateBcvInput.focus();
      return;
    }
    initialRateBCV = rateBCV > 0 ? rateBCV : null;
    downpaymentPaidUSD = 0;
    downpaymentPaidBs = bsVal;
    const usdEq = (rateBCV > 0 && bsVal > 0) ? (bsVal / rateBCV) : 0;
    downpaymentAmountUSD = Math.min(totalSaleUSD, Math.max(0, usdEq));
    downpaymentRefText = bsVal > 0 ? `Bs. ${formatBs(bsVal)} al cambio de ${rateBCV.toFixed(2)} Bs/$ = $${usdEq.toFixed(2)} USD` : "Sin cuota inicial";
  } else if (currency === "MIXED") {
    const usdVal = parseFloat(downpaymentAmountUsdInput ? downpaymentAmountUsdInput.value : 0) || 0;
    const bsVal = parseFloat(downpaymentAmountBsInput ? downpaymentAmountBsInput.value : 0) || 0;
    const rateBCV = parseFloat(downpaymentRateBcvInput ? downpaymentRateBcvInput.value : 0) || 0;
    if (bsVal > 0 && rateBCV <= 0) {
      if (errorMsg) {
        errorMsg.textContent = "Por favor ingresa la Tasa BCV de hoy para calcular la parte de la inicial en Bolívares.";
        errorMsg.style.display = "block";
      }
      if (typeof addSystemLog === "function") {
        addSystemLog({
          level: "WARNING",
          action: "VALIDATION_ERROR",
          details: { form: "credit", reason: "Tasa BCV de hoy requerida para parte mixta en Bolívares" },
          status: "failed",
          errorMessage: "Tasa BCV de hoy requerida para inicial mixta"
        });
      }
      if (downpaymentRateBcvInput) downpaymentRateBcvInput.focus();
      return;
    }
    initialRateBCV = rateBCV > 0 ? rateBCV : null;
    downpaymentPaidUSD = usdVal;
    downpaymentPaidBs = bsVal;
    const bsUsdEq = (rateBCV > 0 && bsVal > 0) ? (bsVal / rateBCV) : 0;
    downpaymentAmountUSD = Math.min(totalSaleUSD, Math.max(0, usdVal + bsUsdEq));
    downpaymentRefText = `$${usdVal.toFixed(2)} USD + Bs. ${formatBs(bsVal)}` + (rateBCV > 0 ? ` (al cambio de ${rateBCV.toFixed(2)} Bs/$)` : "");
  }

  const downpaymentPercentInput = document.getElementById("credit-downpayment-percent");
  const percentVal = parseFloat(downpaymentPercentInput ? downpaymentPercentInput.value : 0) || 0;
  const downpaymentPercentNum = totalSaleUSD > 0 ? ((downpaymentAmountUSD / totalSaleUSD) * 100) : 0;
  const downpaymentPercent = percentVal > 0 && Math.abs(percentVal - downpaymentPercentNum) < 1 
    ? percentVal 
    : (downpaymentPercentNum % 1 === 0 ? downpaymentPercentNum : parseFloat(downpaymentPercentNum.toFixed(1)));

  const remainingBalance = Math.max(0, totalSaleUSD - downpaymentAmountUSD);
  const installmentAmount = (remainingBalance > 0 && installmentsCount > 0) ? (remainingBalance / installmentsCount) : 0;

  const frequencySelect = document.getElementById("credit-payment-frequency");
  const frequencyDays = frequencySelect ? (parseInt(frequencySelect.value, 10) || 30) : 30;
  const frequencyLabel = frequencySelect ? frequencySelect.options[frequencySelect.selectedIndex].text : "Mensual (cada 30 días)";

  // Generar plan de cuotas (en USD - la tasa BCV no se fija aquí)
  const installments = [];
  const now = new Date();
  for (let i = 1; i <= installmentsCount; i++) {
    const dueDateObj = new Date(now.getTime() + i * frequencyDays * 24 * 60 * 60 * 1000);
    const dueDateStr = dueDateObj.toISOString().split("T")[0]; // YYYY-MM-DD
    installments.push({
      number: i,
      dueDate: dueDateStr,
      amountUSD: installmentAmount,
      status: downpaymentAmountUSD >= totalSaleUSD ? "Pagada" : "Pendiente"
    });
  }

  const newCredit = {
    id: "cred_" + Date.now(),
    createdAt: Date.now(),
    clientId: clientObj.id,
    client: {
      id: clientObj.id,
      name: clientObj.name,
      dni: clientObj.dni,
      phone: clientObj.phone,
      address: clientObj.address
    },
    items: currentCreditItems.map((it, idx) => {
      const q = parseInt(it.cantidad !== undefined ? it.cantidad : (it.quantity !== undefined ? it.quantity : it.qty), 10) || 1;
      const p = parseFloat(it.precioUnitario !== undefined ? it.precioUnitario : (it.price !== undefined ? it.price : (it.priceUSD !== undefined ? it.priceUSD : it.unitPrice))) || 0;
      const tot = parseFloat(it.totalLinea !== undefined ? it.totalLinea : it.subtotal) || parseFloat((q * p).toFixed(2));
      const n = String(it.nombre || it.name || "Producto").trim();
      return {
        id: it.id || `item_${Date.now()}_${idx}`,
        productId: it.productId || "",
        name: n,
        nombre: n,
        quantity: q,
        qty: q,
        cantidad: q,
        price: p,
        priceUSD: p,
        precioUnitario: p,
        unitPrice: p,
        subtotal: tot,
        totalLinea: tot
      };
    }),
    downpaymentCurrency: currency,
    downpaymentAmount: downpaymentAmountUSD,
    downpaymentPercent,
    downpaymentPaidUSD,
    downpaymentPaidBs,
    downpaymentRefText,
    totalDivisasPaid: downpaymentPaidUSD,
    totalBsPaid: downpaymentPaidBs,
    installmentsCount,
    paymentFrequency: frequencyDays,
    paymentFrequencyLabel: frequencyLabel,
    hasShipping,
    shippingAmount,
    productsTotal,
    totalSaleUSD,
    rateBCV: initialRateBCV,
    initialRateBCV: initialRateBCV,
    remainingBalance,
    installmentAmount,
    installments,
    payments: []
  };

  // Si entregó cuota inicial, registrarla de inmediato en el historial de pagos
  if (downpaymentAmountUSD > 0) {
    newCredit.payments.push({
      id: "pay_init_" + Date.now(),
      date: new Date().toISOString(),
      description: "Cuota inicial",
      amountUSD: downpaymentAmountUSD,
      currency,
      rateBCVToday: initialRateBCV,
      amountBs: downpaymentPaidBs,
      remainingBalanceAfter: remainingBalance
    });
  }

  const performSaveCredit = () => {
    // Restar automáticamente la cantidad de cada producto usado si tiene cantidad definida
    const storedProducts = getStoredProducts();
    currentCreditItems.forEach((item) => {
      const prod = storedProducts.find((p) => String(p.id) === String(item.productId));
      if (prod && prod.quantity !== null && prod.quantity !== undefined && prod.quantity !== "") {
        const currentStock = parseInt(prod.quantity, 10) || 0;
        prod.quantity = currentStock - item.quantity;
      }
    });
    saveProductsToStorage(storedProducts);
    renderProducts();

    // Guardar crédito en historial
    const currentCredits = getStoredCredits();
    currentCredits.unshift(newCredit);
    saveCreditsToStorage(currentCredits);

    if (typeof addSystemLog === "function") {
      addSystemLog({
        level: "INFO",
        action: "CREATE_CREDIT",
        details: {
          id: newCredit.id,
          clienteId: clientObj.id,
          clienteNombre: clientObj.name,
          montoTotalUSD: newCredit.totalSaleUSD,
          cuotas: newCredit.installmentsCount,
          inicialUSD: newCredit.downpaymentAmount,
          saldoUSD: newCredit.remainingBalance,
          fecha: new Date(newCredit.createdAt).toISOString()
        },
        status: "success"
      });

      addSystemLog({
        level: "INFO",
        action: "CALCULATE_INSTALLMENTS",
        details: {
          creditId: newCredit.id,
          totalSaleUSD: newCredit.totalSaleUSD,
          remainingBalance: newCredit.remainingBalance,
          installmentsCount: newCredit.installmentsCount,
          installmentAmountUSD: newCredit.installmentAmount
        },
        status: "success"
      });
    }

    closeCreditModal();
    renderCredits();
  };

  // PARTE 2 — Alerta de múltiples créditos activos al crear crédito
  const allCredits = getStoredCredits();
  const targetDni = clientObj && clientObj.dni ? String(clientObj.dni).trim().toLowerCase() : "";
  const targetName = clientObj && clientObj.name ? String(clientObj.name).trim().toLowerCase() : "";
  const activeCredits = allCredits.filter((c) => {
    const isThisClient = (clientId && (String(c.clientId) === String(clientId) || (c.client && String(c.client.id) === String(clientId)))) ||
                         (targetDni && c.client && c.client.dni && String(c.client.dni).trim().toLowerCase() === targetDni) ||
                         (targetDni && c.clientCedula && String(c.clientCedula).trim().toLowerCase() === targetDni) ||
                         (targetName && c.client && c.client.name && String(c.client.name).trim().toLowerCase() === targetName) ||
                         (targetName && c.clientName && String(c.clientName).trim().toLowerCase() === targetName);
    if (!isThisClient) return false;
    const st = String(c.status || "").trim().toLowerCase();
    return st !== "pagado" && st !== "cancelado";
  });

  const activeCount = activeCredits.length;

  const proceedWithCreditSave = () => {
    if (activeCount >= 1) {
      if (typeof addSystemLog === "function") {
        addSystemLog({
          level: "WARNING",
          action: "CREDIT_LIMIT_EXCEEDED",
          details: {
            clientId: clientObj.id,
            clientName: clientObj.name,
            activeCreditsCount: activeCount
          },
          status: "failed",
          errorMessage: `El cliente ${clientObj.name} ya tiene ${activeCount} crédito(s) activo(s)`
        });
      }
      showActiveCreditsWarningModal(activeCount, performSaveCredit);
      return;
    }
    performSaveCredit();
  };

  if (typeof checkItemsCatalogStatus === "function") {
    checkItemsCatalogStatus(currentCreditItems, proceedWithCreditSave, "credit-product-select", "credito");
  } else {
    proceedWithCreditSave();
  }
}

// ============================================================
// MODAL DE ADVERTENCIA: MÚLTIPLES CRÉDITOS ACTIVOS AL CREAR
// ============================================================
let pendingActiveCreditsCallback = null;

function showActiveCreditsWarningModal(activeCount, onConfirm) {
  setupActiveCreditsModalEvents();
  const modal = document.getElementById("modal-active-credits-confirm");
  const msgEl = document.getElementById("active-credits-message");
  const inputEl = document.getElementById("input-active-credits-word");
  const btnConfirm = document.getElementById("btn-confirm-active-credits");

  if (!modal) {
    if (confirm(`⚠️ Este cliente ya tiene ${activeCount} crédito(s) activo(s). ¿Deseas crear uno adicional?`)) {
      if (typeof onConfirm === "function") onConfirm();
    }
    return;
  }

  pendingActiveCreditsCallback = onConfirm;

  if (msgEl) {
    msgEl.textContent = `⚠️ Este cliente ya tiene ${activeCount} crédito(s) activo(s). ¿Deseas crear uno adicional?`;
  }

  if (inputEl) {
    inputEl.value = "";
  }

  if (btnConfirm) {
    btnConfirm.disabled = true;
  }

  modal.classList.remove("hidden");
  if (inputEl) {
    inputEl.focus();
  }
}

function closeActiveCreditsWarningModal() {
  const modal = document.getElementById("modal-active-credits-confirm");
  const inputEl = document.getElementById("input-active-credits-word");
  const btnConfirm = document.getElementById("btn-confirm-active-credits");

  if (modal) modal.classList.add("hidden");
  if (inputEl) inputEl.value = "";
  if (btnConfirm) btnConfirm.disabled = true;
  pendingActiveCreditsCallback = null;
}

function setupActiveCreditsModalEvents() {
  const inputEl = document.getElementById("input-active-credits-word");
  const btnConfirm = document.getElementById("btn-confirm-active-credits");
  const btnCancel = document.getElementById("btn-cancel-active-credits");
  const btnCloseX = document.getElementById("btn-close-active-credits-x");
  const modal = document.getElementById("modal-active-credits-confirm");

  if (inputEl && !inputEl.dataset.bound) {
    inputEl.dataset.bound = "true";
    inputEl.addEventListener("input", () => {
      const isAccepted = inputEl.value.trim().toLowerCase() === "acepto";
      if (btnConfirm) btnConfirm.disabled = !isAccepted;
    });
    inputEl.addEventListener("keydown", (e) => {
      if (e.key === "Enter") {
        e.preventDefault();
        if (btnConfirm && !btnConfirm.disabled) {
          btnConfirm.click();
        }
      }
    });
  }

  if (btnConfirm && !btnConfirm.dataset.bound) {
    btnConfirm.dataset.bound = "true";
    btnConfirm.addEventListener("click", () => {
      if (inputEl && inputEl.value.trim().toLowerCase() !== "acepto") return;
      const callback = pendingActiveCreditsCallback;
      closeActiveCreditsWarningModal();
      if (typeof callback === "function") {
        callback();
      }
    });
  }

  if (btnCancel && !btnCancel.dataset.bound) {
    btnCancel.dataset.bound = "true";
    btnCancel.addEventListener("click", closeActiveCreditsWarningModal);
  }

  if (btnCloseX && !btnCloseX.dataset.bound) {
    btnCloseX.dataset.bound = "true";
    btnCloseX.addEventListener("click", closeActiveCreditsWarningModal);
  }

  if (modal && !modal.dataset.bound) {
    modal.dataset.bound = "true";
    modal.addEventListener("click", (e) => {
      if (e.target === modal) closeActiveCreditsWarningModal();
    });
  }
}

// ============================================================
// AUDITORÍA DE ESTADOS DE CRÉDITO Y NOTIFICACIONES NATIVAS
// ============================================================

let overdueActionQueue = [];
let isOverdueModalOpen = false;
let currentOverdueItem = null;

// Envío de notificaciones nativas del navegador con Notification API y fallback
function sendNativeNotification(title, body) {
  if (typeof addSystemLog === "function") {
    addSystemLog({
      level: "INFO",
      action: "NOTIFICATION_SENT",
      details: { title, body },
      status: "success"
    });
  }

  if (!("Notification" in window)) {
    alert(`${title}\n\n${body}`);
    return;
  }

  if (Notification.permission === "granted") {
    try {
      new Notification(title, {
        body: body,
        icon: "icon-192.png"
      });
      return;
    } catch (e) {
      alert(`${title}\n\n${body}`);
      return;
    }
  }

  if (Notification.permission !== "denied") {
    Notification.requestPermission().then((permission) => {
      if (permission === "granted") {
        try {
          new Notification(title, {
            body: body,
            icon: "icon-192.png"
          });
        } catch (e) {
          alert(`${title}\n\n${body}`);
        }
      } else {
        alert(`${title}\n\n${body}`);
      }
    }).catch(() => {
      alert(`${title}\n\n${body}`);
    });
    return;
  }

  // Si el permiso fue denegado explícitamente
  alert(`${title}\n\n${body}`);
}

// PARTE 1 & PARTE 2: Auditoría automática de estados de crédito
function auditCreditStatuses() {
  const credits = getStoredCredits();
  if (!credits || credits.length === 0) return;

  const now = new Date();
  const yyyy = now.getFullYear();
  const mm = String(now.getMonth() + 1).padStart(2, "0");
  const dd = String(now.getDate()).padStart(2, "0");
  const todayStr = `${yyyy}-${mm}-${dd}`;

  let hasChanges = false;
  const newlyCortadoCredits = [];

  credits.forEach((credit) => {
    // Si ya está pagado por completo, no auditar
    if (credit.status === "pagado" || (credit.remainingBalance !== undefined && credit.remainingBalance <= 0)) {
      return;
    }

    const installments = Array.isArray(credit.installments) ? credit.installments : [];
    // Busca la próxima cuota sin pagar (installments donde paid === false)
    const nextUnpaid = installments.find(
      (inst) => !inst.paid && inst.status !== "Pagada" && !inst.merged && inst.status !== "Fusionada"
    );

    if (!nextUnpaid) {
      if (credit.status !== "pagado") {
        credit.status = "pagado";
        hasChanges = true;
      }
      return;
    }

    const dueStr = String(nextUnpaid.dueDate || "").substring(0, 10);
    if (!dueStr) return;

    // Regla de estados:
    // Si hoy < dueDate → estado "Solvente"
    // Si hoy === dueDate (mismo día calendario) → estado "Pendiente"
    // Si hoy > dueDate → estado "Cortado"
    let newStatus = "Solvente";
    if (todayStr < dueStr) {
      newStatus = "Solvente";
    } else if (todayStr === dueStr) {
      newStatus = "Pendiente";
    } else {
      newStatus = "Cortado";
    }

    const previousStatus = credit.status;

    if (newStatus !== previousStatus) {
      credit.status = newStatus;
      hasChanges = true;

      const clientName = credit.client ? (credit.client.name || "Cliente") : "Cliente";
      const instAmount = nextUnpaid.amountUSD !== undefined
        ? parseFloat(nextUnpaid.amountUSD)
        : (parseFloat(nextUnpaid.amount) || 0);

      const auditReason = todayStr < dueStr ? "Fecha anterior a vencimiento" : (todayStr === dueStr ? "Vence hoy" : "Cuota vencida (en mora)");
      if (typeof addSystemLog === "function") {
        addSystemLog({
          level: "INFO",
          action: "AUDIT_STATUS_CHANGE",
          details: {
            creditId: credit.id,
            cliente: clientName,
            de: previousStatus,
            hacia: newStatus,
            razon: auditReason
          },
          status: "success"
        });
      }

      // PARTE 2 — Notificaciones por Notification API (sin backend)
      if (newStatus === "Pendiente") {
        sendNativeNotification(
          "📋 Pago pendiente hoy",
          `Hoy le toca pagar a ${clientName} — $${instAmount.toFixed(2)} USD`
        );
      } else if (newStatus === "Cortado") {
        sendNativeNotification(
          "⚠️ Cuota vencida",
          `La cuota de ${clientName} venció hoy. Abre HogarFlex para gestionar.`
        );

        // PARTE 3 — Encolar para modal de acciones cuando un crédito pasa a "Cortado"
        newlyCortadoCredits.push({
          credit,
          installment: nextUnpaid,
          clientName,
          amount: instAmount
        });
      }
    }
  });

  if (hasChanges) {
    try {
      localStorage.setItem(CREDITS_STORAGE_KEY, JSON.stringify(credits));
    } catch (err) {
      console.error("Error al persistir créditos tras auditoría:", err);
    }
    // Si el estado cambió respecto al anterior, llama a triggerAutoCloudBackup("creditos")
    if (typeof triggerAutoCloudBackup === "function") {
      triggerAutoCloudBackup("creditos");
    }
    // Actualizar visualización en tabla si ya está montada
    if (typeof renderCredits === "function") {
      renderCredits();
    }
  }

  // PARTE 3: Si hay varios créditos cortados, el modal se muestra uno por uno en secuencia
  if (newlyCortadoCredits.length > 0) {
    initOverdueActionQueue(newlyCortadoCredits);
  }
}

// Iniciar cola de modales de acciones para créditos cortados
function initOverdueActionQueue(items) {
  overdueActionQueue = [...overdueActionQueue, ...items];
  if (!isOverdueModalOpen) {
    showNextOverdueActionModal();
  }
}

// Mostrar el siguiente modal en la secuencia
function showNextOverdueActionModal() {
  const modal = document.getElementById("modal-credit-overdue-action");
  if (!modal) return;

  if (overdueActionQueue.length === 0) {
    modal.classList.add("hidden");
    isOverdueModalOpen = false;
    currentOverdueItem = null;
    return;
  }

  isOverdueModalOpen = true;
  currentOverdueItem = overdueActionQueue.shift();

  const { credit, installment, clientName, amount } = currentOverdueItem;

  // Título: "⚠️ Cuota vencida — [nombre del cliente]"
  const titleEl = document.getElementById("modal-overdue-action-title");
  if (titleEl) {
    titleEl.textContent = `⚠️ Cuota vencida — ${clientName}`;
  }

  // Mensaje: "La cuota de $[monto] USD venció hoy. ¿Qué acción deseas tomar?"
  const msgEl = document.getElementById("modal-overdue-action-msg");
  if (msgEl) {
    msgEl.textContent = `La cuota de $${amount.toFixed(2)} USD venció hoy. ¿Qué acción deseas tomar?`;
  }

  // Contador opcional si quedan más en cola
  const badgeCounter = document.getElementById("modal-overdue-action-badge-counter");
  if (badgeCounter) {
    if (overdueActionQueue.length > 0) {
      badgeCounter.textContent = `Pendientes en revisión: ${overdueActionQueue.length + 1}`;
      badgeCounter.style.display = "inline-block";
    } else {
      badgeCounter.style.display = "none";
    }
  }

  // Input de días por defecto (1-30 días)
  const daysInput = document.getElementById("input-flexibility-days");
  if (daysInput) {
    daysInput.value = "5";
  }

  modal.classList.remove("hidden");
}

// Opción 1 — Dar días de flexibilidad: desplaza la dueDate N días hacia adelante y cambia a "Solvente"
function applyFlexibilityAction() {
  if (!currentOverdueItem) return;

  const daysInput = document.getElementById("input-flexibility-days");
  const days = parseInt(daysInput ? daysInput.value : 5, 10);
  if (isNaN(days) || days < 1 || days > 30) {
    alert("Por favor ingresa un número de días válido entre 1 y 30.");
    return;
  }

  const { credit, installment } = currentOverdueItem;
  const credits = getStoredCredits();
  const targetCredit = credits.find((c) => String(c.id) === String(credit.id));

  if (targetCredit && Array.isArray(targetCredit.installments)) {
    const targetInst = targetCredit.installments.find(
      (inst) => inst.number === installment.number || inst.dueDate === installment.dueDate
    );

    const targetDate = new Date();
    targetDate.setDate(targetDate.getDate() + days);
    const yyyy = targetDate.getFullYear();
    const mm = String(targetDate.getMonth() + 1).padStart(2, "0");
    const dd = String(targetDate.getDate()).padStart(2, "0");
    const newDueDateStr = `${yyyy}-${mm}-${dd}`;

    if (targetInst) {
      targetInst.dueDate = newDueDateStr;
    }
    targetCredit.status = "Solvente";

    saveCreditsToStorage(credits);
    triggerAutoCloudBackup("creditos");
    renderCredits();
  }

  showNextOverdueActionModal();
}

// Opción 2 — Unir con siguiente cuota: marca merged: true, suma a installments[i+1].amount y queda "Fusionada"
function mergeWithNextInstallmentAction() {
  if (!currentOverdueItem) return;

  const { credit, installment } = currentOverdueItem;
  const credits = getStoredCredits();
  const targetCredit = credits.find((c) => String(c.id) === String(credit.id));

  if (!targetCredit || !Array.isArray(targetCredit.installments)) {
    showNextOverdueActionModal();
    return;
  }

  const instIdx = targetCredit.installments.findIndex(
    (inst) => inst.number === installment.number || (inst.dueDate === installment.dueDate && !inst.merged && inst.status !== "Pagada")
  );

  if (instIdx === -1) {
    showNextOverdueActionModal();
    return;
  }

  if (instIdx >= targetCredit.installments.length - 1) {
    alert("Esta es la última cuota del crédito, no hay una cuota siguiente con la cual unirla. Puedes aplicar días de flexibilidad (Opción 1).");
    return;
  }

  const currentInst = targetCredit.installments[instIdx];
  const nextInst = targetCredit.installments[instIdx + 1];

  const currentAmt = parseFloat(currentInst.amountUSD !== undefined ? currentInst.amountUSD : (currentInst.amount || 0)) || 0;
  const nextAmt = parseFloat(nextInst.amountUSD !== undefined ? nextInst.amountUSD : (nextInst.amount || 0)) || 0;
  const combinedAmt = Math.round((nextAmt + currentAmt) * 100) / 100;

  currentInst.merged = true;
  currentInst.status = "Fusionada";
  currentInst.amountUSD = 0;
  currentInst.amount = 0;

  nextInst.amount = combinedAmt;
  nextInst.amountUSD = combinedAmt;
  if (nextInst.originalAmountUSD !== undefined) {
    nextInst.originalAmountUSD = Math.round(((parseFloat(nextInst.originalAmountUSD) || nextAmt) + currentAmt) * 100) / 100;
  }

  // Recalcular estado del crédito tras fusionar cuota
  const nextUnpaidAfter = targetCredit.installments.find(
    (i) => !i.paid && i.status !== "Pagada" && !i.merged && i.status !== "Fusionada"
  );

  if (nextUnpaidAfter) {
    const now = new Date();
    const yyyy = now.getFullYear();
    const mm = String(now.getMonth() + 1).padStart(2, "0");
    const dd = String(now.getDate()).padStart(2, "0");
    const todayStr = `${yyyy}-${mm}-${dd}`;
    const dueStr = String(nextUnpaidAfter.dueDate || "").substring(0, 10);

    if (todayStr < dueStr) {
      targetCredit.status = "Solvente";
    } else if (todayStr === dueStr) {
      targetCredit.status = "Pendiente";
    } else {
      targetCredit.status = "Cortado";
    }
  } else {
    targetCredit.status = "Solvente";
  }

  saveCreditsToStorage(credits);
  triggerAutoCloudBackup("creditos");
  renderCredits();

  showNextOverdueActionModal();
}

// Opción 3 — Cerrar sin acción: deja el crédito en Cortado y pasa al siguiente en la secuencia
function closeOverdueActionModal() {
  showNextOverdueActionModal();
}

// Configurar eventos del modal de acciones de flexibilidad
function setupOverdueActionModalEvents() {
  const btnFlex = document.getElementById("btn-action-apply-flexibility");
  if (btnFlex && !btnFlex.dataset.bound) {
    btnFlex.dataset.bound = "true";
    btnFlex.addEventListener("click", applyFlexibilityAction);
  }

  const btnMerge = document.getElementById("btn-action-merge-next");
  if (btnMerge && !btnMerge.dataset.bound) {
    btnMerge.dataset.bound = "true";
    btnMerge.addEventListener("click", mergeWithNextInstallmentAction);
  }

  const btnClose = document.getElementById("btn-action-close-overdue");
  if (btnClose && !btnClose.dataset.bound) {
    btnClose.dataset.bound = "true";
    btnClose.addEventListener("click", closeOverdueActionModal);
  }

  const btnCloseX = document.getElementById("btn-close-overdue-modal-x");
  if (btnCloseX && !btnCloseX.dataset.bound) {
    btnCloseX.dataset.bound = "true";
    btnCloseX.addEventListener("click", closeOverdueActionModal);
  }
}

// PARTE 4 — Visual en lista de créditos
// "Solvente" → badge verde
// "Pendiente" → badge amarillo/naranja
// "Cortado" → badge rojo con animación de pulso suave
function getCreditStatus(credit) {
  const installments = Array.isArray(credit.installments) ? credit.installments : [];
  const unpaidInstallment = installments.find(
    (inst) => !inst.paid && inst.status !== "Pagada" && !inst.merged && inst.status !== "Fusionada"
  );

  if (!unpaidInstallment) {
    return {
      statusText: "Pagado",
      statusClass: "status-solvente status-ok",
      nextAmount: "$0.00",
      nextDueDate: "Completado"
    };
  }

  let statusText = credit.status;
  if (!statusText || !["Solvente", "Pendiente", "Cortado", "Pagado"].includes(statusText)) {
    const now = new Date();
    const yyyy = now.getFullYear();
    const mm = String(now.getMonth() + 1).padStart(2, "0");
    const dd = String(now.getDate()).padStart(2, "0");
    const todayStr = `${yyyy}-${mm}-${dd}`;
    const dueStr = String(unpaidInstallment.dueDate || "").substring(0, 10);

    if (!dueStr || todayStr < dueStr) {
      statusText = "Solvente";
    } else if (todayStr === dueStr) {
      statusText = "Pendiente";
    } else {
      statusText = "Cortado";
    }
  }

  let statusClass = "status-solvente";
  if (statusText === "Pendiente") {
    statusClass = "status-pendiente";
  } else if (statusText === "Cortado") {
    statusClass = "status-cortado";
  } else if (statusText === "Pagado") {
    statusClass = "status-solvente status-ok";
  }

  const amt = unpaidInstallment.amountUSD !== undefined
    ? parseFloat(unpaidInstallment.amountUSD)
    : (parseFloat(unpaidInstallment.amount) || 0);

  const nextAmountUSD = `$${amt.toFixed(2)} USD`;
  const dueDateObj = unpaidInstallment.dueDate ? new Date(unpaidInstallment.dueDate + "T00:00:00") : null;

  return {
    statusText,
    statusClass,
    nextAmount: nextAmountUSD,
    nextDueDate: dueDateObj ? formatDateDisplay(dueDateObj) : "-"
  };
}

// Renderizar tabla principal de créditos
function renderCredits() {
  const tbody = document.getElementById("credits-tbody");
  const noCreditsMsg = document.getElementById("no-credits-msg");
  const table = document.getElementById("credits-table");

  if (!tbody || !noCreditsMsg || !table) return;

  const credits = getStoredCredits();
  const clients = getStoredClients();

  if (credits.length === 0) {
    table.classList.add("hidden");
    noCreditsMsg.classList.remove("hidden");
    tbody.innerHTML = "";
    updateSelectedCreditsButton();
    return;
  }

  table.classList.remove("hidden");
  noCreditsMsg.classList.add("hidden");

  tbody.innerHTML = credits
    .map((credit) => {
      // Cliente seguro (si credit.client falta, busca por clientId o fallback)
      const clientObj = credit.client || clients.find((c) => String(c.id) === String(credit.clientId)) || { name: "Cliente", dni: "-" };
      const clientName = clientObj.name || "Cliente";
      const clientDni = clientObj.dni || "-";

      // Resumen de productos seguro
      const productsSummary = (credit.items && Array.isArray(credit.items) && credit.items.length > 0)
        ? credit.items.map((item) => `${escapeHtml(item.name || "Producto")} (x${item.quantity || 1})`).join(", ")
        : "Sin productos";

      // Cuotas pagadas / totales seguro
      const installments = Array.isArray(credit.installments) ? credit.installments : [];
      const paidCount = installments.filter((inst) => inst.status === "Pagada").length;
      const totalCount = installments.length;
      const cuotasRatio = `${paidCount}/${totalCount}`;

      // Estado y próxima cuota
      const statusInfo = getCreditStatus(credit);

      // Cuota inicial mostrada según la moneda pagada sin mezclar
      const downpaymentAmount = parseFloat(credit.downpaymentAmount) || 0;
      const downpaymentPercent = credit.downpaymentPercent !== undefined ? credit.downpaymentPercent : 0;
      const downpaymentPaidUSD = parseFloat(credit.downpaymentPaidUSD) || 0;
      const downpaymentPaidBs = parseFloat(credit.downpaymentPaidBs) || 0;

      let downpaymentDisplay = `<strong>$${downpaymentAmount.toFixed(2)} USD</strong>`;
      if (downpaymentPaidBs > 0 && (!downpaymentPaidUSD || downpaymentPaidUSD === 0)) {
        downpaymentDisplay = `<strong>Bs. ${formatBs(downpaymentPaidBs)}</strong><br><span style="font-size: 0.76rem; color: var(--color-text-muted);">(Ref: $${downpaymentAmount.toFixed(2)} USD - ${downpaymentPercent}%)</span>`;
      } else if (downpaymentPaidUSD > 0 && downpaymentPaidBs > 0) {
        downpaymentDisplay = `<strong>$${downpaymentPaidUSD.toFixed(2)}</strong> + <strong>Bs. ${formatBs(downpaymentPaidBs)}</strong><br><span style="font-size: 0.76rem; color: var(--color-text-muted);">(${downpaymentPercent}%)</span>`;
      } else if (downpaymentAmount > 0) {
        downpaymentDisplay = `<strong>$${downpaymentAmount.toFixed(2)} USD</strong><br><span style="font-size: 0.76rem; color: var(--color-text-muted);">(${downpaymentPercent}%)</span>`;
      } else {
        downpaymentDisplay = `<strong>$0.00</strong>`;
      }

      const hasUnpaid = installments.some((inst) => inst.status !== "Pagada");

      return `
        <tr>
          <td style="width: 44px; text-align: center;">
            <input type="checkbox" class="credit-row-checkbox" data-id="${credit.id}" style="width: 17px; height: 17px; cursor: pointer;">
          </td>
          <td>
            <strong>${escapeHtml(clientName)}</strong><br>
            <span class="client-dni-badge" style="font-size: 0.76rem; padding: 2px 6px;">${escapeHtml(clientDni)}</span>
          </td>
          <td title="${escapeHtml(productsSummary)}" style="max-width: 220px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;">
            ${escapeHtml(productsSummary)}
          </td>
          <td>
            ${downpaymentDisplay}
          </td>
          <td>
            <span class="product-qty-badge">${cuotasRatio}</span>
          </td>
          <td>
            <strong>${statusInfo.nextAmount}</strong>
          </td>
          <td>
            ${statusInfo.nextDueDate}
          </td>
          <td>
            <span class="status-pill ${statusInfo.statusClass}">${statusInfo.statusText}</span>
          </td>
          <td class="actions-cell">
            <button type="button" class="btn-action-invoice" data-id="${credit.id}" title="Generar factura de crédito">📄 Factura</button>
            ${hasUnpaid
              ? `<button type="button" class="btn-action-pay-installment" data-id="${credit.id}">✓ Pagar cuota</button>`
              : `<button type="button" class="btn-action-pay-installment" disabled>✓ Pagado</button>`}
            ${hasUnpaid
              ? `<button type="button" class="btn-action-abonar" data-id="${credit.id}">💳 Abonar</button>`
              : `<button type="button" class="btn-action-abonar" disabled>Saldado</button>`}
            <button type="button" class="btn-action-view" data-id="${credit.id}">Ver detalle</button>
            <button type="button" class="btn-action-delete-credit btn-action-delete" data-id="${credit.id}" title="Eliminar crédito">🗑️ Eliminar</button>
          </td>
        </tr>
      `;
    })
    .join("");

  // Conectar botones Factura, Pagar Cuota, Abonar, Ver Detalle y Eliminar
  tbody.querySelectorAll(".btn-action-invoice").forEach((btn) => {
    btn.onclick = (e) => {
      e.preventDefault();
      const id = btn.getAttribute("data-id");
      if (id) generateAndOpenCreditInvoice(id);
    };
  });

  tbody.querySelectorAll(".btn-action-pay-installment").forEach((btn) => {
    btn.onclick = (e) => {
      e.preventDefault();
      const id = btn.getAttribute("data-id");
      if (id) openPayInstallmentModal(id);
    };
  });

  tbody.querySelectorAll(".btn-action-abonar").forEach((btn) => {
    btn.onclick = (e) => {
      e.preventDefault();
      const id = btn.getAttribute("data-id");
      if (id) openCreditPaymentModal(id);
    };
  });

  tbody.querySelectorAll(".btn-action-view").forEach((btn) => {
    btn.onclick = (e) => {
      e.preventDefault();
      const id = btn.getAttribute("data-id");
      if (id) openCreditDetailModal(id);
    };
  });

  tbody.querySelectorAll(".btn-action-delete-credit").forEach((btn) => {
    btn.onclick = (e) => {
      e.preventDefault();
      const id = btn.getAttribute("data-id");
      if (id) openDeleteCreditModal(id);
    };
  });

  // Delegación de eventos para checkboxes en el tbody de créditos
  if (tbody._creditCheckboxHandler) {
    tbody.removeEventListener("change", tbody._creditCheckboxHandler);
  }
  tbody._creditCheckboxHandler = (e) => {
    if (e.target && e.target.classList.contains("credit-row-checkbox")) {
      updateSelectedCreditsButton();
    }
  };
  tbody.addEventListener("change", tbody._creditCheckboxHandler);

  // Checkbox maestro para créditos
  const checkAllCredits = document.getElementById("check-all-credits");
  if (checkAllCredits) {
    if (checkAllCredits._masterHandler) {
      checkAllCredits.removeEventListener("change", checkAllCredits._masterHandler);
    }
    checkAllCredits._masterHandler = () => {
      const boxes = tbody.querySelectorAll(".credit-row-checkbox");
      boxes.forEach((cb) => {
        cb.checked = checkAllCredits.checked;
      });
      updateSelectedCreditsButton();
    };
    checkAllCredits.addEventListener("change", checkAllCredits._masterHandler);
  }

  updateSelectedCreditsButton();
}

// Abrir modal de detalle completo del crédito con monedas separadas
function openCreditDetailModal(creditId) {
  const credits = getStoredCredits();
  const credit = credits.find((c) => String(c.id) === String(creditId));
  if (!credit) return;

  currentDetailCreditId = creditId;
  const modal = document.getElementById("credit-detail-modal");

  // 1. Datos del cliente
  document.getElementById("detail-client-name").textContent = credit.client.name;
  document.getElementById("detail-client-dni").textContent = credit.client.dni;
  document.getElementById("detail-client-phone").textContent = credit.client.phone;
  document.getElementById("detail-client-address").textContent = credit.client.address;

  // 2. Productos comprados
  const productsTbody = document.getElementById("detail-products-tbody");
  productsTbody.innerHTML = credit.items
    .map((item) => `
      <tr>
        <td><strong>${escapeHtml(item.name)}</strong></td>
        <td>${item.quantity}</td>
        <td>$${item.price.toFixed(2)}</td>
        <td><strong>$${item.subtotal.toFixed(2)}</strong></td>
      </tr>
    `)
    .join("");

  // 3. Resumen financiero con monedas separadas
  // El saldo de un crédito siempre se muestra en USD directamente
  document.getElementById("detail-total-usd").textContent = `$${credit.totalSaleUSD.toFixed(2)}`;
  document.getElementById("detail-shipping-usd").textContent = credit.hasShipping ? `$${credit.shippingAmount.toFixed(2)}` : "$0.00";
  document.getElementById("detail-downpayment-usd").textContent = `$${credit.downpaymentAmount.toFixed(2)} (${credit.downpaymentPercent}%)`;
  document.getElementById("detail-remaining-usd").textContent = `$${credit.remainingBalance.toFixed(2)}`;
  
  const detailFreq = document.getElementById("detail-frequency");
  if (detailFreq) {
    detailFreq.textContent = credit.paymentFrequencyLabel || "Mensual (cada 30 días)";
  }

  const rateBcvEl = document.getElementById("detail-rate-bcv");
  if (rateBcvEl) rateBcvEl.textContent = "Variable (del día de pago)";

  const paidUSD = credit.totalDivisasPaid !== undefined ? credit.totalDivisasPaid : (credit.downpaymentPaidUSD !== undefined ? credit.downpaymentPaidUSD : (credit.downpaymentAmount || 0));
  const paidBs = credit.totalBsPaid !== undefined ? credit.totalBsPaid : (credit.downpaymentPaidBs || 0);

  const detailPaidUsdEl = document.getElementById("detail-downpayment-paid-usd");
  const detailPaidBsEl = document.getElementById("detail-downpayment-paid-bs");
  const detailRefEl = document.getElementById("detail-downpayment-ref");
  
  if (detailPaidUsdEl) detailPaidUsdEl.textContent = `$${paidUSD.toFixed(2)}`;
  if (detailPaidBsEl) detailPaidBsEl.textContent = `Bs. ${formatBs(paidBs)}`;
  if (detailRefEl) detailRefEl.textContent = credit.downpaymentRefText || "-";

  // Al final del resumen mostrar dos totales separados
  const detailTotalDivisasEl = document.getElementById("detail-total-divisas");
  const detailTotalBsEl = document.getElementById("detail-total-bs");
  if (detailTotalDivisasEl) detailTotalDivisasEl.textContent = `$${paidUSD.toFixed(2)}`;
  if (detailTotalBsEl) detailTotalBsEl.textContent = `Bs. ${formatBs(paidBs)}`;

  // 4. Tabla de cuotas (con montos en USD y nota de tasa del día)
  const scheduleTbody = document.getElementById("detail-schedule-tbody");
  const today = new Date();
  today.setHours(0, 0, 0, 0);

  scheduleTbody.innerHTML = credit.installments
    .map((inst) => {
      let instStatusBadge = '<span class="status-pill status-ok">Pagada</span>';
      let bcvNote = '<span style="color: #0284c7; font-size: 0.78rem;">Oficial del día al pagar</span>';

      if (inst.merged || inst.status === "Fusionada") {
        instStatusBadge = '<span class="status-pill" style="background:#f1f5f9; color:#475569; border:1px solid #cbd5e1;">Fusionada</span>';
        bcvNote = '<span style="color: #64748b; font-size: 0.8rem;">Unida a sig. cuota</span>';
      } else if (inst.status !== "Pagada") {
        const dueDate = new Date(inst.dueDate + "T00:00:00");
        const diffDays = Math.ceil((dueDate.getTime() - today.getTime()) / (1000 * 60 * 60 * 24));

        if (inst.status === "Parcialmente pagada") {
          instStatusBadge = '<span class="status-pill status-partial">Parcialmente pagada</span>';
        } else if (diffDays < 0) {
          instStatusBadge = '<span class="status-pill status-danger">Vencida</span>';
        } else if (diffDays <= 3) {
          instStatusBadge = '<span class="status-pill status-warning">Por vencer</span>';
        } else {
          instStatusBadge = '<span class="status-pill" style="background:#e0f2fe; color:#0369a1; border:1px solid #bae6fd;">Pendiente</span>';
        }
      } else {
        bcvNote = '<span style="color: #15803d; font-weight: 600; font-size: 0.8rem;">Liquidada</span>';
      }

      const formattedDueDate = formatDateDisplay(new Date(inst.dueDate + "T00:00:00"));
      const amountDetailDisplay = (inst.merged || inst.status === "Fusionada")
        ? `<strong style="color: #94a3b8; text-decoration: line-through;">$${(parseFloat(inst.amountUSD) || 0).toFixed(2)} USD</strong> <small style="color: var(--color-text-muted); display: block;">(Fusionada con sig. cuota)</small>`
        : (inst.status === "Parcialmente pagada" && inst.originalAmountUSD && inst.originalAmountUSD > inst.amountUSD)
          ? `<strong>$${inst.amountUSD.toFixed(2)} USD</strong> <small style="color: var(--color-text-muted); display: block;">(Resta de $${inst.originalAmountUSD.toFixed(2)})</small>`
          : `<strong>$${(parseFloat(inst.amountUSD !== undefined ? inst.amountUSD : inst.amount) || 0).toFixed(2)} USD</strong>`;

      return `
        <tr>
          <td><strong>Cuota ${inst.number}</strong></td>
          <td>${formattedDueDate}</td>
          <td>${amountDetailDisplay}</td>
          <td>${bcvNote}</td>
          <td>${instStatusBadge}</td>
        </tr>
      `;
    })
    .join("");

  // 5. Historial de Pagos y Abonos Registrados
  const paymentsTbody = document.getElementById("detail-payments-tbody");
  const emptyPaymentsMsg = document.getElementById("empty-payments-msg");
  const payments = credit.payments || [];

  if (paymentsTbody && emptyPaymentsMsg) {
    if (payments.length === 0) {
      paymentsTbody.innerHTML = "";
      emptyPaymentsMsg.classList.remove("hidden");
    } else {
      emptyPaymentsMsg.classList.add("hidden");
      paymentsTbody.innerHTML = renderPaymentHistoryRows(credit, payments);
    }
  }

  // Actualizar botones de acción en el pie del detalle
  const btnPayInstDetail = document.getElementById("btn-pay-installment-from-detail");
  const btnAbonarDetail = document.getElementById("btn-open-payment-from-detail");
  const hasPending = credit.installments.some((inst) => inst.status !== "Pagada");

  if (btnPayInstDetail) {
    if (hasPending) {
      btnPayInstDetail.style.display = "inline-block";
      btnPayInstDetail.disabled = false;
      btnPayInstDetail.onclick = () => {
        openPayInstallmentModal(credit.id);
      };
    } else {
      btnPayInstDetail.style.display = "none";
    }
  }

  if (btnAbonarDetail) {
    if (hasPending) {
      btnAbonarDetail.style.display = "inline-block";
      btnAbonarDetail.disabled = false;
      btnAbonarDetail.onclick = () => {
        openCreditPaymentModal(credit.id);
      };
    } else {
      btnAbonarDetail.style.display = "none";
    }
  }

  const btnInvoiceDetail = document.getElementById("btn-generate-invoice-from-detail");
  if (btnInvoiceDetail) {
    btnInvoiceDetail.onclick = () => {
      generateAndOpenCreditInvoice(credit.id);
    };
  }

  modal.classList.remove("hidden");
}

function closeCreditDetailModal() {
  const modal = document.getElementById("credit-detail-modal");
  if (modal) modal.classList.add("hidden");
}

// ============================================================
// FUNCIONES DE PAGAR CUOTA FIJA PASO A PASO (CORRECCIÓN 3)
// ============================================================

let currentPayInstallmentCreditId = null;

function openPayInstallmentModal(creditId) {
  const credits = getStoredCredits();
  const credit = credits.find((c) => String(c.id) === String(creditId));
  if (!credit) return;

  const nextPending = credit.installments.find((i) => i.status !== "Pagada");
  if (!nextPending || credit.remainingBalance <= 0) {
    alert("Este crédito ya no tiene cuotas pendientes (está al día y totalmente saldado).");
    return;
  }

  currentPayInstallmentCreditId = creditId;

  const modal = document.getElementById("credit-pay-installment-modal");
  const form = document.getElementById("credit-pay-installment-form");
  const errorBanner = document.getElementById("pay-installment-error");
  const currencySelect = document.getElementById("pay-inst-currency-select");
  const rateBcvBox = document.getElementById("pay-inst-rate-bcv-box");
  const rateBcvTodayInput = document.getElementById("pay-inst-rate-bcv-today");

  if (form) form.reset();
  if (errorBanner) {
    errorBanner.style.display = "none";
    errorBanner.textContent = "";
  }

  document.getElementById("pay-inst-credit-id").value = creditId;
  const clientName = (credit.client && credit.client.name) ? credit.client.name : "Cliente";
  const clientDni = (credit.client && credit.client.dni) ? credit.client.dni : "";
  const clientNameEl = document.getElementById("pay-inst-client-name");
  if (clientNameEl) clientNameEl.textContent = `${clientName} ${clientDni ? '(' + clientDni + ')' : ''}`;
  document.getElementById("pay-inst-number-badge").textContent = `Cuota ${nextPending.number} de ${credit.installments.length}`;
  document.getElementById("pay-inst-due-date").textContent = formatDateDisplay(new Date(nextPending.dueDate + "T00:00:00"));
  document.getElementById("pay-inst-amount-usd").textContent = `$${nextPending.amountUSD.toFixed(2)} USD`;
  document.getElementById("pay-inst-credit-balance").textContent = `$${credit.remainingBalance.toFixed(2)} USD`;

  const montoPagadoInstEl = document.getElementById("pay-inst-monto-pagado-input");
  if (montoPagadoInstEl) montoPagadoInstEl.value = `$${nextPending.amountUSD.toFixed(2)} USD`;

  // Fecha por defecto hoy
  const dateInput = document.getElementById("pay-inst-date");
  if (dateInput) {
    dateInput.value = new Date().toISOString().split("T")[0];
  }

  // Limpiar referencia y comprobante
  const refInput = document.getElementById("pay-inst-reference");
  if (refInput) refInput.value = "";
  currentPayInstReceiptBase64 = null;
  const receiptImg = document.getElementById("pay-inst-receipt-preview-img");
  const receiptPlaceholder = document.getElementById("pay-inst-receipt-placeholder");
  const btnRemoveReceipt = document.getElementById("btn-remove-pay-inst-receipt");
  const fileInput = document.getElementById("pay-inst-receipt-file");
  if (fileInput) fileInput.value = "";
  if (receiptImg) { receiptImg.src = ""; receiptImg.classList.add("hidden"); }
  if (receiptPlaceholder) receiptPlaceholder.classList.remove("hidden");
  if (btnRemoveReceipt) btnRemoveReceipt.classList.add("hidden");

  if (currencySelect) currencySelect.value = "USD";
  if (rateBcvBox) rateBcvBox.classList.add("hidden");
  if (rateBcvTodayInput) rateBcvTodayInput.value = "";

  const calcBsBox = document.getElementById("pay-inst-calc-bs-box");
  if (calcBsBox) calcBsBox.style.display = "none";

  updatePayInstallmentCalculations();

  modal.classList.remove("hidden");
}

function closePayInstallmentModal() {
  const modal = document.getElementById("credit-pay-installment-modal");
  const form = document.getElementById("credit-pay-installment-form");
  if (modal) modal.classList.add("hidden");
  if (form) form.reset();
  currentPayInstReceiptBase64 = null;
  const fileInput = document.getElementById("pay-inst-receipt-file");
  if (fileInput) fileInput.value = "";
  currentPayInstallmentCreditId = null;
}

function updatePayInstallmentCalculations() {
  const credits = getStoredCredits();
  const credit = credits.find((c) => String(c.id) === String(currentPayInstallmentCreditId));
  if (!credit) return;

  const nextPending = credit.installments.find((i) => i.status !== "Pagada");
  if (!nextPending) return;

  const currencySelect = document.getElementById("pay-inst-currency-select");
  const rateBcvBox = document.getElementById("pay-inst-rate-bcv-box");
  const rateBcvTodayInput = document.getElementById("pay-inst-rate-bcv-today");
  const calcBsBox = document.getElementById("pay-inst-calc-bs-box");
  const calcBsAmountEl = document.getElementById("pay-inst-calc-bs-amount");
  const calcBsFormulaEl = document.getElementById("pay-inst-calc-bs-formula");
  const montoPagadoInstEl = document.getElementById("pay-inst-monto-pagado-input");

  const currency = currencySelect ? currencySelect.value : "USD";

  if (currency === "BS") {
    if (rateBcvBox) rateBcvBox.classList.remove("hidden");
    if (calcBsBox) calcBsBox.style.display = "block";

    const rateBCV = parseFloat(rateBcvTodayInput ? rateBcvTodayInput.value : 0) || 0;
    if (rateBCV > 0) {
      const bsResult = nextPending.amountUSD * rateBCV;
      if (calcBsAmountEl) calcBsAmountEl.textContent = `Bs. ${formatBs(bsResult)}`;
      if (calcBsFormulaEl) calcBsFormulaEl.textContent = `Cálculo: $${nextPending.amountUSD.toFixed(2)} USD × ${rateBCV.toFixed(2)} Bs/$ = Bs. ${formatBs(bsResult)}`;
      if (montoPagadoInstEl) montoPagadoInstEl.value = `$${nextPending.amountUSD.toFixed(2)} USD (Cobro: Bs. ${formatBs(bsResult)})`;
    } else {
      if (calcBsAmountEl) calcBsAmountEl.textContent = "Bs. 0,00";
      if (calcBsFormulaEl) calcBsFormulaEl.textContent = "Ingresa la Tasa BCV de hoy para calcular el cobro de la cuota en Bolívares";
      if (montoPagadoInstEl) montoPagadoInstEl.value = `$${nextPending.amountUSD.toFixed(2)} USD`;
    }
  } else {
    if (rateBcvBox) rateBcvBox.classList.add("hidden");
    if (calcBsBox) calcBsBox.style.display = "none";
    if (montoPagadoInstEl) montoPagadoInstEl.value = `$${nextPending.amountUSD.toFixed(2)} USD`;
  }
}

function handlePayInstallmentSubmit(e) {
  e.preventDefault();

  const credits = getStoredCredits();
  const credit = credits.find((c) => String(c.id) === String(currentPayInstallmentCreditId));
  const errorBanner = document.getElementById("pay-installment-error");
  const currencySelect = document.getElementById("pay-inst-currency-select");
  const rateBcvTodayInput = document.getElementById("pay-inst-rate-bcv-today");
  const payDateInput = document.getElementById("pay-inst-date");
  const payDateVal = payDateInput && payDateInput.value ? payDateInput.value : new Date().toISOString().split("T")[0];
  const refInput = document.getElementById("pay-inst-reference");
  const referenceNumber = refInput ? refInput.value.trim() : "";

  if (!credit) {
    if (errorBanner) {
      errorBanner.textContent = "Crédito no encontrado.";
      errorBanner.style.display = "block";
    }
    return;
  }

  const nextPending = credit.installments.find((i) => i.status !== "Pagada");
  if (!nextPending) {
    if (errorBanner) {
      errorBanner.textContent = "Este crédito ya no tiene cuotas pendientes.";
      errorBanner.style.display = "block";
    }
    return;
  }

  const cuotaAmountUSD = nextPending.amountUSD;
  const currency = currencySelect ? currencySelect.value : "USD";
  let rateBCVToday = null;
  let montoBsResultante = 0;

  if (currency === "BS") {
    rateBCVToday = parseFloat(rateBcvTodayInput ? rateBcvTodayInput.value : 0) || 0;
    if (rateBCVToday <= 0) {
      if (errorBanner) {
        errorBanner.textContent = "Por favor ingresa la Tasa BCV de hoy para realizar el cobro en Bolívares.";
        errorBanner.style.display = "block";
      }
      if (typeof addSystemLog === "function") {
        addSystemLog({
          level: "WARNING",
          action: "VALIDATION_ERROR",
          details: { form: "pay_installment", reason: "Tasa BCV de hoy requerida para pago en Bolívares" },
          status: "failed",
          errorMessage: "Tasa BCV de hoy requerida para cobrar cuota en Bolívares"
        });
      }
      if (rateBcvTodayInput) rateBcvTodayInput.focus();
      return;
    }
    montoBsResultante = cuotaAmountUSD * rateBCVToday;
  }

  // 1. Marcar esta cuota específica como Pagada
  nextPending.status = "Pagada";
  nextPending.paidDate = payDateVal;
  nextPending.paidCurrency = currency;
  nextPending.rateBCVToday = rateBCVToday;
  nextPending.paidAmountBs = montoBsResultante;

  // 2. Descontar exactamente el monto de la cuota del saldo restante sin dejar en rojo y sin alterar las cuotas futuras
  const newBalance = Math.max(0, Math.round((credit.remainingBalance - cuotaAmountUSD) * 100) / 100);
  credit.remainingBalance = newBalance;

  // 3. Totales separados
  if (currency === "BS") {
    credit.totalBsPaid = (credit.totalBsPaid || 0) + montoBsResultante;
  } else {
    credit.totalDivisasPaid = (credit.totalDivisasPaid || 0) + cuotaAmountUSD;
  }

  // 4. Historial de pagos
  const newPayId = "pay_" + Date.now();
  credit.payments = credit.payments || [];
  credit.payments.push({
    id: newPayId,
    date: payDateVal,
    type: "cuota",
    description: `Pago Cuota ${nextPending.number}`,
    installmentNumber: nextPending.number,
    amountUSD: cuotaAmountUSD,
    currency,
    rateBCVToday: currency === "BS" ? rateBCVToday : null,
    amountBs: currency === "BS" ? montoBsResultante : 0,
    referenceNumber,
    receiptUrl: currentPayInstReceiptBase64 || null,
    remainingBalanceAfter: newBalance
  });

  saveCreditsToStorage(credits);

  if (typeof addSystemLog === "function") {
    addSystemLog({
      level: "INFO",
      action: "CREATE_PAYMENT",
      details: {
        creditoId: credit.id,
        pagoId: newPayId,
        monto: cuotaAmountUSD,
        moneda: currency,
        fecha: payDateVal,
        tipo: "cuota",
        cuotaNumero: nextPending.number,
        saldoRestanteUSD: newBalance
      },
      status: "success"
    });
  }

  closePayInstallmentModal();
  renderCredits();
  renderPagosSection();
  renderDashboardSection();

  // Si modal detalle estaba abierto, refrescarlo
  const detailModal = document.getElementById("credit-detail-modal");
  if (detailModal && !detailModal.classList.contains("hidden")) {
    openCreditDetailModal(credit.id);
  }

  // Si modal perfil cliente estaba abierto, refrescarlo
  const clientProfileModal = document.getElementById("client-profile-modal");
  if (clientProfileModal && !clientProfileModal.classList.contains("hidden")) {
    openClientProfileModal(credit.clientId);
  }

  // Si modal historial de pagos estaba abierto, refrescarlo
  const historyModal = document.getElementById("credit-payments-history-modal");
  if (historyModal && !historyModal.classList.contains("hidden")) {
    openCreditPaymentsHistoryModal(credit.id);
  }

  // Generar y abrir recibo de pago automáticamente
  generateAndOpenPaymentReceipt(credit.id, newPayId);

  if (currency === "BS") {
    alert(`¡Cuota #${nextPending.number} pagada con éxito!\n• Monto: $${cuotaAmountUSD.toFixed(2)} USD\n• Tasa BCV de hoy: ${rateBCVToday.toFixed(2)} Bs/$\n• Monto cobrado en Bs: Bs. ${formatBs(montoBsResultante)}\n• Saldo restante: $${newBalance.toFixed(2)} USD\nSe avanzó a la siguiente cuota sin alterar las cuotas futuras.`);
  } else {
    alert(`¡Cuota #${nextPending.number} pagada con éxito!\n• Monto: $${cuotaAmountUSD.toFixed(2)} USD\n• Saldo restante: $${newBalance.toFixed(2)} USD\nSe avanzó a la siguiente cuota sin alterar las cuotas futuras.`);
  }
}

// ============================================================
// FUNCIONES DE ABONO LIBRE QUE REDISTRIBUYE CUOTAS (CORRECCIÓN 3)
// ============================================================

// Abrir modal de registrar abono / pago libre
function openCreditPaymentModal(creditId) {
  const credits = getStoredCredits();
  const credit = credits.find((c) => String(c.id) === String(creditId));
  if (!credit) return;

  currentPaymentCreditId = creditId;

  const modal = document.getElementById("credit-payment-modal");
  const form = document.getElementById("credit-payment-form");
  const errorBanner = document.getElementById("payment-form-error");
  const amountInput = document.getElementById("payment-amount-input");
  const currencySelect = document.getElementById("payment-currency-select");
  const rateBcvBox = document.getElementById("payment-rate-bcv-box");
  const rateBcvTodayInput = document.getElementById("payment-rate-bcv-today");

  if (form) form.reset();
  if (errorBanner) {
    errorBanner.style.display = "none";
    errorBanner.textContent = "";
  }

  // Llenar resumen de deuda actual
  document.getElementById("payment-credit-id").value = creditId;
  const clientNameAbono = credit.clientName || (credit.client && credit.client.name) ? (credit.clientName || credit.client.name) : "Cliente";
  const clientDniAbono = credit.clientCi || credit.clientCedula || (credit.client && (credit.client.dni || credit.client.cedula)) || "";
  const clientNameAbonoEl = document.getElementById("pay-client-name");
  if (clientNameAbonoEl) clientNameAbonoEl.textContent = `${clientNameAbono} ${clientDniAbono ? '(' + clientDniAbono + ')' : ''}`;
  const totalSaleUSD = parseFloat(credit.totalSaleUSD !== undefined ? credit.totalSaleUSD : (credit.totalUSD !== undefined ? credit.totalUSD : (credit.total || credit.remainingBalance || 0))) || 0; document.getElementById("pay-total-debt").textContent = `$${totalSaleUSD.toFixed(2)} USD`;
  const remainingBal = parseFloat(credit.remainingBalance !== undefined ? credit.remainingBalance : 0) || 0; document.getElementById("pay-current-balance").textContent = `$${remainingBal.toFixed(2)} USD`;
  
  const installments = credit.installments || []; const pendingCount = installments.filter((i) => i.status !== "Pagada" && i.status !== "pagada").length;
  document.getElementById("pay-pending-count").textContent = `${pendingCount} cuota(s) pendiente(s) de ${installments.length}`;

  // Fecha por defecto hoy
  const dateInput = document.getElementById("payment-date");
  if (dateInput) {
    dateInput.value = new Date().toISOString().split("T")[0];
  }

  // Limpiar referencia y comprobante
  const refInput = document.getElementById("payment-reference");
  if (refInput) refInput.value = "";
  currentPaymentReceiptBase64 = null;
  const receiptImg = document.getElementById("payment-receipt-preview-img");
  const receiptPlaceholder = document.getElementById("payment-receipt-placeholder");
  const btnRemoveReceipt = document.getElementById("btn-remove-payment-receipt");
  const fileInput = document.getElementById("payment-receipt-file");
  if (fileInput) fileInput.value = "";
  if (receiptImg) { receiptImg.src = ""; receiptImg.classList.add("hidden"); }
  if (receiptPlaceholder) receiptPlaceholder.classList.remove("hidden");
  if (btnRemoveReceipt) btnRemoveReceipt.classList.add("hidden");

  if (currencySelect) currencySelect.value = "USD";
  if (rateBcvBox) rateBcvBox.classList.add("hidden");
  if (rateBcvTodayInput) rateBcvTodayInput.value = "";

  // Para abonar, la dueña ingresa un monto libre (ej. $10 o $100)
  if (amountInput) {
    amountInput.value = "";
    const nextPendingInst = (credit.installments || []).find((i) => i.status !== "Pagada" && i.status !== "pagada");
    const defaultAmountUSD = nextPendingInst ? (parseFloat(nextPendingInst.amountUSD !== undefined ? nextPendingInst.amountUSD : (nextPendingInst.amount || 0)) || 0) : 0;
    amountInput.value = defaultAmountUSD > 0 ? defaultAmountUSD.toFixed(2) : "";
    amountInput.placeholder = defaultAmountUSD > 0 ? defaultAmountUSD.toFixed(2) : "0.00";
  }
  const paymentAmountBsInput = document.getElementById("payment-amount-bs-input");
  if (paymentAmountBsInput) {
    paymentAmountBsInput.value = "";
  }

  updatePaymentCalculations();

  modal.classList.remove("hidden");
  if (amountInput) amountInput.focus();
}

// Cerrar modal de pago
function closeCreditPaymentModal() {
  const modal = document.getElementById("credit-payment-modal");
  const form = document.getElementById("credit-payment-form");
  if (modal) modal.classList.add("hidden");
  if (form) form.reset();
  currentPaymentReceiptBase64 = null;
  const fileInput = document.getElementById("payment-receipt-file");
  if (fileInput) fileInput.value = "";
  const paymentAmountBsInput = document.getElementById("payment-amount-bs-input");
  if (paymentAmountBsInput) paymentAmountBsInput.value = "";
  currentPaymentCreditId = null;
}

// Cálculo automático en tiempo real del abono con Tasa BCV de hoy
function updatePaymentCalculations() {
  const credits = getStoredCredits();
  const credit = credits.find((c) => String(c.id) === String(currentPaymentCreditId));
  if (!credit) return;

  const amountInput = document.getElementById("payment-amount-input");
  const currencySelect = document.getElementById("payment-currency-select");
  const currencyRef = document.getElementById("payment-currency-ref");
  const rateBcvBox = document.getElementById("payment-rate-bcv-box");
  const rateBcvTodayInput = document.getElementById("payment-rate-bcv-today");
  const calcBsBox = document.getElementById("calc-pay-bs-box");
  const calcBsAmountEl = document.getElementById("calc-pay-bs-amount");
  const calcBsFormulaEl = document.getElementById("calc-pay-bs-formula");
  const amountBsBox = document.getElementById("payment-amount-bs-box");
  const amountBsInput = document.getElementById("payment-amount-bs-input");
  const amountLabel = document.getElementById("payment-amount-label");
  const amountHint = document.getElementById("payment-amount-hint");

  const amountValUSD = parseFloat(amountInput.value) || 0;
  const currency = currencySelect ? currencySelect.value : "USD";

  let rateBCVToday = 0;
  let montoBsResultante = 0;

  if (currency === "BS") {
    if (rateBcvBox) rateBcvBox.classList.remove("hidden");
    if (amountBsBox) amountBsBox.classList.remove("hidden");
    if (amountLabel) amountLabel.textContent = "Equivalente en USD ($)";
    if (amountHint) amountHint.textContent = "Calculado según la Tasa BCV de hoy o editable";
    rateBCVToday = parseFloat(rateBcvTodayInput ? rateBcvTodayInput.value : 0) || 0;

    if (currencyRef) {
      currencyRef.textContent = "Cobro en Bolívares calculado con la tasa BCV ingresada hoy.";
    }

    if (calcBsBox && calcBsAmountEl && calcBsFormulaEl) {
      calcBsBox.style.display = "block";
      if (rateBCVToday > 0 && amountValUSD > 0) {
        montoBsResultante = amountValUSD * rateBCVToday;
        calcBsAmountEl.textContent = `Bs. ${formatBs(montoBsResultante)}`;
        calcBsFormulaEl.textContent = `Cálculo: $${amountValUSD.toFixed(2)} USD × ${rateBCVToday.toFixed(2)} Bs/$ = Bs. ${formatBs(montoBsResultante)}`;
      } else {
        calcBsAmountEl.textContent = "Bs. 0,00";
        calcBsFormulaEl.textContent = "Ingresa la Tasa BCV de hoy para calcular el monto exacto en Bolívares";
      }
    }
  } else {
    if (rateBcvBox) rateBcvBox.classList.add("hidden");
    if (amountBsBox) amountBsBox.classList.add("hidden");
    if (calcBsBox) calcBsBox.style.display = "none";
    if (amountLabel) amountLabel.textContent = "Monto a abonar (USD)";
    if (amountHint) amountHint.textContent = "Ingresa cualquier monto libre en dólares a abonar (ej: 10 o 100)";
    if (currencyRef) {
      currencyRef.textContent = "Pago directo en Divisas ($ USD) registrado sin conversión.";
    }
  }

  // 1. Monto pagado
  const calcAmountEl = document.getElementById("calc-pay-amount");
  if (calcAmountEl) calcAmountEl.textContent = `$${amountValUSD.toFixed(2)} USD`;

  // 2. Porcentaje que representa de la deuda total
  const totalDebtBase = parseFloat(credit.totalSaleUSD !== undefined ? credit.totalSaleUSD : (credit.totalUSD !== undefined ? credit.totalUSD : (credit.remainingBalance || 1))) || 1;
  const percentVal = totalDebtBase > 0 ? (amountValUSD / totalDebtBase) * 100 : 0;
  const percentFormatted = percentVal % 1 === 0 ? percentVal.toFixed(0) : percentVal.toFixed(1);

  const calcPercentEl = document.getElementById("calc-pay-percent");
  if (calcPercentEl) {
    calcPercentEl.textContent = `${percentFormatted}% (de la deuda total de $${totalDebtBase.toFixed(2)} USD)`;
  }

  // 3. Saldo restante (en USD)
  const creditRemaining = parseFloat(credit.remainingBalance !== undefined ? credit.remainingBalance : 0) || 0;
  const newRemainingBalance = Math.max(0, creditRemaining - amountValUSD);
  const calcRemainingEl = document.getElementById("calc-pay-remaining");
  if (calcRemainingEl) calcRemainingEl.textContent = `$${newRemainingBalance.toFixed(2)} USD`;

  // 4. Cómo se aplica el abono cuota por cuota en orden cronológico
  const redistListEl = document.getElementById("calc-pay-redistribution-list");
  if (!redistListEl) return;

  const pendingInstallments = credit.installments
    .filter((inst) => inst.status !== "Pagada")
    .sort((a, b) => (a.number || 0) - (b.number || 0));

  if (pendingInstallments.length === 0) {
    redistListEl.innerHTML = `<span style="color: #15803d; font-weight: 600;">Este crédito no tiene cuotas pendientes (está saldado).</span>`;
    return;
  }

  if (amountValUSD <= 0) {
    // Si no ha escrito monto, mostrar cuotas pendientes con su monto actual
    redistListEl.innerHTML = pendingInstallments.map((inst) => {
      const dueDate = new Date(inst.dueDate + "T00:00:00");
      const currentDue = Math.round((inst.amountUSD || 0) * 100) / 100;
      const partialTag = inst.status === "Parcialmente pagada" ? " <small style='color: #b45309;'>(Parcial)</small>" : "";
      return `
        <div style="display: flex; justify-content: space-between; align-items: center; padding: 5px 8px; background: #ffffff; border-radius: 4px; border: 1px solid #e2e8f0;">
          <span><strong>Cuota ${inst.number}</strong> (${formatDateDisplay(dueDate)}):</span>
          <strong style="color: var(--color-primary); font-size: 0.9rem;">$${currentDue.toFixed(2)} USD${partialTag}</strong>
        </div>
      `;
    }).join("");
    return;
  }

  if (newRemainingBalance <= 0) {
    redistListEl.innerHTML = `
      <div style="padding: 8px 10px; background: #dcfce7; border: 1px solid #86efac; border-radius: 6px; color: #166534; font-weight: 700;">
        ✓ ¡Deuda cancelada en su totalidad! Las ${pendingInstallments.length} cuotas pendientes quedarán en $0.00 (Pagadas).
      </div>
    `;
    return;
  }

  // Simulación cuota por cuota en orden cronológico
  let abonoSimulado = Math.round(amountValUSD * 100) / 100;

  redistListEl.innerHTML = pendingInstallments.map((inst) => {
    const dueDate = new Date(inst.dueDate + "T00:00:00");
    const currentDue = Math.round((inst.amountUSD || 0) * 100) / 100;

    if (abonoSimulado <= 0) {
      // Las cuotas futuras no se modifican en su monto original
      return `
        <div style="display: flex; justify-content: space-between; align-items: center; padding: 5px 8px; background: #ffffff; border-radius: 4px; border: 1px solid #e2e8f0;">
          <span><strong>Cuota ${inst.number}</strong> (${formatDateDisplay(dueDate)}):</span>
          <span style="color: var(--color-primary); font-size: 0.88rem;">$${currentDue.toFixed(2)} USD <small style="color: var(--color-text-muted);">(Intacta)</small></span>
        </div>
      `;
    }

    if (abonoSimulado >= currentDue) {
      // Alcanza para pagarla completa -> la marca como Pagada y el sobrante pasa a la siguiente cuota
      abonoSimulado = Math.round((abonoSimulado - currentDue) * 100) / 100;
      return `
        <div style="display: flex; justify-content: space-between; align-items: center; padding: 5px 8px; background: #f0fdf4; border-radius: 4px; border: 1px solid #86efac;">
          <span><strong>Cuota ${inst.number}</strong> (${formatDateDisplay(dueDate)}):</span>
          <strong style="color: #15803d; font-size: 0.92rem;">✓ Pagada completa</strong>
        </div>
      `;
    } else {
      // NO alcanza para pagarla completa -> reduce el monto de esa cuota por el valor abonado y queda como Parcialmente pagada
      const remainingForInst = Math.round((currentDue - abonoSimulado) * 100) / 100;
      const abonadoAEsta = abonoSimulado;
      abonoSimulado = 0;
      return `
        <div style="display: flex; justify-content: space-between; align-items: center; padding: 5px 8px; background: #fefce8; border-radius: 4px; border: 1px solid #fde047;">
          <span><strong>Cuota ${inst.number}</strong> (${formatDateDisplay(dueDate)}):</span>
          <span style="color: #ca8a04; font-size: 0.88rem; font-weight: 700;">
            Parcial: Resta $${remainingForInst.toFixed(2)} USD <small style="color: #854d0e;">(abona $${abonadoAEsta.toFixed(2)})</small>
          </span>
        </div>
      `;
    }
  }).join("");
}

// Guardar y aplicar el pago libre al crédito con registro de Tasa BCV de hoy
function handlePaymentFormSubmit(e) {
  e.preventDefault();

  const credits = getStoredCredits();
  const credit = credits.find((c) => String(c.id) === String(currentPaymentCreditId));
  const errorBanner = document.getElementById("payment-form-error");
  const amountInput = document.getElementById("payment-amount-input");
  const currencySelect = document.getElementById("payment-currency-select");
  const rateBcvTodayInput = document.getElementById("payment-rate-bcv-today");

  if (!credit) {
    if (errorBanner) {
      errorBanner.textContent = "Crédito no encontrado.";
      errorBanner.style.display = "block";
    }
    return;
  }

  const amountValUSD = parseFloat(amountInput.value);
  if (isNaN(amountValUSD) || amountValUSD <= 0) {
    if (errorBanner) {
      errorBanner.textContent = "Por favor ingresa un monto válido mayor a cero.";
      errorBanner.style.display = "block";
    }
    if (typeof addSystemLog === "function") {
      addSystemLog({
        level: "WARNING",
        action: "VALIDATION_ERROR",
        details: { form: "credit_payment", reason: "Monto inválido menor o igual a cero" },
        status: "failed",
        errorMessage: "Monto inválido para el abono"
      });
    }
    amountInput.focus();
    return;
  }

  const currency = currencySelect ? currencySelect.value : "USD";
  let rateBCVToday = null;
  let montoBsResultante = 0;

  if (currency === "BS") {
    rateBCVToday = parseFloat(rateBcvTodayInput ? rateBcvTodayInput.value : 0) || 0;
    if (rateBCVToday <= 0) {
      if (errorBanner) {
        errorBanner.textContent = "Por favor ingresa la Tasa BCV de hoy para realizar el cobro en Bolívares.";
        errorBanner.style.display = "block";
      }
      if (typeof addSystemLog === "function") {
        addSystemLog({
          level: "WARNING",
          action: "VALIDATION_ERROR",
          details: { form: "credit_payment", reason: "Tasa BCV de hoy requerida para abono en Bolívares" },
          status: "failed",
          errorMessage: "Tasa BCV requerida para abono en Bolívares"
        });
      }
      if (rateBcvTodayInput) rateBcvTodayInput.focus();
      return;
    }
    montoBsResultante = amountValUSD * rateBCVToday;
  }

  const newRemainingBalance = Math.max(0, Math.round((credit.remainingBalance - amountValUSD) * 100) / 100);

  const payDateInput = document.getElementById("payment-date");
  const payDateVal = payDateInput && payDateInput.value ? payDateInput.value : new Date().toISOString().split("T")[0];
  const refInput = document.getElementById("payment-reference");
  const referenceNumber = refInput ? refInput.value.trim() : "";

  // Aplicar el monto abonado cuota por cuota, en orden cronológico (de la más antigua a la más reciente)
  let abonoDisponible = Math.round(amountValUSD * 100) / 100;

  // Filtrar cuotas que aún tienen saldo por pagar (no están totalmente Pagadas) ordenadas cronológicamente
  const pendingInstallments = credit.installments
    .filter((inst) => inst.status !== "Pagada")
    .sort((a, b) => (a.number || 0) - (b.number || 0));

  for (const inst of pendingInstallments) {
    if (abonoDisponible <= 0) break;

    // Guardar monto original de referencia si no existe
    if (inst.originalAmountUSD === undefined) {
      inst.originalAmountUSD = inst.amountUSD;
    }

    const currentDue = Math.round((inst.amountUSD || 0) * 100) / 100;

    if (abonoDisponible >= currentDue) {
      // 2. Si el monto alcanza para pagarla completa -> la marca como Pagada y el sobrante pasa a la siguiente cuota
      abonoDisponible = Math.round((abonoDisponible - currentDue) * 100) / 100;
      inst.amountUSD = 0;
      inst.status = "Pagada";
      inst.paidDate = payDateVal;
    } else {
      // 3. Si el monto NO alcanza para pagarla completa -> reduce el monto de esa cuota por el valor abonado y queda como Parcialmente pagada
      inst.amountUSD = Math.round((currentDue - abonoDisponible) * 100) / 100;
      inst.status = "Parcialmente pagada";
      abonoDisponible = 0;
      // No toca las cuotas siguientes
      break;
    }
  }

  // Si no queda saldo en el crédito, todas quedan pagadas
  if (newRemainingBalance <= 0) {
    credit.installments.forEach((inst) => {
      inst.status = "Pagada";
      inst.amountUSD = 0;
    });
  }

  // Actualizar saldo del crédito siempre en USD
  credit.remainingBalance = newRemainingBalance;

  // Registrar pago por moneda separada
  if (currency === "BS") {
    credit.totalBsPaid = (credit.totalBsPaid || 0) + montoBsResultante;
  } else {
    credit.totalDivisasPaid = (credit.totalDivisasPaid || 0) + amountValUSD;
  }

  // Historial de pagos del crédito con monto USD, tasa BCV usada ese día y monto en Bs resultante
  const newPayId = "pay_" + Date.now();
  credit.payments = credit.payments || [];
  credit.payments.push({
    id: newPayId,
    date: payDateVal,
    type: "abono",
    description: "Abono a capital",
    amountUSD: amountValUSD,
    currency,
    rateBCVToday: currency === "BS" ? rateBCVToday : null,
    amountBs: currency === "BS" ? montoBsResultante : 0,
    referenceNumber,
    receiptUrl: currentPaymentReceiptBase64 || null,
    remainingBalanceAfter: newRemainingBalance
  });

  // Guardar en localStorage
  saveCreditsToStorage(credits);

  if (typeof addSystemLog === "function") {
    addSystemLog({
      level: "INFO",
      action: "CREATE_PAYMENT",
      details: {
        creditoId: credit.id,
        pagoId: newPayId,
        montoUSD: amountValUSD,
        moneda: currency,
        fecha: payDateVal,
        tipo: "abono",
        saldoRestanteUSD: newRemainingBalance
      },
      status: "success"
    });
  }

  closeCreditPaymentModal();
  renderCredits();
  renderPagosSection();
  renderDashboardSection();

  // Si el modal de detalle estaba abierto, refrescarlo con los nuevos saldos, cuotas e historial
  const detailModal = document.getElementById("credit-detail-modal");
  if (detailModal && !detailModal.classList.contains("hidden")) {
    openCreditDetailModal(credit.id);
  }

  // Si el modal de perfil de cliente estaba abierto, refrescarlo
  const clientProfileModal = document.getElementById("client-profile-modal");
  if (clientProfileModal && !clientProfileModal.classList.contains("hidden")) {
    openClientProfileModal(credit.clientId);
  }

  // Si modal historial de pagos estaba abierto, refrescarlo
  const historyModal = document.getElementById("credit-payments-history-modal");
  if (historyModal && !historyModal.classList.contains("hidden")) {
    openCreditPaymentsHistoryModal(credit.id);
  }

  // Generar y abrir recibo de pago automáticamente
  generateAndOpenPaymentReceipt(credit.id, newPayId);

  if (currency === "BS") {
    alert(`¡Pago en Bolívares registrado con éxito!\n• Monto abonado: $${amountValUSD.toFixed(2)} USD\n• Tasa BCV de hoy: ${rateBCVToday.toFixed(2)} Bs/$\n• Monto cobrado en Bs: Bs. ${formatBs(montoBsResultante)}\n• Saldo restante: $${newRemainingBalance.toFixed(2)} USD\nAbono aplicado cuota por cuota.`);
  } else {
    alert(`¡Pago en Divisas registrado con éxito!\n• Monto abonado: $${amountValUSD.toFixed(2)} USD\n• Saldo restante: $${newRemainingBalance.toFixed(2)} USD\nAbono aplicado cuota por cuota.`);
  }
}

// Utilidad para formatear fechas a DD/MM/YYYY
function formatDateDisplay(dateObj) {
  if (!dateObj || isNaN(dateObj.getTime())) return "-";
  const day = String(dateObj.getDate()).padStart(2, "0");
  const month = String(dateObj.getMonth() + 1).padStart(2, "0");
  const year = dateObj.getFullYear();
  return `${day}/${month}/${year}`;
}

// Utilidad para formatear Bolívares con separadores
function formatBs(amount) {
  if (isNaN(amount)) return "0,00";
  return amount.toLocaleString("es-VE", {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2
  });
}

