// Renderizar la vista principal del Módulo de Pagos
function renderPagosSection() {
  const tbody = document.getElementById("pagos-tbody");
  const emptyMsg = document.getElementById("empty-pagos-msg");
  if (!tbody || !emptyMsg) return;

  const credits = getStoredCredits();

  // Filtrar solo créditos activos (con saldo restante > 0 o que tengan cuotas pendientes de pago)
  const activeCredits = credits.filter((c) => {
    const hasPending = c.installments && c.installments.some((inst) => inst.status !== "Pagada");
    return (c.remainingBalance > 0 || hasPending);
  });

  // Ordenar por próxima cuota más cercana
  activeCredits.sort((a, b) => {
    const nextA = a.installments ? a.installments.find((i) => i.status !== "Pagada") : null;
    const nextB = b.installments ? b.installments.find((i) => i.status !== "Pagada") : null;
    const timeA = nextA ? new Date(nextA.dueDate + "T00:00:00").getTime() : Infinity;
    const timeB = nextB ? new Date(nextB.dueDate + "T00:00:00").getTime() : Infinity;
    return timeA - timeB;
  });

  // Filtrar según búsqueda
  const filteredCredits = activeCredits.filter((c) => {
    if (!currentPagosSearchQuery) return true;
    const name = (c.client && c.client.name ? c.client.name : "").toLowerCase();
    const dni = (c.client && c.client.dni ? c.client.dni : "").toLowerCase();
    return name.includes(currentPagosSearchQuery) || dni.includes(currentPagosSearchQuery);
  });

  if (filteredCredits.length === 0) {
    tbody.innerHTML = "";
    emptyMsg.classList.remove("hidden");
    updateSelectedPagosButton();
    return;
  }

  emptyMsg.classList.add("hidden");

  tbody.innerHTML = filteredCredits.map((c) => {
    const clientName = escapeHtml(c.client ? c.client.name : "Sin nombre");
    const clientDni = escapeHtml(c.client ? c.client.dni : "-");

    // Resumen de productos
    const productsSummary = c.items && c.items.length > 0
      ? c.items.map((it) => `${escapeHtml(it.name)} (${it.quantity})`).join(", ")
      : "Sin productos";

    // Conteo de cuotas pagadas
    const totalInstallments = c.installments ? c.installments.length : 0;
    const paidInstallmentsCount = c.installments ? c.installments.filter((i) => i.status === "Pagada").length : 0;
    const nextPending = c.installments ? c.installments.find((i) => i.status !== "Pagada") : null;

    // Estado del crédito
    const statusObj = getCreditStatus(c);

    const nextAmountUSD = nextPending ? `$${nextPending.amountUSD.toFixed(2)} USD` : "$0.00";
    const nextDueDateStr = nextPending ? formatDateDisplay(new Date(nextPending.dueDate + "T00:00:00")) : "-";

    return `
      <tr>
        <td style="width: 44px; text-align: center;">
          <input type="checkbox" class="pagos-row-checkbox pago-row-checkbox" data-id="${c.id}" style="width: 17px; height: 17px; cursor: pointer;">
        </td>
        <td>
          <div style="font-weight: 700; color: var(--color-primary);">${clientName}</div>
          <small style="color: var(--color-text-muted);">C.I: ${clientDni}</small>
        </td>
        <td>
          <div style="font-size: 0.88rem; max-width: 220px; white-space: normal; line-height: 1.3;">
            ${productsSummary}
          </div>
        </td>
        <td>
          <span style="font-weight: 700; background: #e0f2fe; color: #0369a1; padding: 2px 8px; border-radius: 4px; font-size: 0.82rem;">
            ${paidInstallmentsCount} / ${totalInstallments}
          </span>
        </td>
        <td>
          <strong style="color: #15803d; font-size: 0.95rem;">${nextAmountUSD}</strong>
        </td>
        <td>
          <span style="font-size: 0.88rem;">${nextDueDateStr}</span>
        </td>
        <td>
          <span class="status-badge ${statusObj.statusClass}">${statusObj.statusText}</span>
        </td>
        <td>
          <div style="display: flex; gap: 4px; flex-wrap: wrap;">
            <button type="button" class="btn-action-pay-installment btn-pagos-pay-inst" data-id="${c.id}" onclick="openPayInstallmentModal('${c.id}')" title="Pagar la cuota correspondiente">✓ Pagar cuota</button>
            <button type="button" class="btn-action-abonar btn-pagos-abonar" data-id="${c.id}" onclick="openCreditPaymentModal('${c.id}')" title="Abonar monto libre y redistribuir">💳 Abonar</button>
            <button type="button" class="btn-action-history btn-pagos-history" data-id="${c.id}" onclick="openCreditPaymentsHistoryModal('${c.id}')" title="Ver historial de pagos">📜 Historial</button>
            <button type="button" class="btn-action-delete-credit-pagos btn-action-delete" data-id="${c.id}" onclick="openDeleteCreditModal('${c.id}')" title="Eliminar crédito">🗑️</button>
          </div>
        </td>
      </tr>
    `;
  }).join("");

  // Delegación de eventos para checkboxes en el tbody de pagos
  if (tbody._pagoCheckboxHandler) {
    tbody.removeEventListener("change", tbody._pagoCheckboxHandler);
  }
  tbody._pagoCheckboxHandler = (e) => {
    if (e.target && (e.target.classList.contains("pago-row-checkbox") || e.target.classList.contains("pagos-row-checkbox"))) {
      updateSelectedPagosButton();
    }
  };
  tbody.addEventListener("change", tbody._pagoCheckboxHandler);

  // Checkbox maestro para pagos
  const checkAllPagos = document.getElementById("check-all-pagos");
  if (checkAllPagos) {
    if (checkAllPagos._masterHandler) {
      checkAllPagos.removeEventListener("change", checkAllPagos._masterHandler);
    }
    checkAllPagos._masterHandler = () => {
      const boxes = tbody.querySelectorAll(".pagos-row-checkbox, .pago-row-checkbox");
      boxes.forEach((cb) => {
        cb.checked = checkAllPagos.checked;
      });
      updateSelectedPagosButton();
    };
    checkAllPagos.addEventListener("change", checkAllPagos._masterHandler);
  }

  updateSelectedPagosButton();
}

function renderPagos() {
  renderPagosSection();
}
window.renderPagos = renderPagos;

// Renderizar filas de la tabla de historial de pagos (usado por modal de detalle y modal de historial)
function renderPaymentHistoryRows(credit, payments) {
  if (!payments || payments.length === 0) return "";

  // Mostrar ordenado cronológicamente (más recientes primero)
  const sorted = [...payments].sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

  return sorted.map((p) => {
    const dateObj = new Date(p.date + (String(p.date).includes("T") ? "" : "T00:00:00"));
    const dateStr = formatDateDisplay(dateObj);
    const timeStr = (!isNaN(dateObj.getTime()) && String(p.date).includes("T"))
      ? dateObj.toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" })
      : "";

    const typeBadge = p.type === "cuota"
      ? `<span class="badge-cuota">Cuota ${p.installmentNumber ? '#' + p.installmentNumber : ''}</span>`
      : `<span class="badge-abono">Abono</span>`;

    const currBadge = p.currency === "BS"
      ? '<span class="badge-bolivares">Bolívares (Bs)</span>'
      : '<span class="badge-divisas">Divisas ($)</span>';

    const rateStr = p.rateBCVToday ? `Bs. ${parseFloat(p.rateBCVToday).toFixed(2)}` : "—";
    const bsResultStr = p.amountBs > 0 ? `<strong>Bs. ${formatBs(p.amountBs)}</strong>` : "—";
    const refStr = p.referenceNumber ? `<code>#${escapeHtml(p.referenceNumber)}</code>` : "—";

    const receiptThumb = p.receiptUrl
      ? `<img src="${p.receiptUrl}" class="receipt-thumbnail" alt="Comprobante" title="Clic para ampliar" data-receipt="${p.receiptUrl}">`
      : '<span style="color: var(--color-text-muted); font-size: 0.8rem;">—</span>';

    return `
      <tr>
        <td style="width: 44px; text-align: center;">
          <input type="checkbox" class="payment-row-checkbox" data-credit-id="${credit.id}" data-payment-id="${p.id}" style="width: 17px; height: 17px; cursor: pointer;">
        </td>
        <td>${dateStr} <small style="color: var(--color-text-muted); display: block;">${timeStr}</small></td>
        <td>${typeBadge}</td>
        <td><strong>$${parseFloat(p.amountUSD).toFixed(2)} USD</strong></td>
        <td>${currBadge}</td>
        <td>${rateStr}</td>
        <td>${bsResultStr}</td>
        <td>${refStr}</td>
        <td style="text-align: center;">${receiptThumb}</td>
        <td>
          <div style="display: flex; gap: 4px; flex-wrap: wrap;">
            <button type="button" class="btn-action-receipt" data-credit-id="${credit.id}" data-payment-id="${p.id}" title="Generar recibo de pago">🧾 Recibo</button>
            <button type="button" class="btn-action-edit-pay" data-credit-id="${credit.id}" data-payment-id="${p.id}" title="Editar pago">✏️ Editar</button>
            <button type="button" class="btn-action-delete-pay" data-credit-id="${credit.id}" data-payment-id="${p.id}" title="Eliminar pago">🗑️ Eliminar</button>
          </div>
        </td>
      </tr>
    `;
  }).join("");
}

