// Recalcular integralmente las finanzas, saldos y cuotas de un crédito tras editar o eliminar pagos
function recalculateCreditFinances(credit) {
  if (!credit) return;
  credit.payments = credit.payments || [];

  // Ordenar pagos por fecha cronológicamente
  credit.payments.sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());

  // 1. Recalcular pagos por moneda
  let totalDivisas = credit.downpaymentPaidUSD || 0;
  let totalBs = credit.downpaymentPaidBs || 0;
  let totalPaymentsUSD = 0;

  credit.payments.forEach((p) => {
    const amtUSD = parseFloat(p.amountUSD) || 0;
    totalPaymentsUSD += amtUSD;
    if (p.currency === "BS") {
      totalBs += parseFloat(p.amountBs) || 0;
    } else {
      totalDivisas += amtUSD;
    }
  });

  credit.totalDivisasPaid = totalDivisas;
  credit.totalBsPaid = totalBs;

  // 2. Saldo restante total
  const initialDebt = Math.max(0, credit.totalSaleUSD - (credit.downpaymentAmount || 0));
  let runningBalance = initialDebt;

  // Actualizar remainingBalanceAfter en cada pago
  credit.payments.forEach((p) => {
    runningBalance = Math.max(0, Math.round((runningBalance - (parseFloat(p.amountUSD) || 0)) * 100) / 100);
    p.remainingBalanceAfter = runningBalance;
  });

  credit.remainingBalance = runningBalance;

  // 3. Restaurar y reconstruir cuotas aplicando pagos en orden cronológico
  const defaultInstAmt = credit.installmentAmount || (initialDebt / (credit.installmentsCount || credit.installments.length || 1));
  credit.installments.forEach((inst) => {
    const orig = inst.originalAmountUSD !== undefined ? inst.originalAmountUSD : defaultInstAmt;
    inst.originalAmountUSD = orig;
    inst.amountUSD = orig;
    inst.status = "Pendiente";
  });

  // Aplicar cada pago en orden cronológico
  credit.payments.forEach((p) => {
    if (p.type === "cuota" && p.installmentNumber) {
      const targetInst = credit.installments.find((i) => i.number === p.installmentNumber);
      if (targetInst) {
        targetInst.status = "Pagada";
        targetInst.amountUSD = 0;
      }
    } else {
      // Abono: aplicar cuota por cuota cronológicamente
      let abono = parseFloat(p.amountUSD) || 0;
      const pending = credit.installments
        .filter((i) => i.status !== "Pagada")
        .sort((a, b) => (a.number || 0) - (b.number || 0));

      for (const inst of pending) {
        if (abono <= 0) break;
        const curDue = Math.round(inst.amountUSD * 100) / 100;
        if (abono >= curDue) {
          abono = Math.round((abono - curDue) * 100) / 100;
          inst.amountUSD = 0;
          inst.status = "Pagada";
        } else {
          inst.amountUSD = Math.round((curDue - abono) * 100) / 100;
          inst.status = "Parcialmente pagada";
          abono = 0;
          break;
        }
      }
    }
  });

  // Si el crédito quedó en $0, todas las cuotas pasan a Pagadas
  if (credit.remainingBalance <= 0) {
    credit.installments.forEach((inst) => {
      inst.status = "Pagada";
      inst.amountUSD = 0;
    });
  }
}

// Abrir modal para Editar Pago existente
function openEditPaymentModal(creditId, paymentId) {
  const credits = getStoredCredits();
  const credit = credits.find((c) => String(c.id) === String(creditId));
  if (!credit) return;

  const payment = (credit.payments || []).find((p) => String(p.id) === String(paymentId));
  if (!payment) return;

  currentEditPaymentCreditId = creditId;
  currentEditPaymentId = paymentId;
  currentEditPayReceiptBase64 = payment.receiptUrl || null;

  const modal = document.getElementById("modal-edit-payment");
  const form = document.getElementById("edit-payment-form");
  const errorBanner = document.getElementById("edit-payment-error");

  if (form) form.reset();
  if (errorBanner) {
    errorBanner.style.display = "none";
    errorBanner.textContent = "";
  }

  document.getElementById("edit-pay-credit-id").value = creditId;
  document.getElementById("edit-pay-payment-id").value = paymentId;

  const dateVal = payment.date ? String(payment.date).split("T")[0] : new Date().toISOString().split("T")[0];
  document.getElementById("edit-pay-date").value = dateVal;
  document.getElementById("edit-pay-currency").value = payment.currency || "USD";
  document.getElementById("edit-pay-amount-usd").value = payment.amountUSD || "";
  document.getElementById("edit-pay-rate-bcv").value = payment.rateBCVToday || "";
  const editPayBsInput = document.getElementById("edit-pay-amount-bs");
  if (editPayBsInput) editPayBsInput.value = payment.amountBs ? parseFloat(payment.amountBs).toFixed(2) : "";
  document.getElementById("edit-pay-reference").value = payment.referenceNumber || "";

  // Mostrar u ocultar comprobante
  const img = document.getElementById("edit-pay-receipt-preview-img");
  const placeholder = document.getElementById("edit-pay-receipt-placeholder");
  const btnRemove = document.getElementById("btn-remove-edit-pay-receipt");
  const fileInput = document.getElementById("edit-pay-receipt-file");
  if (fileInput) fileInput.value = "";

  if (currentEditPayReceiptBase64) {
    if (img) { img.src = currentEditPayReceiptBase64; img.classList.remove("hidden"); }
    if (placeholder) placeholder.classList.add("hidden");
    if (btnRemove) btnRemove.classList.remove("hidden");
  } else {
    if (img) { img.src = ""; img.classList.add("hidden"); }
    if (placeholder) placeholder.classList.remove("hidden");
    if (btnRemove) btnRemove.classList.add("hidden");
  }

  updateEditPaymentCalculations();

  if (modal) modal.classList.remove("hidden");
}

function closeEditPaymentModal() {
  const modal = document.getElementById("modal-edit-payment");
  const form = document.getElementById("edit-payment-form");
  if (modal) modal.classList.add("hidden");
  if (form) form.reset();
  currentEditPayReceiptBase64 = null;
  const fileInput = document.getElementById("edit-pay-receipt-file");
  if (fileInput) fileInput.value = "";
  const editPayBsInput = document.getElementById("edit-pay-amount-bs");
  if (editPayBsInput) editPayBsInput.value = "";
  currentEditPaymentCreditId = null;
  currentEditPaymentId = null;
}

function updateEditPaymentCalculations() {
  const currencySelect = document.getElementById("edit-pay-currency");
  const rateBox = document.getElementById("edit-pay-rate-bcv-box");
  const rateInput = document.getElementById("edit-pay-rate-bcv");
  const amountInput = document.getElementById("edit-pay-amount-usd");
  const bsBox = document.getElementById("edit-pay-amount-bs-box");
  const bsInput = document.getElementById("edit-pay-amount-bs");
  const calcBsEl = document.getElementById("edit-pay-calc-bs");

  const currency = currencySelect ? currencySelect.value : "USD";
  const amountUSD = parseFloat(amountInput ? amountInput.value : 0) || 0;
  const rateBCV = parseFloat(rateInput ? rateInput.value : 0) || 0;

  if (currency === "BS") {
    if (rateBox) rateBox.classList.remove("hidden");
    if (bsBox) bsBox.classList.remove("hidden");
    if (calcBsEl) {
      if (rateBCV > 0 && amountUSD > 0) {
        const bsAmt = amountUSD * rateBCV;
        calcBsEl.textContent = `Equivalente en Bolívares: Bs. ${formatBs(bsAmt)} (${rateBCV.toFixed(2)} Bs/$)`;
      } else {
        calcBsEl.textContent = "Ingresa la tasa BCV oficial para calcular en Bolívares.";
      }
    }
  } else {
    if (rateBox) rateBox.classList.add("hidden");
    if (bsBox) bsBox.classList.add("hidden");
    if (calcBsEl) calcBsEl.textContent = "";
  }
}

function handleEditPaymentSubmit(e) {
  e.preventDefault();

  const credits = getStoredCredits();
  const credit = credits.find((c) => String(c.id) === String(currentEditPaymentCreditId));
  const errorBanner = document.getElementById("edit-payment-error");

  if (!credit) {
    if (errorBanner) {
      errorBanner.textContent = "Crédito no encontrado.";
      errorBanner.style.display = "block";
    }
    return;
  }

  const payment = (credit.payments || []).find((p) => String(p.id) === String(currentEditPaymentId));
  if (!payment) {
    if (errorBanner) {
      errorBanner.textContent = "Pago no encontrado.";
      errorBanner.style.display = "block";
    }
    return;
  }

  const dateVal = document.getElementById("edit-pay-date").value || new Date().toISOString().split("T")[0];
  const currencyVal = document.getElementById("edit-pay-currency").value || "USD";
  const amountUSD = parseFloat(document.getElementById("edit-pay-amount-usd").value);
  const rateBCV = parseFloat(document.getElementById("edit-pay-rate-bcv").value) || 0;
  const refVal = document.getElementById("edit-pay-reference").value.trim();

  if (isNaN(amountUSD) || amountUSD <= 0) {
    if (errorBanner) {
      errorBanner.textContent = "Por favor ingresa un monto válido mayor a cero.";
      errorBanner.style.display = "block";
    }
    document.getElementById("edit-pay-amount-usd").focus();
    return;
  }

  if (currencyVal === "BS" && rateBCV <= 0) {
    if (errorBanner) {
      errorBanner.textContent = "Por favor ingresa la tasa BCV utilizada para el cobro en Bolívares.";
      errorBanner.style.display = "block";
    }
    document.getElementById("edit-pay-rate-bcv").focus();
    return;
  }

  // Actualizar datos del pago
  payment.date = dateVal;
  payment.currency = currencyVal;
  payment.amountUSD = amountUSD;
  payment.rateBCVToday = currencyVal === "BS" ? rateBCV : null;
  payment.amountBs = currencyVal === "BS" ? (amountUSD * rateBCV) : 0;
  payment.referenceNumber = refVal;
  payment.receiptUrl = currentEditPayReceiptBase64 || null;

  // Recalcular integralmente el crédito
  recalculateCreditFinances(credit);

  // Guardar en localStorage
  saveCreditsToStorage(credits);

  if (typeof addSystemLog === "function") {
    addSystemLog({
      level: "INFO",
      action: "UPDATE_PAYMENT",
      details: {
        creditoId: credit.id,
        pagoId: payment.id,
        montoUSD: amountUSD,
        moneda: currencyVal,
        fecha: dateVal,
        tasaBCV: currencyVal === "BS" ? rateBCV : null
      },
      status: "success"
    });
  }

  closeEditPaymentModal();
  renderCredits();
  renderPagosSection();

  // Si modal historial de pagos estaba abierto, refrescarlo
  const historyModal = document.getElementById("credit-payments-history-modal");
  if (historyModal && !historyModal.classList.contains("hidden")) {
    openCreditPaymentsHistoryModal(credit.id);
  }

  // Si modal detalle estaba abierto, refrescarlo
  const detailModal = document.getElementById("credit-detail-modal");
  if (detailModal && !detailModal.classList.contains("hidden")) {
    openCreditDetailModal(credit.id);
  }

  // Si modal perfil cliente estaba abierto, refrescarlo
  const clientProfileModal = document.getElementById("client-profile-modal");
  if (clientProfileModal && !clientProfileModal.classList.contains("hidden")) {
    openClientProfileModal(credit.clientId);
  }

  alert("¡Registro de pago actualizado exitosamente!");
}

// Abrir modal de confirmación para eliminar pago
function openDeletePaymentModal(creditId, paymentIdOrIds) {
  currentDeletePaymentCreditId = creditId;
  currentDeletePaymentIds = Array.isArray(paymentIdOrIds) ? paymentIdOrIds : [paymentIdOrIds];

  const modal = document.getElementById("modal-confirm-delete-payment");
  const input = document.getElementById("input-confirm-delete-payment-word");
  const btnConfirm = document.getElementById("btn-confirm-delete-payment");
  const msg = document.getElementById("delete-payment-modal-msg");

  if (input) input.value = "";
  if (btnConfirm) btnConfirm.disabled = true;

  if (msg) {
    if (currentDeletePaymentIds.length > 1) {
      msg.textContent = `¿Estás seguro de que deseas eliminar los ${currentDeletePaymentIds.length} registros de pago seleccionados? Esta acción revertirá los montos en el saldo y cronograma de cuotas del crédito.`;
    } else {
      msg.textContent = "¿Estás seguro de que deseas eliminar este registro de pago? Esta acción revertirá el monto en el saldo y cronograma de cuotas del crédito.";
    }
  }

  if (modal) modal.classList.remove("hidden");
  if (input) input.focus();
}

function closeDeletePaymentModal() {
  const modal = document.getElementById("modal-confirm-delete-payment");
  if (modal) modal.classList.add("hidden");
  const input = document.getElementById("input-confirm-delete-payment-word");
  if (input) input.value = "";
  currentDeletePaymentCreditId = null;
  currentDeletePaymentIds = [];
}

// Ejecutar eliminación del pago
function executeDeletePayment() {
  const input = document.getElementById("input-confirm-delete-payment-word");
  if (!input || input.value.trim().toLowerCase() !== "borrar") return;
  if (!currentDeletePaymentCreditId || !currentDeletePaymentIds || currentDeletePaymentIds.length === 0) return;

  const credits = getStoredCredits();
  const credit = credits.find((c) => String(c.id) === String(currentDeletePaymentCreditId));
  if (!credit) return;

  const targetIds = currentDeletePaymentIds.map(String);

  // Eliminar el/los pagos
  credit.payments = (credit.payments || []).filter((p) => !targetIds.includes(String(p.id)));

  // Recalcular integralmente las finanzas y cuotas del crédito
  recalculateCreditFinances(credit);

  // Guardar en localStorage
  saveCreditsToStorage(credits);

  if (typeof addSystemLog === "function") {
    addSystemLog({
      level: "INFO",
      action: "DELETE_PAYMENT",
      details: {
        creditoId: credit.id,
        targetIds,
        cantidad: targetIds.length
      },
      status: "success"
    });
  }

  // triggerAutoCloudBackup("creditos") explícito al terminar
  if (typeof triggerAutoCloudBackup === "function") {
    triggerAutoCloudBackup("creditos");
  }

  closeDeletePaymentModal();
  renderCredits();
  renderPagosSection();

  // Refrescar modales abiertos
  const historyModal = document.getElementById("credit-payments-history-modal");
  if (historyModal && !historyModal.classList.contains("hidden")) {
    openCreditPaymentsHistoryModal(credit.id);
  }

  const detailModal = document.getElementById("credit-detail-modal");
  if (detailModal && !detailModal.classList.contains("hidden")) {
    openCreditDetailModal(credit.id);
  }

  const clientProfileModal = document.getElementById("client-profile-modal");
  if (clientProfileModal && !clientProfileModal.classList.contains("hidden")) {
    openClientProfileModal(credit.clientId);
  }

  if (typeof showCloudSyncToast === "function") {
    showCloudSyncToast("Pago eliminado y saldo recalculado correctamente", "success");
  }
}

