// Compartir resumen del documento vía WhatsApp
function shareDocViaWhatsApp(doc) {
  if (!doc) return;

  const clientPhone = formatPhoneForWhatsApp(doc.client ? doc.client.phone : "");
  const dateObj = new Date(doc.date || Date.now());
  const dateStr = formatDateDisplay(dateObj);
  const timeStr = (!isNaN(dateObj.getTime()) && String(doc.date).includes("T"))
    ? " " + dateObj.toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" })
    : "";

  let message = "";

  if (doc.type === "factura_credito") {
    const items = (doc.data && Array.isArray(doc.data.items)) ? doc.data.items : [];
    const itemsList = items.map((it) => {
      const qty = parseInt(it.cantidad !== undefined ? it.cantidad : (it.quantity !== undefined ? it.quantity : it.qty), 10) || 1;
      const price = parseFloat(it.precioUnitario !== undefined ? it.precioUnitario : (it.price !== undefined ? it.price : it.priceUSD)) || 0;
      const sub = parseFloat(it.totalLinea !== undefined ? it.totalLinea : it.subtotal) || (price * qty);
      const name = it.nombre || it.name || "Producto";
      return `• ${name} (x${qty}) - $${sub.toFixed(2)} USD ($${price.toFixed(2)} c/u)`;
    }).join("\n");
    const shippingLine = doc.data.hasShipping && doc.data.shippingAmount > 0 ? `\n🚚 *Flete:* $${parseFloat(doc.data.shippingAmount).toFixed(2)} USD` : "";
    const bsTotalLine = doc.totalAmountBs ? `\n🇻🇪 *Total Bs:* Bs. ${formatBs(doc.totalAmountBs)}` + (doc.rateBCV ? ` (Tasa: ${parseFloat(doc.rateBCV).toFixed(2)} Bs/$)` : "") : "";
    const downpaymentStr = doc.data.downpaymentAmount > 0 ? `$${parseFloat(doc.data.downpaymentAmount).toFixed(2)} USD` : "$0.00";

    const installments = doc.data.installments || [];
    const installmentsList = installments.map((inst) => {
      const dStr = inst.dueDate ? formatDateDisplay(new Date(inst.dueDate + "T00:00:00")) : "-";
      const bsVal = inst.amountBs ? ` (Bs. ${formatBs(inst.amountBs)})` : (doc.rateBCV ? ` (Bs. ${formatBs(inst.amountUSD * doc.rateBCV)})` : "");
      return `- Cuota ${inst.number}: ${dStr} -> $${parseFloat(inst.amountUSD).toFixed(2)} USD${bsVal} [${inst.status || "Pendiente"}]`;
    }).join("\n");

    message = `*HOGARFLEX NOELUIS* 📄\n*Factura de Crédito:* ${doc.docNumber}\n📅 *Fecha:* ${dateStr}\n\n👤 *Cliente:* ${doc.client.name} (C.I. ${doc.client.dni})\n📞 *Teléfono:* ${doc.client.phone || '-'}\n📍 *Dirección:* ${doc.client.address || '-'}\n\n🛍️ *Detalle de Compra:*\n${itemsList}${shippingLine}\n\n💰 *Total de Compra:* $${parseFloat(doc.totalAmountUSD).toFixed(2)} USD${bsTotalLine}\n💵 *Inicial Pagada:* ${downpaymentStr}\n📌 *Saldo Pendiente:* $${parseFloat(doc.data.remainingBalance).toFixed(2)} USD\n\n🗓️ *Plan de Cuotas:*\n${installmentsList}\n\n¡Muchas gracias por su preferencia! ✨\n*HOGARFLEX NOELUIS*`;
  } else {
    const conceptStr = doc.data.paymentType === "cuota"
      ? `Cuota #${doc.data.installmentNumber || ''}`
      : "Abono libre a capital";

    const bsPart = doc.totalAmountBs > 0
      ? `\n🇻🇪 *Monto en Bs:* Bs. ${formatBs(doc.totalAmountBs)}` + (doc.rateBCV ? ` (Tasa BCV: ${parseFloat(doc.rateBCV).toFixed(2)} Bs/$)` : "")
      : "";

    const refPart = doc.data.referenceNumber ? `\n📲 *Nº de Referencia:* #${doc.data.referenceNumber}` : "";

    message = `*HOGARFLEX NOELUIS* 🧾\n*Recibo Oficial de Pago:* ${doc.docNumber}\n📅 *Fecha de Pago:* ${dateStr}${timeStr}\n\n👤 *Cliente:* ${doc.client.name} (C.I. ${doc.client.dni})\n📞 *Teléfono:* ${doc.client.phone || '-'}\n\n📝 *Concepto:* ${conceptStr}\n💵 *Monto Pagado:* $${parseFloat(doc.totalAmountUSD).toFixed(2)} USD${bsPart}${refPart}\n💳 *Saldo Restante:* $${parseFloat(doc.data.remainingBalanceAfter).toFixed(2)} USD\n⏳ *Cuotas Pendientes:* ${doc.data.pendingInstallmentsCount} cuotas\n\n¡Muchas gracias por su puntualidad! ✨\n*HOGARFLEX NOELUIS*`;
  }

  const url = clientPhone
    ? `https://wa.me/${clientPhone}?text=${encodeURIComponent(message)}`
    : `https://wa.me/?text=${encodeURIComponent(message)}`;

  window.open(url, "_blank");
}

// Descargar documento PDF usando jsPDF
function printInvoiceDoc() {
  const cur = currentPreviewDoc;
  if (!cur) {
    alert("No hay ningún comprobante seleccionado.");
    return;
  }

  if (!window.jspdf || !window.jspdf.jsPDF) {
    alert('Error: la librería PDF no está disponible. Recarga la página e intenta de nuevo.');
    return;
  }

  const { jsPDF } = window.jspdf;
  const doc = new jsPDF({ unit: 'mm', format: 'letter' });
  const pageW = 215.9;
  const pageH = 279.4;
  const margin = 15;
  let y = 0;

  const invoiceDateStr = cur.date ? formatDateDisplay(new Date(cur.date)) : new Date().toLocaleDateString('es-VE');

  const invoice = {
    invoiceNumber: cur.docNumber || 'FAC-0001',
    date: invoiceDateStr,
    clientName: (cur.client && cur.client.name) ? cur.client.name : '',
    clientCI: (cur.client && cur.client.dni) ? cur.client.dni : '',
    clientPhone: (cur.client && cur.client.phone) ? cur.client.phone : '',
    clientAddress: (cur.client && cur.client.address) ? cur.client.address : '',
    items: cur.type === "recibo_pago"
      ? [{
          name: cur.data?.description || (cur.data?.paymentType === "cuota" ? `Pago Cuota #${cur.data?.installmentNumber || ''}` : "Abono libre a capital"),
          nombre: cur.data?.description || (cur.data?.paymentType === "cuota" ? `Pago Cuota #${cur.data?.installmentNumber || ''}` : "Abono libre a capital"),
          qty: 1,
          cantidad: 1,
          price: parseFloat(cur.totalAmountUSD) || 0,
          precioUnitario: parseFloat(cur.totalAmountUSD) || 0,
          subtotal: parseFloat(cur.totalAmountUSD) || 0,
          totalLinea: parseFloat(cur.totalAmountUSD) || 0
        }]
      : (cur.data?.items || []).map((it) => {
          const qty = parseInt(it.cantidad !== undefined ? it.cantidad : (it.quantity !== undefined ? it.quantity : it.qty), 10) || 1;
          let price = parseFloat(
            it.precioUnitario !== undefined ? it.precioUnitario :
            (it.price !== undefined ? it.price :
            (it.priceUSD !== undefined ? it.priceUSD :
            it.unitPrice))
          ) || 0;
          let lineTotal = parseFloat(it.totalLinea !== undefined ? it.totalLinea : it.subtotal) || parseFloat((qty * price).toFixed(2));
          if (price <= 0 && lineTotal > 0 && qty > 0) {
            price = parseFloat((lineTotal / qty).toFixed(2));
          } else if (price <= 0 && cur.totalAmountUSD && cur.data?.items?.length > 0) {
            price = parseFloat((parseFloat(cur.totalAmountUSD) / cur.data.items.length / qty).toFixed(2));
            lineTotal = parseFloat((qty * price).toFixed(2));
          }
          const itemName = it.nombre || it.name || "Producto";
          return {
            name: itemName,
            nombre: itemName,
            qty: qty,
            cantidad: qty,
            price: price,
            precioUnitario: price,
            totalLinea: lineTotal,
            subtotal: lineTotal
          };
        }),
    shipping: (cur.data?.hasShipping && cur.data?.shippingAmount > 0) ? parseFloat(cur.data.shippingAmount) : 0,
    totalUSD: parseFloat(cur.totalAmountUSD) || 0,
    bcvRate: parseFloat(cur.rateBCV) || 0,
    downPayment: parseFloat(cur.data?.downpaymentPaidUSD !== undefined && cur.data?.downpaymentPaidUSD > 0 ? cur.data.downpaymentPaidUSD : (cur.data?.downpaymentAmount || 0)) || 0,
    balance: parseFloat(cur.data?.remainingBalance !== undefined ? cur.data.remainingBalance : cur.data?.remainingBalanceAfter) || 0,
    installments: (cur.data?.installments || []).map((inst, idx) => ({
      number: inst.number !== undefined ? inst.number : (idx + 1),
      dueDate: inst.dueDate ? formatDateDisplay(new Date(inst.dueDate + "T00:00:00")) : '',
      amountUSD: parseFloat(inst.amountUSD) || 0,
      status: inst.status || 'Pendiente'
    }))
  };

  // ENCABEZADO — rectángulo navy
  doc.setFillColor(26, 58, 107); // #1a3a6b
  doc.rect(0, 0, pageW, 40, 'F');

  // LOGO — si existe como base64 o elemento imagen
  const headerLogoEl = document.querySelector('.header-logo') || document.querySelector('.login-logo');
  if (typeof LOGO_BASE64 !== 'undefined' && LOGO_BASE64) {
    try {
      const imgFormat = LOGO_BASE64.includes('image/png') ? 'PNG' : 'JPEG';
      doc.addImage(LOGO_BASE64, imgFormat, 10, 5, 25, 25);
    } catch (err) {
      console.warn("No se pudo cargar el logo en el PDF:", err);
    }
  } else if (headerLogoEl && headerLogoEl.complete && headerLogoEl.naturalWidth > 0) {
    try {
      doc.addImage(headerLogoEl, 'JPEG', 10, 5, 25, 25);
    } catch (err) {
      console.warn("No se pudo cargar headerLogoEl en el PDF:", err);
    }
  }

  // Texto del encabezado en blanco
  doc.setTextColor(255, 255, 255);
  doc.setFontSize(18);
  doc.setFont('helvetica', 'bold');
  doc.text('HOGARFLEX NOELUIS', pageW / 2, 14, { align: 'center' });
  doc.setFontSize(11);
  doc.setFont('helvetica', 'normal');
  const docSubtitle = cur.type === 'recibo_pago' ? 'RECIBO OFICIAL DE PAGO' : 'NOTA DE ENTREGA / FACTURA DE CRÉDITO';
  doc.text(docSubtitle, pageW / 2, 22, { align: 'center' });
  doc.setFontSize(9);
  doc.text('0424.215.58.05    |    0412.048.11.57', pageW / 2, 29, { align: 'center' });

  // Número de factura y fecha en blanco (esquina derecha)
  doc.text('N°: ' + (invoice.invoiceNumber || 'FAC-0001'), pageW - margin, 16, { align: 'right' });
  doc.text('Fecha: ' + (invoice.date || new Date().toLocaleDateString('es-VE')), pageW - margin, 22, { align: 'right' });

  // Línea dorada bajo encabezado
  doc.setDrawColor(245, 196, 0); // #f5c400
  doc.setLineWidth(1.5);
  doc.line(0, 40, pageW, 40);

  y = 50;

  // DATOS DEL CLIENTE
  doc.setTextColor(26, 58, 107);
  doc.setFontSize(10);
  doc.setFont('helvetica', 'bold');
  doc.text('DATOS DEL CLIENTE', margin, y);
  y += 5;
  doc.setDrawColor(200, 200, 200);
  doc.setLineWidth(0.3);
  doc.line(margin, y, pageW - margin, y);
  y += 6;
  doc.setFont('helvetica', 'normal');
  doc.setTextColor(0, 0, 0);
  doc.text('Cliente: ' + (invoice.clientName || ''), margin, y);
  y += 6;
  doc.text('C.I.: ' + (invoice.clientCI || '') + '    Teléfono: ' + (invoice.clientPhone || ''), margin, y);
  y += 6;
  doc.text('Dirección: ' + (invoice.clientAddress || ''), margin, y);
  y += 10;

  // TABLA DE PRODUCTOS
  doc.setFillColor(26, 58, 107);
  doc.rect(margin, y, pageW - margin * 2, 8, 'F');
  doc.setTextColor(255, 255, 255);
  doc.setFont('helvetica', 'bold');
  doc.setFontSize(9);
  doc.text('CANT.', margin + 2, y + 5.5);
  doc.text('DESCRIPCIÓN', margin + 20, y + 5.5);
  doc.text('P. UNIT. USD', margin + 110, y + 5.5);
  doc.text('TOTAL USD', margin + 145, y + 5.5);
  y += 8;
  doc.setTextColor(0, 0, 0);
  doc.setFont('helvetica', 'normal');

  // Iterar productos del invoice leyendo directamente del objeto factura
  (invoice.items || []).forEach((item, i) => {
    if (i % 2 === 0) { doc.setFillColor(245, 245, 245); doc.rect(margin, y, pageW - margin * 2, 7, 'F'); }
    const iQty = item.cantidad !== undefined ? item.cantidad : (item.qty || 1);
    const iPrice = item.precioUnitario !== undefined ? item.precioUnitario : (item.price || 0);
    const iTotal = item.totalLinea !== undefined ? item.totalLinea : ((item.subtotal !== undefined) ? item.subtotal : (iQty * iPrice));
    const iName = item.nombre || item.name || '';

    doc.text(String(iQty), margin + 2, y + 5);
    doc.text(String(iName), margin + 20, y + 5);
    doc.text('$' + iPrice.toFixed(2), margin + 110, y + 5);
    doc.text('$' + iTotal.toFixed(2), margin + 145, y + 5);
    y += 7;
  });

  // Flete si aplica
  if (invoice.shipping && invoice.shipping > 0) {
    doc.text('1', margin + 2, y + 5);
    doc.text('Flete / Envío', margin + 20, y + 5);
    doc.text('$' + invoice.shipping.toFixed(2), margin + 110, y + 5);
    doc.text('$' + invoice.shipping.toFixed(2), margin + 145, y + 5);
    y += 7;
  }
  y += 5;

  // TOTALES
  doc.setDrawColor(245, 196, 0);
  doc.setLineWidth(0.8);
  doc.line(margin, y, pageW - margin, y);
  y += 6;
  doc.setFont('helvetica', 'bold');
  doc.text('TOTAL: $' + (invoice.totalUSD || 0).toFixed(2) + ' USD', pageW - margin, y, { align: 'right' });
  y += 6;
  if (invoice.bcvRate && invoice.bcvRate > 0) {
    doc.setFont('helvetica', 'normal');
    doc.text('Tasa BCV: ' + invoice.bcvRate + ' Bs/$', pageW - margin, y, { align: 'right' });
    y += 6;
    doc.text('Equivalente: Bs. ' + ((invoice.totalUSD || 0) * invoice.bcvRate).toLocaleString('es-VE', {minimumFractionDigits: 2}), pageW - margin, y, { align: 'right' });
    y += 6;
  }
  doc.setFont('helvetica', 'bold');
  doc.setTextColor(26, 58, 107);
  doc.text('Cuota Inicial Pagada: $' + (invoice.downPayment || 0).toFixed(2) + ' USD', margin, y);
  y += 6;
  doc.setTextColor(180, 0, 0);
  doc.text('Saldo Pendiente: $' + (invoice.balance || 0).toFixed(2) + ' USD', margin, y);
  y += 10;

  // PLAN DE CUOTAS
  if (invoice.installments && invoice.installments.length > 0) {
    if (y + 45 > pageH - 30) {
      doc.addPage();
      y = 20;
    }

    doc.setTextColor(26, 58, 107);
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(10);
    doc.text('PLAN DE CUOTAS', margin, y);
    y += 5;

    // Resumen de cuotas encima de la tabla
    const totalInst = invoice.installments.length;
    const paidInst = invoice.installments.filter((i) => i.status === 'Pagada').length;
    const pendingInst = invoice.installments.filter((i) => i.status !== 'Pagada').length;
    const downPaymentFormatted = (invoice.downPayment || 0).toFixed(2);

    doc.setFillColor(248, 250, 252);
    doc.setDrawColor(203, 213, 225);
    doc.setLineWidth(0.3);
    doc.roundedRect(margin, y, pageW - margin * 2, 8, 1.5, 1.5, 'FD');

    const statColW = (pageW - margin * 2) / 4;
    doc.setFontSize(7.5);

    // Cuota inicial pagada
    doc.setFont('helvetica', 'normal');
    doc.setTextColor(71, 85, 105);
    doc.text('Inicial pagada:', margin + 3, y + 5.2);
    doc.setFont('helvetica', 'bold');
    doc.setTextColor(21, 128, 61);
    doc.text('$' + downPaymentFormatted + ' USD', margin + 22, y + 5.2);

    // Total de cuotas
    doc.setFont('helvetica', 'normal');
    doc.setTextColor(71, 85, 105);
    doc.text('Total cuotas:', margin + statColW + 2, y + 5.2);
    doc.setFont('helvetica', 'bold');
    doc.setTextColor(15, 23, 42);
    doc.text(String(totalInst), margin + statColW + 20, y + 5.2);

    // Cuotas pagadas
    doc.setFont('helvetica', 'normal');
    doc.setTextColor(71, 85, 105);
    doc.text('Cuotas pagadas:', margin + statColW * 2 + 2, y + 5.2);
    doc.setFont('helvetica', 'bold');
    doc.setTextColor(26, 58, 107);
    doc.text(String(paidInst), margin + statColW * 2 + 24, y + 5.2);

    // Cuotas pendientes
    doc.setFont('helvetica', 'normal');
    doc.setTextColor(71, 85, 105);
    doc.text('Cuotas pendientes:', margin + statColW * 3 + 2, y + 5.2);
    doc.setFont('helvetica', 'bold');
    doc.setTextColor(180, 0, 0);
    doc.text(String(pendingInst), margin + statColW * 3 + 28, y + 5.2);

    y += 11;

    // Tabla de cuotas
    doc.setFillColor(26, 58, 107);
    doc.rect(margin, y, pageW - margin * 2, 7, 'F');
    doc.setTextColor(255, 255, 255);
    doc.setFontSize(8.5);
    doc.setFont('helvetica', 'bold');
    doc.text('N°', margin + 3, y + 5);
    doc.text('Fecha de Vencimiento', margin + 20, y + 5);
    doc.text('Monto USD', margin + 105, y + 5);
    doc.text('Estado', margin + 148, y + 5);
    y += 7;

    doc.setTextColor(0, 0, 0);
    doc.setFont('helvetica', 'normal');
    doc.setFontSize(8);
    invoice.installments.forEach((inst, i) => {
      if (y > pageH - 60) {
        doc.addPage();
        y = 20;
      }
      if (i % 2 === 0) {
        doc.setFillColor(245, 245, 245);
        doc.rect(margin, y, pageW - margin * 2, 6.5, 'F');
      }
      doc.text(String(inst.number || (i + 1)), margin + 3, y + 4.5);
      doc.text(inst.dueDate || '', margin + 20, y + 4.5);
      doc.text('$' + (inst.amountUSD || 0).toFixed(2) + ' USD', margin + 105, y + 4.5);

      const st = inst.status || 'Pendiente';
      if (st === 'Pagada') {
        doc.setTextColor(21, 128, 61);
        doc.setFont('helvetica', 'bold');
      } else if (st === 'Parcialmente pagada') {
        doc.setTextColor(180, 83, 9);
        doc.setFont('helvetica', 'bold');
      } else {
        doc.setTextColor(3, 105, 161);
        doc.setFont('helvetica', 'normal');
      }
      doc.text(st, margin + 148, y + 4.5);
      doc.setTextColor(0, 0, 0);
      doc.setFont('helvetica', 'normal');
      y += 6.5;
    });
    y += 6;
  }

  // CLÁUSULA AL PIE CON QR (Antes de firmas)
  if (cur.type !== 'recibo_pago') {
    if (y + 55 > pageH - 20) {
      doc.addPage();
      y = 20;
    }

    const clauseBoxY = y;
    const clauseBoxH = 26;
    const clauseBoxW = pageW - margin * 2;

    doc.setFillColor(248, 250, 252);
    doc.setDrawColor(203, 213, 225);
    doc.setLineWidth(0.4);
    doc.roundedRect(margin, clauseBoxY, clauseBoxW, clauseBoxH, 1.5, 1.5, 'FD');

    // Acento azul en borde izquierdo
    doc.setFillColor(26, 58, 107);
    doc.rect(margin, clauseBoxY, 1.5, clauseBoxH, 'F');

    // Columna izquierda: QR (aprox. 80x80px -> 21x21 mm)
    const qrSize = 21;
    const qrX = margin + 3.5;
    const qrY = clauseBoxY + (clauseBoxH - qrSize) / 2;

    doc.setFillColor(255, 255, 255);
    doc.rect(qrX - 0.5, qrY - 0.5, qrSize + 1, qrSize + 1, 'F');

    const qrImgEl = document.querySelector('.doc-clause-qr-img') || document.getElementById('invoice-qr-contrato-img');
    let qrRendered = false;
    if (qrImgEl && qrImgEl.complete && qrImgEl.naturalWidth > 0) {
      try {
        doc.addImage(qrImgEl, 'PNG', qrX, qrY, qrSize, qrSize);
        qrRendered = true;
      } catch (err) {
        console.warn("Error dibujando qrImgEl en PDF:", err);
      }
    }
    if (!qrRendered && typeof QR_CONTRATO_BASE64 !== 'undefined' && QR_CONTRATO_BASE64) {
      try {
        doc.addImage(QR_CONTRATO_BASE64, 'PNG', qrX, qrY, qrSize, qrSize);
        qrRendered = true;
      } catch (err) {
        console.warn("Error dibujando QR_CONTRATO_BASE64 en PDF:", err);
      }
    }

    // Columna derecha: Texto de la cláusula
    const textX = qrX + qrSize + 5;
    const textW = (margin + clauseBoxW) - textX - 4;
    doc.setFontSize(8);
    doc.setFont('helvetica', 'normal');
    doc.setTextColor(30, 41, 59);

    const clauseText = "Al recibir esta nota de entrega / factura, usted acepta los términos y condiciones del contrato de financiamiento. En caso de fallar en el pago de alguna de las cuotas acordadas, se pondrá en ejercicio dicho contrato.";
    const splitClause = doc.splitTextToSize(clauseText, textW);
    doc.text(splitClause, textX, clauseBoxY + 7);

    y = clauseBoxY + clauseBoxH + 4;
  }

  // FIRMAS
  if (y + 30 > pageH - 15) {
    doc.addPage();
    y = 20;
  }
  doc.setDrawColor(100, 100, 100);
  doc.setLineWidth(0.4);
  doc.line(margin, y + 12, margin + 70, y + 12);
  doc.line(pageW - margin - 70, y + 12, pageW - margin, y + 12);
  doc.setFontSize(9);
  doc.setTextColor(0, 0, 0);
  doc.text('HOGARFLEX NOELUIS', margin + 35, y + 17, { align: 'center' });
  doc.text('Firma y Sello Comercial', margin + 35, y + 22, { align: 'center' });
  doc.text((invoice.clientName || 'Cliente'), pageW - margin - 35, y + 17, { align: 'center' });
  doc.text('Conforme / Firma del Cliente', pageW - margin - 35, y + 22, { align: 'center' });

  // PIE — línea dorada (ajustada al alto de hoja carta 279.4mm)
  const footerLineY = pageH - 10;
  doc.setDrawColor(245, 196, 0);
  doc.setLineWidth(2);
  doc.line(0, footerLineY, pageW, footerLineY);
  doc.setFontSize(8);
  doc.setTextColor(100, 100, 100);
  doc.text('Condición de financiamiento: El cliente se compromete a cancelar las cuotas en las fechas acordadas.', pageW / 2, footerLineY + 5, { align: 'center' });

  // Forzar descarga con extensión .pdf correcta usando <a> element:
  const blob = doc.output('blob');
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = 'Factura_HOGARFLEX_' + (invoice.invoiceNumber || 'FAC') + '.pdf';
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  setTimeout(() => URL.revokeObjectURL(url), 1000);
}


// Renderizar la sección completa de Facturación
function renderFacturacionSection() {
  const tbody = document.getElementById("invoices-tbody");
  const emptyMsg = document.getElementById("empty-invoices-msg");
  const table = document.getElementById("invoices-table");
  if (!tbody || !emptyMsg || !table) return;

  const invoices = getStoredInvoices();

  // Actualizar métricas KPI superiores
  const totalDocsEl = document.getElementById("kpi-inv-total-docs");
  const breakdownEl = document.getElementById("kpi-inv-docs-breakdown");
  const creditAmountEl = document.getElementById("kpi-inv-total-credit-amount");
  const receiptsAmountEl = document.getElementById("kpi-inv-total-receipts-amount");

  const totalFacturas = invoices.filter((d) => d.type === "factura_credito");
  const totalRecibos = invoices.filter((d) => d.type === "recibo_pago");

  const sumCreditUSD = totalFacturas.reduce((acc, d) => acc + (parseFloat(d.totalAmountUSD) || 0), 0);
  const sumReceiptsUSD = totalRecibos.reduce((acc, d) => acc + (parseFloat(d.totalAmountUSD) || 0), 0);

  if (totalDocsEl) totalDocsEl.textContent = invoices.length;
  if (breakdownEl) breakdownEl.textContent = `${totalFacturas.length} Facturas · ${totalRecibos.length} Recibos`;
  if (creditAmountEl) creditAmountEl.textContent = `$${sumCreditUSD.toFixed(2)}`;
  if (receiptsAmountEl) receiptsAmountEl.textContent = `$${sumReceiptsUSD.toFixed(2)}`;

  // Ordenar por fecha cronológicamente (más reciente primero)
  invoices.sort((a, b) => new Date(b.date || b.createdAt || 0).getTime() - new Date(a.date || a.createdAt || 0).getTime());

  // Filtrar según búsqueda y tipo
  const filtered = invoices.filter((doc) => {
    // Filtro por tipo
    if (currentInvoicesTypeFilter !== "all" && doc.type !== currentInvoicesTypeFilter) {
      return false;
    }

    // Filtro de búsqueda
    if (currentInvoicesSearchQuery) {
      const clientName = (doc.client && doc.client.name ? doc.client.name : "").toLowerCase();
      const clientDni = (doc.client && doc.client.dni ? doc.client.dni : "").toLowerCase();
      const docNum = (doc.docNumber || "").toLowerCase();
      if (!clientName.includes(currentInvoicesSearchQuery) && !clientDni.includes(currentInvoicesSearchQuery) && !docNum.includes(currentInvoicesSearchQuery)) {
        return false;
      }
    }

    return true;
  });

  if (filtered.length === 0) {
    tbody.innerHTML = "";
    table.classList.add("hidden");
    emptyMsg.classList.remove("hidden");
    const btnDeleteAll = document.getElementById("btn-delete-all-invoices");
    if (btnDeleteAll) btnDeleteAll.disabled = (invoices.length === 0);
    updateSelectedInvoicesButton();
    return;
  }

  emptyMsg.classList.add("hidden");
  table.classList.remove("hidden");

  const btnDeleteAll = document.getElementById("btn-delete-all-invoices");
  if (btnDeleteAll) btnDeleteAll.disabled = (invoices.length === 0);

  tbody.innerHTML = filtered.map((doc) => {
    const dateObj = new Date(doc.date || doc.createdAt || Date.now());
    const dateStr = formatDateDisplay(dateObj);
    const timeStr = (!isNaN(dateObj.getTime()) && String(doc.date).includes("T"))
      ? dateObj.toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" })
      : "";

    const typeBadge = doc.type === "factura_credito"
      ? '<span class="badge-factura">📄 Factura crédito</span>'
      : '<span class="badge-recibo">🧾 Recibo pago</span>';

    const bsStr = doc.totalAmountBs && doc.totalAmountBs > 0
      ? `<br><small style="color: #64748b;">(Bs. ${formatBs(doc.totalAmountBs)})</small>`
      : "";

    return `
      <tr>
        <td style="width: 44px; text-align: center;">
          <input type="checkbox" class="invoice-row-checkbox" data-id="${doc.id}" style="width: 17px; height: 17px; cursor: pointer;">
        </td>
        <td>
          <strong>${dateStr}</strong>
          ${timeStr ? `<small style="color: var(--color-text-muted); display: block;">${timeStr}</small>` : ''}
        </td>
        <td>
          <code style="font-weight: 700; font-size: 0.92rem; color: var(--color-primary);">${escapeHtml(doc.docNumber)}</code>
        </td>
        <td>
          <strong>${escapeHtml(doc.client.name)}</strong><br>
          <small style="color: var(--color-text-muted);">C.I. ${escapeHtml(doc.client.dni)} · ${escapeHtml(doc.client.phone || '-')}</small>
        </td>
        <td>
          ${typeBadge}
        </td>
        <td>
          <strong style="font-size: 0.95rem; color: #1e293b;">$${parseFloat(doc.totalAmountUSD).toFixed(2)} USD</strong>
          ${bsStr}
        </td>
        <td style="text-align: right;">
          <div style="display: flex; gap: 6px; justify-content: flex-end; flex-wrap: wrap;">
            <button type="button" class="btn-action-view btn-action-view-inv" data-id="${doc.id}" title="Ver documento">👁️ Ver</button>
            <button type="button" class="btn-action-receipt btn-action-wa-inv" data-id="${doc.id}" style="background: #25d366;" title="Compartir por WhatsApp">📲 WhatsApp</button>
            <button type="button" class="btn-action-delete-inv" data-id="${doc.id}" title="Eliminar factura" style="background: #fee2e2; color: #dc2626; border: 1px solid #fca5a5; padding: 5px 10px; border-radius: 6px; font-size: 0.8rem; font-weight: 600; cursor: pointer; display: inline-flex; align-items: center; gap: 4px;">🗑️ Eliminar</button>
          </div>
        </td>
      </tr>
    `;
  }).join("");

  updateSelectedInvoicesButton();
}

// Exportar al objeto window
window.initFacturacionModule = initFacturacionModule;
window.renderFacturacionSection = renderFacturacionSection;
window.generateAndOpenCreditInvoice = generateAndOpenCreditInvoice;
window.generateAndOpenPaymentReceipt = generateAndOpenPaymentReceipt;
window.openInvoicePreviewModal = openInvoicePreviewModal;
window.closeInvoicePreviewModal = closeInvoicePreviewModal;
window.shareDocViaWhatsApp = shareDocViaWhatsApp;
window.printInvoiceDoc = printInvoiceDoc;
window.openDeleteInvoiceModal = openDeleteInvoiceModal;
window.closeDeleteInvoiceModal = closeDeleteInvoiceModal;
window.executeFinalInvoiceDeletion = executeFinalInvoiceDeletion;
window.updateSelectedInvoicesButton = updateSelectedInvoicesButton;

