// Toast flotante para feedback de sincronización en cualquier pantalla
let cloudToastTimer = null;
function showCloudSyncToast(message, type = "info") {
  const toast = document.getElementById("cloud-sync-toast");
  const toastText = document.getElementById("cloud-sync-toast-text");
  const toastIcon = document.getElementById("cloud-sync-toast-icon");
  if (!toast || !toastText) return;

  if (cloudToastTimer) {
    clearTimeout(cloudToastTimer);
    cloudToastTimer = null;
  }

  toastText.textContent = message;
  toast.className = "cloud-toast show";

  if (type === "success") {
    toast.style.background = "#f0fdf4";
    toast.style.border = "1px solid #86efac";
    toast.style.color = "#15803d";
    if (toastIcon) toastIcon.textContent = "✅";
  } else if (type === "error") {
    toast.style.background = "#fef2f2";
    toast.style.border = "1px solid #fca5a5";
    toast.style.color = "#b91c1c";
    if (toastIcon) toastIcon.textContent = "❌";
  } else {
    toast.style.background = "#eff6ff";
    toast.style.border = "1px solid #93c5fd";
    toast.style.color = "#1d4ed8";
    if (toastIcon) toastIcon.textContent = "⏳";
  }

  if (type !== "info") {
    cloudToastTimer = setTimeout(() => {
      toast.classList.remove("show");
    }, 4500);
  }
}

// EXPORTAR FOTOS DE PRODUCTOS A GOOGLE DRIVE VÍA APPS SCRIPT (HogarFlex_Productos)
async function exportProductImagesToGoogleDrive(isSilent = true) {
  const scriptUrl = getAppsScriptUrl();
  if (!scriptUrl || !navigator.onLine) return 0;

  try {
    const products = getStoredProducts();
    const productsWithPhoto = products.filter((p) => p.photo && p.photo.startsWith("data:image"));
    if (productsWithPhoto.length === 0) return 0;

    let uploadedCount = 0;
    for (const prod of productsWithPhoto) {
      try {
        const res = await fetch(scriptUrl, {
          method: "POST",
          body: JSON.stringify({
            action: "upload_product_image",
            productId: prod.id,
            fileName: `producto_${prod.id}.jpg`,
            base64: prod.photo
          })
        });
        if (res.ok) {
          const json = await res.json();
          const isSuccess = json && (json.status === "success" || json.success === true);
          if (isSuccess && !json.alreadyExists) {
            uploadedCount++;
          }
        }
      } catch (err) {
        console.warn("Error al subir foto de producto a Drive:", prod.id, err);
      }
    }
    if (uploadedCount > 0) {
      console.log(`[HogarFlex Drive] ✅ ${uploadedCount} fotos de productos sincronizadas en HogarFlex_Productos.`);
    }
    return uploadedCount;
  } catch (err) {
    console.error("Error al exportar fotos de productos a Drive:", err);
    return 0;
  }
}

// EXPORTAR ARCHIVOS A GOOGLE DRIVE VÍA APPS SCRIPT (Comprobantes y Fotos)
async function exportReceiptsToGoogleDrive() {
  if (isExportingReceipts) return;

  if (!navigator.onLine) {
    showReceiptsStatus("Sin conexión. El respaldo se hará cuando vuelva el internet.", "error");
    return;
  }

  const scriptUrl = getAppsScriptUrl();
  if (!scriptUrl) {
    alert("Por favor configura la URL de Google Apps Script antes de exportar.");
    return;
  }

  isExportingReceipts = true;
  const exportBtn = document.getElementById("btn-export-receipts");

  showReceiptsStatus("⏳ Sincronizando comprobantes y fotos de productos en Google Drive...", "info");
  if (exportBtn) exportBtn.setAttribute("disabled", "true");

  try {
    const credits = getStoredCredits();
    const receiptsToUpload = [];

    const monthNames = [
      "01_Enero", "02_Febrero", "03_Marzo", "04_Abril",
      "05_Mayo", "06_Junio", "07_Julio", "08_Agosto",
      "09_Septiembre", "10_Octubre", "11_Noviembre", "12_Diciembre"
    ];

    credits.forEach((cr) => {
      const clientDni = (cr.client?.dni || "V0").replace(/[^a-zA-Z0-9]/g, "");
      const clientName = (cr.client?.name || "Cliente").replace(/\s+/g, "_").replace(/[^a-zA-Z0-9_]/g, "");
      (cr.payments || []).forEach((p) => {
        if (p.receiptUrl && p.receiptUrl.startsWith("data:image")) {
          const dateObj = new Date(p.date || Date.now());
          const mIndex = dateObj.getMonth();
          const monthFolder = monthNames[mIndex] || "00_Varios";
          const dateStr = p.date ? String(p.date).split("T")[0] : "fecha";
          const fileName = `PAGO_${clientDni}_${clientName}_${dateStr}.jpg`;

          receiptsToUpload.push({
            fileName,
            monthFolder,
            base64: p.receiptUrl
          });
        }
      });
    });

    let uploadedReceiptsCount = 0;
    for (const item of receiptsToUpload) {
      try {
        const res = await fetch(scriptUrl, {
          method: "POST",
          body: JSON.stringify({
            action: "upload_receipt",
            fileName: item.fileName,
            monthFolder: item.monthFolder,
            base64: item.base64
          })
        });
        if (res.ok) {
          const json = await res.json();
          const isSuccess = json && (json.status === "success" || json.success === true);
          if (isSuccess && !json.alreadyExists) {
            uploadedReceiptsCount++;
          }
        }
      } catch (uploadErr) {
        console.warn("Error subiendo comprobante individual:", item.fileName, uploadErr);
      }
    }

    // Sincronizar también fotos de productos a HogarFlex_Productos
    const uploadedPhotosCount = await exportProductImagesToGoogleDrive(false);

    if (uploadedReceiptsCount > 0 || uploadedPhotosCount > 0) {
      showReceiptsStatus(`✅ Sincronizados en Drive: ${uploadedReceiptsCount} comprobante(s) y ${uploadedPhotosCount} foto(s) de productos.`, "success");
    } else {
      showReceiptsStatus(`✅ Todos los comprobantes y fotos ya estaban sincronizados en Google Drive.`, "success");
    }
  } catch (err) {
    console.error("Error al exportar archivos a Drive vía Apps Script:", err);
    showReceiptsStatus(`Error: ${err.message || err}`, "error");
  } finally {
    isExportingReceipts = false;
    if (exportBtn) exportBtn.removeAttribute("disabled");
  }
}

